export const OVERLAYS = {"equine-medicine--equine-gi":{"equine-medicine--equine-gi--กายวิภาคทางเดินอาหารม้า":{"claims":[{"id":"equine-medicine--equine-gi--กายวิภาคทางเดินอาหารม้า--v1","statement":"ม้าเป็นสัตว์ที่หมักอาหารในลำไส้ใหญ่ (hindgut fermenter) โดย cecum และ colon ทำหน้าที่ย่อยและหมักไฟเบอร์ด้วยจุลชีพเพื่อให้พลังงานแก่ร่างกาย และจุลชีพเหล่านี้ยังมีบทบาทในการป้องกันโรคของลำไส้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27285903","locator":"Vol 94(6), pp. 2262-2274, Abstract and section 1","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Its vital role in hydrolyzing and fermenting fiber, thus providing energy to the host, was recognized. Although there was a critical lack of information on the hindgut microbes, their role in preventing intestinal diseases was suggested."}}]},"equine-medicine--equine-gi--กระเพาะอาหาร":{"claims":[{"id":"equine-medicine--equine-gi--กระเพาะอาหาร--v1","statement":"กระเพาะม้าแบ่งเป็นเยื่อบุ squamous และ glandular จริง โดยแผลของ squamous mucosa อยู่ใกล้ margo plicatus ในทุกเคสที่ตรวจ (100%) ส่วนแผลของ glandular mucosa อยู่ที่ fundus และ pylorus ซึ่งยืนยันว่า pyloric region เป็นตำแหน่งที่พบความผิดปกติได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17555289","locator":"Vol 55(2), pp. 241-249, Results and Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In all horses the squamous mucosa lesions were localised near the margo plicatus (100% of the cases)... Lesions of the glandular mucosa were localised in 11 horses at the fundic area, in 1 horse they occurred in the pylorus"}}]},"equine-medicine--equine-gi--ลำไส้และลำดับการเรียงตัวของ-colon":{"claims":[{"id":"equine-medicine--equine-gi--ลำไส้และลำดับการเรียงตัวของ-colon--v1","statement":"Pelvic flexure เป็นจุดที่ลำไส้ใหญ่แคบลงกะทันหัน จึงเป็นตำแหน่งคลาสสิกของ impaction ตามหลักที่ว่า impaction เกิดที่บริเวณซึ่งเส้นผ่านศูนย์กลางของลำไส้ลดลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19580942","locator":"Vol 25(2), pp. 317-327, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"An impaction is an accumulation of dehydrated ingesta in a portion of the digestive tract, typically at sites where the intestinal diameter decreases."}}]},"equine-medicine--equine-gi--choke":{"claims":[{"id":"equine-medicine--equine-gi--choke--v1","statement":"สาเหตุหลักของ esophageal obstruction ในม้าคือการอุดตันด้วยอาหารที่กินเข้าไป โดยพบ 28 จาก 34 เคส ตรงกับที่สไลด์ระบุว่าเกิดจากการเคี้ยวไม่ละเอียดและกินหญ้าแห้ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10738598","locator":"Vol 41(3), pp. 207-210, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Of 34 cases presenting with esophageal obstruction, 28 cases were due to impaction of ingesta."}},{"id":"equine-medicine--equine-gi--choke--v2","statement":"ยิ่งปล่อยให้ choke อยู่นานก่อนเข้ารับการรักษา ยิ่งเสี่ยง aspiration pneumonia โดยม้าที่เกิดปอดอักเสบจากการสำลักมีระยะเวลาอุดตันก่อนมาถึงโรงพยาบาลนานกว่าอย่างมีนัยสำคัญ (มัธยฐาน 18 ชั่วโมง เทียบกับ 4 ชั่วโมง) ซึ่งเป็นภาวะแทรกซ้อนสำคัญที่สไลด์ไม่ได้กล่าวถึง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10738598","locator":"Vol 41(3), pp. 207-210, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The duration of esophageal obstruction prior to admission was significantly longer in horses that developed aspiration pneumonia (median 18, range 2-48 h) than in those horses that did not (median 4, range 0.5-48 h)."}}]},"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus":{"claims":[{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v1","statement":"คำเรียก ESGD (equine squamous gastric disease) และ EGGD (equine glandular gastric disease) เป็นคำที่ ECEIM consensus แนะนำให้ใช้ เพราะระบุตำแหน่งกายวิภาคของเยื่อบุที่เป็นโรคได้ตรงกว่าคำว่า EGUS เฉย ๆ ตรงกับที่สไลด์แบ่งไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26340142","locator":"Vol 29(5), pp. 1288-1299, Terminology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine Squamous Gastric Disease (ESGD) and Equine Glandular Gastric Disease (EGGD) as terms that more specifically describe the affected region anatomically."}},{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v2","statement":"การอดอาหารเป็นช่วง ๆ (intermittent starvation) ทำให้เกิดและทำให้ ESGD รุนแรงขึ้น และการกินแป้งเกิน 2 กรัมต่อกิโลกรัมน้ำหนักตัวต่อวันเพิ่มโอกาสเกิด ESGD ราวสองเท่า ยืนยัน risk factor เรื่องอดอาหารและอาหารที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26340142","locator":"Vol 29(5), pp. 1288-1299, Risk factors for ESGD","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Intermittent starvation causes and increases the severity of ESGD... Exceeding 2 g/kg BW of starch intake per day is associated with an approximately 2-fold increase in the likelihood of ESGD."}},{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v3","statement":"การไม่มีน้ำให้กินในแปลงเป็นปัจจัยเสี่ยงที่วัดได้จริง โดยม้าที่ไม่มีน้ำให้เข้าถึงในแปลงมีโอกาสเป็น EGUS ระดับตั้งแต่ 2 ใน 5 ขึ้นไป มากกว่า 2.5 เท่า ซึ่งเป็นเหตุผลเชิงหลักฐานที่การจัดการน้ำถูกจัดเป็นปัจจัยป้องกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26340142","locator":"Vol 29(5), pp. 1288-1299, Risk factors","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses without access to water in their paddock are more than 2.5 times more likely to have EGUS >= 2/5."}},{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v4","statement":"Omeprazole ยังคงเป็นยาที่เลือกใช้เป็นอันดับแรกในการรักษา EGUS ด้วยกลไกกดการหลั่งกรด ตรงกับที่สไลด์ระบุว่า Tx คือ acid suppression ด้วย omeprazole ร่วมกับการจัดการ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26340142","locator":"Vol 29(5), pp. 1288-1299, Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Omeprazole remains the drug of choice for treatment of EGUS"}},{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v5","statement":"การให้ alfalfa (lucerne) hay ร่วมกับอาหารข้น ทำให้ค่า pH ในกระเพาะสูงกว่าและมีการบาดเจ็บจากกรดที่เยื่อบุ squamous น้อยกว่าการให้ brome grass hay หรือ coastal Bermuda hay ที่ไม่มีอาหารข้น ซึ่งสนับสนุนคำแนะนำให้ใช้ alfalfa","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26340142","locator":"Vol 29(5), pp. 1288-1299, Dietary management","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Feeding alfalfa hay and grain results in higher gastric pH and less peptic injury to the gastric squamous mucosa than feeding brome grass hay or coastal Bermuda hay with no grain."}},{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v6","statement":"ระบบให้เกรดแผลในกระเพาะสัตว์ตระกูลม้าใช้สเกล 0 ถึง 4 ตามความรุนแรง โดยเกรดตั้งแต่ 2 ขึ้นไปถือว่ามีนัยสำคัญทางคลินิก ตรงกับที่สไลด์แบ่ง Grade 0 ถึง Grade 4 และแยก Grade 2-3 ว่าเยื่อบุแหว่งแล้ว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37559426","locator":"Vol 56(3), pp. 449-455, Methods","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The animals underwent gastroscopic evaluation, and ulcer scores from 0 to 4 were assigned based on severity, with scores >= 2 indicating clinical relevance."}},{"id":"equine-medicine--equine-gi--equine-gastric-ulcer-syndrome-egus--v7","statement":"แผลของเยื่อบุ squamous พบบ่อยกว่าแผลของเยื่อบุ glandular ในม้าจริง โดยจากม้า 52 ตัวที่มีแผลในกระเพาะ ทุกตัวมีแผลที่ squamous mucosa ใกล้ margo plicatus ส่วนแผล glandular พบราว 22 ตัว สนับสนุนที่สไลด์ระบุว่า EGGD พบไม่บ่อยเท่า ESGD แต่ผู้เขียนย้ำว่า glandular lesion ก็พบได้ทั่วไปในม้าโตและควรส่องกล้องดู pylorus ให้ครบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17555289","locator":"Vol 55(2), pp. 241-249, Results and Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lesions of the glandular mucosa are also common in adult horses, and a complete gastroscopic examination including examination of the pylorus is advisable to evaluate this syndrome."}}]},"equine-medicine--equine-gi--gut-sound-4-ตำแหน่ง":{"claims":[{"id":"equine-medicine--equine-gi--gut-sound-4-ตำแหน่ง--v1","statement":"การฟังเสียงลำไส้ในม้าที่มีอาการปวดท้องประเมินเป็นราย quadrant และให้คะแนนรวม (gastrointestinal auscultation score 0-12) โดยการไม่ได้ยินเสียงลำไส้ตั้งแต่ 1 quadrant ขึ้นไป สัมพันธ์กับการเป็นเคส colic ชนิดวิกฤต (OR 3.65) จึงยืนยันว่าการแบ่งฟังเป็นรายตำแหน่งมีความหมายทางคลินิกจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26444675","locator":"Results, multivariable model; 57:69","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"absence of gut sounds in ≥1 quadrant (OR 3.65, P < 0.001, 95 % CI 2.08-6.41)"}}]},"equine-medicine--equine-gi--nasogastric-intubation":{"claims":[{"id":"equine-medicine--equine-gi--nasogastric-intubation--v1","statement":"การสำรวจ Diplomate ของ ACVIM, ACVS และ ACVECC ยืนยันว่า การพบ reflux จากการใส่ nasogastric tube คือเกณฑ์หลักที่ใช้นิยาม postoperative ileus และรอยโรคที่เกี่ยวข้องกับลำไส้เล็กคือปัจจัยเสี่ยงหลัก จึงสนับสนุนว่าสิ่งที่ดูดออกมาได้ (gastric reflux) เป็นตัวบ่งชี้ปัญหาของลำไส้เล็กตามที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26502215","locator":"เล่ม 48 ฉบับ 6 หน้า 714-719, Abstract ส่วนผลการสำรวจ","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The presence of reflux on nasogastric intubation was the main criterion used to define POI. A lesion involving the small intestine was considered the main risk factor for POI."}}]},"equine-medicine--equine-gi--กายวิภาคและเส้นทางของอาหาร":{"claims":[{"id":"equine-medicine--equine-gi--กายวิภาคและเส้นทางของอาหาร--v1","statement":"ม้าไม่มีถุงน้ำดี น้ำดีหลั่งตรงจากตับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-digestive-system-2024","locator":"Small intestine","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Bile is continuously secreted by the liver as the horse doesn’t have a gall bladder in which to store it."}}]},"equine-medicine--equine-gi--การตรวจ-ฟัง-gut-sound-4-ตำแหน่ง":{"claims":[{"id":"equine-medicine--equine-gi--การตรวจ-ฟัง-gut-sound-4-ตำแหน่ง--v1","statement":"การไม่ได้ยินเสียงลำไส้อาจบ่งชี้การเคลื่อนไหวของลำไส้บกพร่องหรือเลือดไปเลี้ยงไม่พอ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"The Veterinarian's Examination of a Horse with Colic (table), auscultation","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lack of sounds may indicate impaired motility or blood flow."}}]},"equine-medicine--equine-gi--การตรวจ-ultrasound-radiography-และ-rectal-palpation":{"claims":[{"id":"equine-medicine--equine-gi--การตรวจ-ultrasound-radiography-และ-rectal-palpation--v1","statement":"FLASH เป็นโปรโตคอลอัลตราซาวด์ช่องท้องที่ตำแหน่งภายนอก 7 จุดในม้า colic ซึ่งเห็นของเหลวอิสระและลำไส้ผิดปกติได้ และสัตวแพทย์ที่ไม่ชำนาญก็ใช้ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20347357","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"FLASH was able to show free abdominal fluid and abnormal intestinal loops, with a mean time of 10.7 min required to complete the protocol."}}]},"equine-medicine--equine-gi--choke-และ-equine-gastric-ulcer-syndrome-egus":{"claims":[{"id":"equine-medicine--equine-gi--choke-และ-equine-gastric-ulcer-syndrome-egus--v1","statement":"EGUS เป็นคำรวมของรอยโรคที่หลอดอาหารส่วนปลาย กระเพาะส่วน nonglandular และ glandular และ duodenum ส่วนต้น และการส่องกล้องกระเพาะตอนท้องว่างเป็นวิธีวินิจฉัยที่ชัดเจนเพียงวิธีเดียว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-gastric-ulcers-in-horses-2026","locator":"Gastric Ulcers in Horses, Overview and Diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Gastroscopic visualization of the ulcers in an empty stomach is the only definitive method of diagnosis."}}]}},"equine-medicine--equine-colic-bestfit":{"equine-medicine--equine-colic-bestfit--สาเหตุและ-predisposing-factors":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--สาเหตุและ-predisposing-factors--v1","statement":"งานวิจัย case control ยืนยัน predisposing factors ของ colic ชนิด simple colonic obstruction and distension ได้หลายข้อที่ตรงกับสไลด์ ได้แก่ พฤติกรรมกินลม (crib-biting/windsucking), จำนวนชั่วโมงที่อยู่ในคอกมากขึ้น, การเปลี่ยนโปรแกรมออกกำลังกายกะทันหัน, การไม่ได้ถ่ายพยาธิด้วย ivermectin หรือ moxidectin ใน 12 เดือนที่ผ่านมา, การขนส่งภายใน 24 ชั่วโมง และการตรวจฟันไม่บ่อย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12358047","locator":"Vol 34(5), pp. 455-463, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"identified crib-biting or windsucking, an increasing number of hours spent in a stable, a recent change in a regular exercise programme, the absence of administration of an ivermectin or moxidectin anthelmintic in the previous 12 months and"}}]},"equine-medicine--equine-colic-bestfit--blood-lactate-และ-ultrasound":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--blood-lactate-และ-ultrasound--v1","statement":"ค่า lactate ใน peritoneal fluid ที่สูงกว่าค่า lactate ในเลือดที่เจาะพร้อมกัน บ่งชี้ intestinal strangulation และ ischaemia จึงให้ข้อมูลที่การเจาะเลือดอย่างเดียวให้ไม่ได้ สนับสนุนที่สไลด์บอกว่าเจาะ peritoneal fluid ให้ข้อมูลดีกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22271469","locator":"Vol 34(1), E2, section on cavity fluid lactate","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In horses evaluated for colic, a peritoneal lactate concentration higher than the simultaneously measured blood lactate concentration is indicative of intestinal strangulation and ischemia."}},{"id":"equine-medicine--equine-colic-bestfit--blood-lactate-และ-ultrasound--v2","statement":"Blood lactate ใช้พยากรณ์โรคใน colic ได้จริง โดยค่าจะสูงขึ้นตามระดับความเสียหายของลำไส้ และค่ามากกว่า 4 mmol/L บ่งชี้พยากรณ์โรค guarded","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23608894","locator":"Vol 41(2), pp. 124-134, clinical pathology section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the blood lactate concentration rises with increasing intestinal compromise with a concentration of > 4 mmol/l indicating a guarded prognosis"}},{"id":"equine-medicine--equine-colic-bestfit--blood-lactate-และ-ultrasound--v3","statement":"หน้าต่างทรวงอกเป็นหนึ่งใน 7 ตำแหน่งของ FLASH จริง และการมองไม่เห็นไตซ้ายระหว่างซาวน์สัมพันธ์กับการวินิจฉัย left dorsal displacement ของ large colon ซึ่งตรงกับที่สไลด์บอกว่าต้องซาวน์ช่องอกด้วย และตรงกับภาพซาวน์ของ nephrosplenic entrapment","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38239746","locator":"Vol 10, 1307938, Methods and Discussion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Using FLASH 7 areas were evaluated on each horse: Ventral abdomen, left cranial abdomen, caudal dorsal and ventral abdomen (left and right) and the right thorax... Detection of the left kidney during FLASH is important since failure to imag"}},{"id":"equine-medicine--equine-colic-bestfit--blood-lactate-และ-ultrasound--v4","statement":"Diaphragmatic hernia เกิดในม้าได้จริงและมักมาด้วยอาการปวดท้องเฉียบพลัน จึงมีเหตุผลที่ต้องมองช่องอกส่วนหน้าล่างในเคส colic","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34670696","locator":"Vol 106, 103746, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Diaphragmatic hernia (DH) represents an acute abdominal crisis, but respiratory symptoms may be occurring... Diagnostic challenges include inconsistent clinical signs of DH, acute nature of the associated colic"}}]},"equine-medicine--equine-colic-bestfit--การแปลผล-ng-tube-ในการวินิจฉัย-colic":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--การแปลผล-ng-tube-ในการวินิจฉัย-colic--v1","statement":"การพบ reflux จากการใส่ NG tube เป็นเกณฑ์หลักที่ใช้นิยาม postoperative ileus และรอยโรคที่ลำไส้เล็กถูกมองว่าเป็นปัจจัยเสี่ยงอันดับต้นของภาวะนี้ ซึ่งสนับสนุนการแปลผลในสไลด์ที่ว่า gastric reflux ชี้ไปที่ปัญหาของลำไส้เล็ก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25256601","locator":"Vol 48(2), pp. 182-187, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The presence of reflux on nasogastric intubation was the main criterion used to define POI. Lesions involving the small intestine were thought to be the leading risk factors for developing POI."}}]},"equine-medicine--equine-colic-bestfit--composite-colic-score-ccs":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--composite-colic-score-ccs--v1","statement":"หลักการของ composite colic score ใช้ได้จริงและมีการ validate มาแล้ว โดย Equine Utrecht University Scale for Composite Pain Assessment (EQUUS-COMPASS) มีค่าตัดสำหรับแยกม้าที่รักษาแบบ conservative ออกจากม้าที่ต้องผ่าตัดหรือการุณยฆาต ด้วย sensitivity 95.8% และ specificity 84.0%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26526526","locator":"Vol 206(3), pp. 356-364, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Internal sensitivity and specificity were good for both EQUUS-COMPASS (sensitivity 95.8%, specificity 84.0%)"}},{"id":"equine-medicine--equine-colic-bestfit--composite-colic-score-ccs--v2","statement":"คำเตือนของเด็คที่ว่าอย่าเชื่อคะแนนอย่างเดียวมีน้ำหนัก เพราะสเกลประเมินความปวด colic ต่างชนิดกันให้ความเที่ยงระหว่างผู้ตรวจต่างกันมาก (ICC 0.68 ถึง 0.86) จึงยังต้องอาศัยการประเมินตัวม้าจริงประกอบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30902193","locator":"Vol 246, pp. 71-77, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The intraclass correlation (ICC) of 0.86 [95% confidence interval (CI); 0.80-0.92] for EAAPS indicated significantly better inter-observer reliability compared to 0.68 for the M and S and 0.71 for the NRS."}}]},"equine-medicine--equine-colic-bestfit--tx-of-choice":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--tx-of-choice--v1","statement":"Buscopan ยับยั้งการบีบตัวของกล้ามเนื้อเรียบ ileum ของม้าทั้งแบบ spontaneous และแบบที่ถูกกระตุ้นด้วย cholinergic ยืนยันกลไก smooth muscle relaxant ที่สไลด์บรรยายไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24779926","locator":"Vol 47(4), pp. 450-455, Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"N-butylscopolammonium bromide inhibits spontaneous and cholinergically mediated contraction in equine ileal smooth muscle strips ex vivo."}},{"id":"equine-medicine--equine-colic-bestfit--tx-of-choice--v2","statement":"ต้องระวังการใช้ Buscopan ในม้า colic ที่มีระบบไหลเวียนโลหิตทรุด เพราะ N-butylscopolammonium bromide ทำให้ heart rate และความดันเลือดสูงขึ้นทันทีหลังฉีด และพบ sinus tachycardia จึงบดบังการประเมินความรุนแรงและพยากรณ์โรคจาก HR ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21790765","locator":"Suppl 39, pp. 117-122, Results and Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Heart rate and blood pressure were significantly elevated immediately following administration of NBB or NBB with xylazine... the effects of administration of NBB alone or in combination with xylazine to horses with colic, especially to tho"}},{"id":"equine-medicine--equine-colic-bestfit--tx-of-choice--v3","statement":"ขนาด flunixin meglumine 1.1 mg/kg ให้ทางหลอดเลือดดำทุก 12 ชั่วโมง เป็นขนาดที่ใช้จริงในงานวิจัยทางคลินิกกับม้าผ่าตัดลำไส้เล็ก และ flunixin บดบังอาการปวดได้มากกว่า meloxicam อย่างมีนัยสำคัญ ซึ่งยืนยันข้อควรระวังเรื่อง masking ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24372991","locator":"Vol 46(4), pp. 427-434, Methods and Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses received either 1.1 mg/kg bwt FM or 0.6 mg/kg bwt meloxicam i.v. q. 12 h... Blinded pain score evaluation showed that more horses receiving meloxicam showed gross signs of pain than those treated with FM (P = 0.04)."}},{"id":"equine-medicine--equine-colic-bestfit--tx-of-choice--v4","statement":"เมื่อเกิดลำไส้แตกและมีอุจจาระปนเปื้อนช่องท้อง พยากรณ์โรคของ septic peritonitis แย่ลงอย่างชัดเจน โดยอัตราการรักษาสำเร็จเหลือ 40% เทียบกับ 84.6% และ 87.5% ในกลุ่มที่ไม่มีการแตกทะลุ สนับสนุนที่สไลด์บอกว่า GI rupture เป็นจุดพิจารณาการุณยฆาต","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32234866","locator":"Vol 187(4), e29, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mean success rate of the treatment was 77 per cent (20/26 animals), with success rates of 84.6 per cent in group 1; 87.5 per cent, group 2; and 40 per cent, group 3."}}]},"equine-medicine--equine-colic-bestfit--colic-แต่ละชนิดที่เด็คสรุปไว้":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--colic-แต่ละชนิดที่เด็คสรุปไว้--v1","statement":"ปัจจัยเสี่ยงของ colic ชนิด simple colonic obstruction and distension ที่มีผลมากที่สุด 3 ข้อคือ การขังคอก 24 ชั่วโมงต่อวัน, พฤติกรรม crib-biting หรือ windsucking และการขนส่งภายใน 24 ชั่วโมงที่ผ่านมา ซึ่งสนับสนุนคำอธิบายในสไลด์ว่า pelvic flexure impaction มักเกิดในม้าที่ไม่ได้เคลื่อนไหว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12358047","locator":"Vol 34(5), pp. 455-463, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Three of the risk factors in this model were associated with a large increase in risk: stabling for 24 h/day, crib-biting/windsucking and travel in the previous 24 h."}},{"id":"equine-medicine--equine-colic-bestfit--colic-แต่ละชนิดที่เด็คสรุปไว้--v2","statement":"Impaction คือการสะสมของอาหารที่ขาดน้ำในทางเดินอาหาร โดยเกิดที่ตำแหน่งที่เส้นผ่านศูนย์กลางลำไส้แคบลง ซึ่งอธิบายว่าทำไม pelvic flexure จึงเป็นจุดเกิด impaction บ่อย และการรักษาคือหยุดอาหาร เติมน้ำให้ ingesta และผ่าตัดในรายรุนแรง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19580942","locator":"Vol 25(2), pp. 317-327, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"An impaction is an accumulation of dehydrated ingesta in a portion of the digestive tract, typically at sites where the intestinal diameter decreases. ... Treatment for impactions includes withholding feed until the impaction passes, rehydr"}}]},"equine-medicine--equine-colic-bestfit--vital-signs-ในเคส-colic":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--vital-signs-ในเคส-colic--v1","statement":"มี composite pain scale ที่สร้างและตรวจสอบสำหรับม้าที่มี acute colic โดยเฉพาะ (EQUUS-COMPASS) ใช้ให้คะแนนความเจ็บซ้ำได้อย่างเป็นภววิสัย โดยค่าตัดสิน 5 แยกม้าปกติออกจากม้า colic และค่า 11 แยกกลุ่มที่รักษาแบบประคับประคองออกจากกลุ่มที่ต้องผ่าตัดหรือการุณยฆาต (ความเที่ยงระหว่างผู้สังเกต ICC 0.98) รองรับที่สไลด์ระบุว่าประเมินความเจ็บปวดด้วย composite colic score","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26526526","locator":"Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The cut-off value for differentiation between healthy and colic horses for the EQUUS-COMPASS was 5, and for differentiation between conservatively treated and surgically treated or euthanased patients it was 11 ... The use of the EQUUS-COMP"}}]},"equine-medicine--equine-colic-bestfit--colic-คืออะไร-สาเหตุโน้มนำ-และอาการ":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--colic-คืออะไร-สาเหตุโน้มนำ-และอาการ--v1","statement":"Colic เป็นคำกว้างสำหรับภาวะที่ทำให้ม้าปวดท้อง และอาการที่พบบ่อยได้แก่ ขุดพื้นด้วยเท้าหน้า หันมองสีข้าง นอนและกลิ้ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"Colic in Horses, introduction and signs","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"colic has become a broad term for a variety of conditions that cause horses to experience abdominal pain."}}]},"equine-medicine--equine-colic-bestfit--ค่าปกติ-และ-lactate-บอกความรุนแรง":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--ค่าปกติ-และ-lactate-บอกความรุนแรง--v1","statement":"lactate ในเลือดสูงขึ้นหลักๆ จาก anaerobic tissue metabolism เมื่อ oxygen delivery ไม่พอ และเกิดร่วมกับ sepsis และการอักเสบรุนแรงได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22180135","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Anaerobic tissue metabolism resulting from inadequate oxygen delivery (DO2) is the most important cause of an increase in blood lactate concentration in equine patients."}}]},"equine-medicine--equine-colic-bestfit--ng-tube-ตรวจและรักษาในตัว":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--ng-tube-ตรวจและรักษาในตัว--v1","statement":"การใส่สายผ่านจมูกลงกระเพาะระบายแก๊สหรือของเหลวได้ เพราะม้าอาเจียนไม่ได้ และ reflux มากกว่า 4 ลิตรเป็นหนึ่งในข้อบ่งชี้ผ่าตัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"Colic in Horses, stomach tube; indications for surgery","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Because horses cannot vomit, the tube can allow release of gas or fluid that would otherwise result in stomach rupture."}}]},"equine-medicine--equine-colic-bestfit--rectal-palpation-และ-abdominocentesis":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--rectal-palpation-และ-abdominocentesis--v1","statement":"การเจาะเก็บน้ำช่องท้องดู protein และเม็ดเลือดขาวบอกความเสียหายของลำไส้ได้ และ rectal examination ให้คลำลำไส้ ตำแหน่งและเนื้อหาในลำไส้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"The Veterinarian's Examination of a Horse with Colic (table)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Composition (protein and white blood cells) can reveal extent of intestinal damage."}}]},"equine-medicine--equine-colic-bestfit--composite-colic-score-ccs-และการตัดสินทางรักษา":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--composite-colic-score-ccs-และการตัดสินทางรักษา--v1","statement":"ข้อบ่งชี้ผ่าตัดในม้า colic ได้แก่ ปวดคุมไม่ได้ ของเหลวจากสายกระเพาะมากกว่า 4 ลิตร ไม่ได้ยินเสียงลำไส้ ผลน้ำช่องท้องผิดปกติ หรือพบการอุดตัน/เคลื่อนที่จาก rectal examination","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"Colic in Horses, surgery","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"more than 4 liters of fluid retrieved from the stomach tube no intestinal sounds heard with a stethoscope abnormalities within a fluid sample from the abdomen"}}]},"equine-medicine--equine-colic-bestfit--การรักษาทางยา-fluid-และการพาเดิน":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--การรักษาทางยา-fluid-และการพาเดิน--v1","statement":"ม้า colic หลายตัวได้ประโยชน์จากการให้สารน้ำเพื่อป้องกัน dehydration โดยให้ผ่านสายกระเพาะหรือทางเส้นเลือด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"Fluid Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Many horses with colic benefit from fluid treatment to prevent dehydration and maintain blood supply to the kidneys and other vital organs."}}]},"equine-medicine--equine-colic-bestfit--การรักษาทางยา-ยาลดปวดและยาคลายกล้ามเนื้อเรียบ":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--การรักษาทางยา-ยาลดปวดและยาคลายกล้ามเนื้อเรียบ--v1","statement":"ยาลดปวดในม้า colic ได้แก่ ยาต้านอักเสบ ยากล่อมประสาทที่ลดปวดด้วย และ narcotics และการใส่สายกระเพาะช่วยลดปวดจากการระบายของเหลวที่คั่ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-colic-in-horses-2026","locator":"Colic in Horses, pain relief","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Examples include anti-inflammatory drugs, sedatives that also reduce pain, and narcotics."}}]},"equine-medicine--equine-colic-bestfit--common-colic-5-แบบ":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--common-colic-5-แบบ--v1","statement":"Nephrosplenic entrapment คือ left dorsal displacement ของ large colon ที่จัดการได้ทั้งทางยา (conservative) และการผ่าตัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39891548","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Conservative and surgical management of left dorsal displacement and nephrosplenic ligament entrapment of the large colon (NSLE) is well described in horses."}}]},"equine-medicine--equine-colic-bestfit--เมื่อไรควรพิจารณาการุณยฆาต":{"claims":[{"id":"equine-medicine--equine-colic-bestfit--เมื่อไรควรพิจารณาการุณยฆาต--v1","statement":"ในม้า colic พารามิเตอร์ทางคลินิกอย่าง heart rate, capillary refill time และสีเยื่อเมือกสัมพันธ์กับการตาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19642409","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Clinical parameters found to be significantly associated with death by univariate analysis were medical/surgical treatment, location of lesion, severity of lesion, mucous membrane colour (MM), capillary refill time (CRT) and heart rate."}}]}},"equine-medicine--equine-colic-surgery":{"equine-medicine--equine-colic-surgery--สัญญาณที่ชี้ว่าต้องผ่าตัดหรือส่งต่อ":{"claims":[{"id":"equine-medicine--equine-colic-surgery--สัญญาณที่ชี้ว่าต้องผ่าตัดหรือส่งต่อ--v1","statement":"การตรวจน้ำในช่องท้อง (abdominocentesis) ช่วยให้สัตวแพทย์จัดการม้า colic ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35044063","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Interpreting changes in peritoneal fluid helps clinicians manage colic and other diseases in horses."}}]},"equine-medicine--equine-colic-surgery--งดอาหารก่อนและหลังผ่าตัดช่องท้อง":{"claims":[{"id":"equine-medicine--equine-colic-surgery--งดอาหารก่อนและหลังผ่าตัดช่องท้อง--v1","statement":"มีการศึกษาเปรียบเทียบการงดอาหารรอบผ่าตัดในม้า (ไม่งด เทียบกับงด 10 ชม. ก่อนผ่า)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38866041","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"45 horses presenting for elective orthopedic procedures were randomly assigned to 1 of 3 groups: not fasted (NF; continuous access to hay perioperatively), fasted muzzled (FM; 10-hour preoperative fast with slow refeeding postoperatively and muzzle placement)"}}]},"equine-medicine--equine-colic-surgery--เตรียมม้า-ผ่า-colon-และหลังผ่าตัด":{"claims":[{"id":"equine-medicine--equine-colic-surgery--เตรียมม้า-ผ่า-colon-และหลังผ่าตัด--v1","statement":"ในม้าที่นอนหงาย (dorsal recumbency) การเคลื่อนของผนังอกถูกจำกัดและปอดถูกอวัยวะในช่องท้องกด ทำให้ alveoli ยุบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34359177","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In dorsally recumbent horses, chest wall movement is restricted and the lungs are compressed by the abdominal organs, leading to the collapse of the alveoli."}}]}},"equine-medicine--equine-lameness":{"equine-medicine--equine-lameness--นิยาม-และเป้าหมายของการตรวจ":{"claims":[{"id":"equine-medicine--equine-lameness--นิยาม-และเป้าหมายของการตรวจ--v1","statement":"Lameness ไม่ใช่โรค แต่เป็น clinical sign ที่แสดงความเจ็บปวด ข้อจำกัดเชิงกล หรือการทำงานของระบบประสาทและกล้ามเนื้อที่เปลี่ยนไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-overview-of-lameness-in-horses-2025","locator":"Overview, paragraph 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lameness is not a disease itself, but a clinical sign. It is a manifestation of pain, mechanical restrictions causing alteration of stance or gait, or altered neuromuscular function."}}]},"equine-medicine--equine-lameness--ประวัติ-และการสร้าง-baseline":{"claims":[{"id":"equine-medicine--equine-lameness--ประวัติ-และการสร้าง-baseline--v1","statement":"การตรวจม้าขาเจ็บเริ่มจากการซักประวัติอย่างละเอียด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"The Lameness Examination, paragraph 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The examination begins with a comprehensive medical history."}}]},"equine-medicine--equine-lameness--ตรวจตอนพัก-conformation-และความสมมาตร":{"claims":[{"id":"equine-medicine--equine-lameness--ตรวจตอนพัก-conformation-และความสมมาตร--v1","statement":"ตรวจ conformation และดูความสมมาตร การบวม กล้ามเนื้อที่หายไป ท่ายืนผิดปกติ และบาดแผล","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"The Lameness Examination, paragraph on visual evaluation","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Conformation should be evaluated and the horse visually checked for symmetry, swellings, muscle loss, abnormal stance, and obvious injuries."}}]},"equine-medicine--equine-lameness--walk-และ-trot-เกรด-1-5-ขาหน้า-และขาหลัง":{"claims":[{"id":"equine-medicine--equine-lameness--walk-และ-trot-เกรด-1-5-ขาหน้า-และขาหลัง--v1","statement":"อาการที่สม่ำเสมอที่สุดของขาหน้าเจ็บข้างเดียวคือ head nod: หัวและคอยกขึ้นเมื่อขาที่เจ็บลงน้ำหนัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"The Lameness Examination, recognition of lameness","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most consistent sign of a unilateral forelimb lameness is the head nod. The head and neck of the horse rise when the lame forelimb strikes the ground and is weightbearing, and they fall when the sound limb strikes the ground."}}]},"equine-medicine--equine-lameness--การคลำทีละส่วน-และ-manipulative-tests":{"claims":[{"id":"equine-medicine--equine-lameness--การคลำทีละส่วน-และ-manipulative-tests--v1","statement":"Flexion test ขาหลังงอขาค้างไว้ 30-60 วินาทีแล้วให้ trot ออกทันทีเพื่อดูว่าอาการเจ็บเกิดหรือเด่นขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"The Lameness Examination, flexion tests","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The limb is flexed for 30–60 seconds and the horse is trotted away from the examiner to determine whether lameness is created or accentuated."}}]},"equine-medicine--equine-lameness--imaging-และการตรวจเสริม":{"claims":[{"id":"equine-medicine--equine-lameness--imaging-และการตรวจเสริม--v1","statement":"Nuclear medicine (scintigraphy) ให้ข้อมูลเชิงหน้าที่ของ bone turnover การไหลเวียนเลือด และการอักเสบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42527218","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine nuclear medicine provides functional information on bone turnover, perfusion, inflammation and tracer biodistribution."}}]},"equine-medicine--equine-lameness--diagnostic-analgesia-หลักการ-ยาชา-และกลยุทธ์":{"claims":[{"id":"equine-medicine--equine-lameness--diagnostic-analgesia-หลักการ-ยาชา-และกลยุทธ์--v1","statement":"Diagnostic regional anesthesia ใช้หาตำแหน่งที่เจ็บเมื่อรู้ว่าเจ็บที่ขาข้างใดแต่ยังไม่รู้ตำแหน่งบนขา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"The Lameness Examination, diagnostic regional anesthesia","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Diagnostic regional anesthesia should be used to determine the area of pain whenever the lameness can be localized to a specific limb but not to a specific site on the limb"}}]},"equine-medicine--equine-lameness--บล็อกขาหน้า-และแผนผังแปลผลบล็อกปลายขา":{"claims":[{"id":"equine-medicine--equine-lameness--บล็อกขาหน้า-และแผนผังแปลผลบล็อกปลายขา--v1","statement":"การบล็อกที่ปลายขาหน้าทำได้ทั้ง perineural (palmar digital หรือ abaxial sesamoid), DIP joint และ navicular bursa และใช้เปรียบเทียบผลกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8467786","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Analgesia of the distal interphalangeal (DIP) joint and of the navicular bursa was performed independently in the lame or lamer forelimb of 59 horses, in which lameness was significantly improved by perineural analgesia of either the palmar digital or palmar (abaxial sesamoid) nerves."}}]},"equine-medicine--equine-lameness--บล็อกขาหลัง-และ-local-infiltration":{"claims":[{"id":"equine-medicine--equine-lameness--บล็อกขาหลัง-และ-local-infiltration--v1","statement":"ขาหลังใช้ perineural analgesia ของ tibial และ fibular nerve ร่วมกับ intra-articular analgesia (tarsocrural) เพื่อหาตำแหน่งที่เจ็บ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15779631","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tarsocrural joint analgesia produced improvement in lameness in 6/11 horses (55%) and perineural analgesia of the tibial and fibular nerves complete soundness in 6/14 horses (43%) in which it was performed"}}]},"equine-medicine--equine-lameness--แปลผลบล็อก-ผลลบลวง-และผลบวกลวง":{"claims":[{"id":"equine-medicine--equine-lameness--แปลผลบล็อก-ผลลบลวง-และผลบวกลวง--v1","statement":"perineural analgesia ไม่แม่นพอจะแยกความเจ็บที่มาจาก DIP joint ออกจาก navicular bursa จึงต้องแปลผลบล็อกอย่างระวัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35488427","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Our results suggest that perineural analgesia is not reliable enough to differentiate pain originating from DIPJ and NB."}}]},"equine-medicine--equine-lameness--ข้อควรระวังอื่น-และกรณีที่ไม่ควรบล็อก":{"claims":[{"id":"equine-medicine--equine-lameness--ข้อควรระวังอื่น-และกรณีที่ไม่ควรบล็อก--v1","statement":"ไม่ควรทำ diagnostic regional anesthesia เมื่อสงสัยกระดูกหัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"The Lameness Examination, fracture caution","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Similarly, diagnostic regional anesthesia should not be performed when a fracture is suspected."}}]}},"equine-medicine--equine-hoof":{"equine-medicine--equine-hoof--กายวิภาคของกีบ":{"claims":[{"id":"equine-medicine--equine-hoof--กายวิภาคของกีบ--v1","statement":"กีบมี dermal (sensitive) และ epidermal (insensitive) laminae เชื่อมกันเหมือนซิป ยึด bony column กับ hoof capsule","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-laminitis-in-horses-2024","locator":"first paragraph","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The bony column of the limb of the horse is suspended from the inside of the hoof capsule by interlocking dermal and epidermal laminae. ... In laminitis, a series of pathophysiological events causes injury to dermal (sensitive) and epidermal (insensitive) laminae, weakening this attachment."}}]},"equine-medicine--equine-hoof--hoof-balance":{"claims":[{"id":"equine-medicine--equine-hoof--hoof-balance--v1","statement":"ความผิดปกติของ hoof/pastern axis, มุมกีบไม่เท่ากัน และ under-run, contracted, sheared heels พบบ่อยกว่าในม้าที่ขาเจ็บเมื่อเทียบกับม้าปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"Examination at rest, hoof examination","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A number of abnormalities such as an abnormal hoof/pastern axis; mismatched hoof angles; under-run, contracted, and sheared heels; and disproportionate hoof size are seen more frequently in lame than in sound horses."}}]},"equine-medicine--equine-hoof--deformities-ของขาในลูกม้า-dods":{"claims":[{"id":"equine-medicine--equine-hoof--deformities-ของขาในลูกม้า-dods--v1","statement":"Flexural deformity วินิจฉัยจากการที่ digit, fetlock หรือ carpus เหยียดหรืองอมากเกิน (hyperextension หรือ hyperflexion)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-flexural-deformities-in-horses-2025","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The diagnosis is apparent on clinical examination, based on hyperextension or hyperflexion of the digit, fetlock, or carpus."}}]},"equine-medicine--equine-hoof--โรคของ-hoof-capsule-ภายนอก":{"claims":[{"id":"equine-medicine--equine-hoof--โรคของ-hoof-capsule-ภายนอก--v1","statement":"White line disease คือภาวะ keratolytic ของชั้นลึกของ stratum medium ในผนังกีบ ทำให้ผนังกีบแยกตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-white-line-disease-in-horses-2024","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"White line disease in horses is a keratolytic condition affecting the deeper layers of the stratum medium of the hoof wall."}}]},"equine-medicine--equine-hoof--โรคของโครงสร้างภายในกีบ-และ-subsolar-abscess":{"claims":[{"id":"equine-medicine--equine-hoof--โรคของโครงสร้างภายในกีบ-และ-subsolar-abscess--v1","statement":"ความเจ็บของ hoof abscess มาจากแรงดันที่เพิ่มขึ้นเร็วภายในโพรงกีบที่ยืดหยุ่นน้อย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-hoof-abscesses-in-horses-2024","locator":"Etiology and Pathophysiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The pain that is responsible for the lameness associated with hoof abscesses in horses is due to the rapid increase in pressure within the low-compliance environment of the hoof capsule."}}]},"equine-medicine--equine-hoof--laminitis-นิยาม-สาเหตุ-และระยะ":{"claims":[{"id":"equine-medicine--equine-hoof--laminitis-นิยาม-สาเหตุ-และระยะ--v1","statement":"Laminitis คือการอักเสบและการแยกของ laminae ของกีบ สาเหตุในม้ารวมถึง carbohydrate overload, น้ำหนักที่ลงขามากเกิน และ endotoxemia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-laminitis-in-horses-2024","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Laminitis is the inflammation and subsequent separation of the laminae of the hoof. Causes in horses include carbohydrate overload, excess weight bearing, and endotoxemia."}}]},"equine-medicine--equine-hoof--laminitis-การรักษาตามช่วงเวลา":{"claims":[{"id":"equine-medicine--equine-hoof--laminitis-การรักษาตามช่วงเวลา--v1","statement":"ยาที่ใช้รักษา laminitis เพื่อรักษาเลือดมาเลี้ยงเท้า ได้แก่ acepromazine และยาอื่น ส่วน NSAIDs ใช้จัดการความปวดและการอักเสบเป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-laminitis-in-horses-2024","locator":"Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Drugs administered to help maintain or improve the blood supply to the foot include acepromazine, pentoxifylline, isoxsuprine, aspirin, and heparin. NSAIDs are most commonly used to manage pain and inflammation."}}]},"equine-medicine--equine-hoof--conformation-ของกีบ-และ-hoof-tester-ตอนตรวจขาเจ็บ":{"claims":[{"id":"equine-medicine--equine-hoof--conformation-ของกีบ-และ-hoof-tester-ตอนตรวจขาเจ็บ--v1","statement":"Hoof tester ใช้กดโครงสร้างภายในโพรงกีบเพื่อหาจุดที่เจ็บ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-the-lameness-examination-in-horses-2024","locator":"Figure caption: Applying hoof testers","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Hoof testers are used to compress structures inside the hoof capsule to detect pain."}}]}},"equine-medicine--equine-tendon":{"equine-medicine--equine-tendon--อุบัติการณ์-และเอ็นที่บาดเจ็บบ่อย":{"claims":[{"id":"equine-medicine--equine-tendon--อุบัติการณ์-และเอ็นที่บาดเจ็บบ่อย--v1","statement":"Tendinitis พบบ่อยที่สุดในม้าที่ใช้งานวิ่งเร็ว โดยเฉพาะม้าแข่ง และการบาดเจ็บของ SDFT พบบ่อยที่ขาหน้าของ Thoroughbred","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tendinitis is the most common in horses used for fast work, particularly racehorses. Superficial digital flexor tendon (SDFT) injuries commonly occur in the forelimb of Thoroughbred racehorses."}}]},"equine-medicine--equine-tendon--โครงสร้าง-histology-และ-physiology-ของ-tendon":{"claims":[{"id":"equine-medicine--equine-tendon--โครงสร้าง-histology-และ-physiology-ของ-tendon--v1","statement":"โครงสร้างและการเรียงตัวตามแนวแกนของ type I collagen fibrils สำคัญต่อ tensile strength ของ tendon และ tenocytes สร้างและรักษา extracellular matrix","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16005620","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The structure and organisation of the extracellular matrix, and in particular the axial alignment of type I collagen fibrils, are essential for the tensile strength of tendons. The resident tenocytes synthesize and maintain the composition of the extracellular matrix"}}]},"equine-medicine--equine-tendon--สาเหตุ-พยาธิกำเนิด-และระยะการซ่อม":{"claims":[{"id":"equine-medicine--equine-tendon--สาเหตุ-พยาธิกำเนิด-และระยะการซ่อม--v1","statement":"SDFT tendinitis มักเกิดหลังออกกำลังเร็ว สัมพันธ์กับ overextension, สภาพร่างกายไม่พร้อม, ความล้า และการฝึกต่อเนื่องทั้งที่ tendon อักเสบอยู่แล้ว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"Etiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"SDFT tendinitis in horses usually appears after fast exercise and is associated with overextension and poor conditioning, fatigue, poor racetrack conditions, and persistent training when inflammatory problems in the tendon already exist."}}]},"equine-medicine--equine-tendon--อาการ-การวินิจฉัย-และเทคนิค-ultrasound":{"claims":[{"id":"equine-medicine--equine-tendon--อาการ-การวินิจฉัย-และเทคนิค-ultrasound--v1","statement":"Ultrasonography (probe เชิงเส้นความถี่สูง 7.5-15 MHz) เป็นเครื่องมือที่ใช้บ่อยที่สุดเพื่อบันทึกการบาดเจ็บของ tendon ในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"Diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ultrasonography (high-frequency [7.5–15 MHz] linear probes) is the most commonly used and available diagnostic tool for documenting tendon injury in horses."}}]},"equine-medicine--equine-tendon--ภาพ-ultrasound-acute-ระหว่างหาย-และ-chronic":{"claims":[{"id":"equine-medicine--equine-tendon--ภาพ-ultrasound-acute-ระหว่างหาย-และ-chronic--v1","statement":"ภาพ ultrasound ของ tendon บาดเจ็บเห็น tendon โตขึ้น, hypoechogenicity เฉพาะที่หรือทั่วเส้น และ fiber ขาดหรือ remodel ในระดับต่างกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"Diagnosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tendon enlargement, focal or generalized hypoechogenicity, and varying degrees of tendon fiber disruption or remodeling can be visualized."}}]},"equine-medicine--equine-tendon--recurrence":{"claims":[{"id":"equine-medicine--equine-tendon--recurrence--v1","statement":"การศึกษาใน 219 ตัวพบ reinjury rate ของ SDF tendonitis ที่ขาที่รักษา 42.5-44.4% ในกลุ่มที่ใช้ controlled exercise อย่างเดียว หรือเสริม hyaluronan หรือ PSGAG","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15253082","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There was no significant difference in reinjury rate of the treated limb(s) between Groups A, B, Ci and Cii (42.5-44.4%) (P>0.9)."}}]},"equine-medicine--equine-tendon--suspensory-ligament-3-syndromes":{"claims":[{"id":"equine-medicine--equine-tendon--suspensory-ligament-3-syndromes--v1","statement":"รอยโรคของ suspensory ligament แบ่งตามตำแหน่งเป็น proximal region, body และ branches","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-suspensory-desmitis-in-horses-2025","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lesions are typically classified as affecting the proximal region, body, or branches of the suspensory ligament."}}]},"equine-medicine--equine-tendon--inferior-check-ligament-icl-desmitis":{"claims":[{"id":"equine-medicine--equine-tendon--inferior-check-ligament-icl-desmitis--v1","statement":"การบาดเจ็บของ inferior check ligament พบน้อยในม้าแข่งแต่พบบ่อยใน ponies และ warmblood","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-inferior-check-ligament-desmitis-in-horses-2025","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Injury of the ICL is relatively uncommon in racehorses but is common in ponies and warmblood breeds."}}]},"equine-medicine--equine-tendon--หลักการรักษา-และการประเมินคุณภาพการหาย":{"claims":[{"id":"equine-medicine--equine-tendon--หลักการรักษา-และการประเมินคุณภาพการหาย--v1","statement":"tendon หายช้า และเนื้อซ่อมมักมีความแข็งแรงเชิงกลด้อยกว่า tendon เดิมเพราะ collagen เรียงตัวไม่เป็นระเบียบเมื่อเกิด scar","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendon-disorders-in-animals-2026","locator":"introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"However, because of this relatively poor blood supply, tendon healing can be prolonged, and the resultant repair tissue is usually of inferior mechanical strength compared to the original, uninjured tendon. This weakening is due to the rearrangement of collagen fibers in a less organized fashion as scar tissue forms."}}]},"equine-medicine--equine-tendon--conservative-treatment-และโปรแกรม-controlled-exercise":{"claims":[{"id":"equine-medicine--equine-tendon--conservative-treatment-และโปรแกรม-controlled-exercise--v1","statement":"Tendinitis รักษาได้ผลดีที่สุดในระยะ acute: พักคอก ประคบเย็น และให้ยาต้านการอักเสบทั้งระบบอย่างเข้มข้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tendinitis in horses is best treated in the early, acute stage. The horse should be stall-rested, and the swelling and inflammation should be treated aggressively with cold packs and systemic anti-inflammatory agents."}}]},"equine-medicine--equine-tendon--physical-therapies-counter-irritation-และศัลยกรรม":{"claims":[{"id":"equine-medicine--equine-tendon--physical-therapies-counter-irritation-และศัลยกรรม--v1","statement":"การรักษา tendinitis เรื้อรังที่เคยใช้ ได้แก่ superficial point firing (ประโยชน์น่าสงสัย) และ percutaneous tendon splitting","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Other treatments for chronic tendinitis in horses have included superficial point firing (which is of questionable benefit) and percutaneous tendon splitting."}}]},"equine-medicine--equine-tendon--ยาฉีดเข้ารอยโรค-growth-factors-และ-stem-cells":{"claims":[{"id":"equine-medicine--equine-tendon--ยาฉีดเข้ารอยโรค-growth-factors-และ-stem-cells--v1","statement":"การฉีด corticosteroid เข้าใน tendon เป็นข้อห้าม เพราะยับยั้งกลไกการซ่อม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tendinitis-in-horses-2025","locator":"Treatment, Pearls & Pitfalls","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Intratendinous corticosteroid injections are contraindicated because they inhibit repair mechanisms."}}]}},"equine-medicine--equine-ortho":{"equine-medicine--equine-ortho--ระยะการหายของแผล-และเส้นเวลาของม้าโดยเฉพาะ":{"claims":[{"id":"equine-medicine--equine-ortho--ระยะการหายของแผล-และเส้นเวลาของม้าโดยเฉพาะ--v1","statement":"ระยะอักเสบของแผลในม้ายืดยาวผิดปกติเมื่อเทียบกับ pony โดยจำนวน polymorphonuclear leucocyte ใน pony สูงในสามสัปดาห์แรกแล้วลดลงอย่างรวดเร็ว ส่วนในม้าเริ่มต้นต่ำกว่าแต่คงสูงอยู่ตลอดช่วงที่ติดตาม ซึ่งเป็นหลักฐานตรงกับลายมือที่ระบุว่า inflammatory phase ของม้านานมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9952331","locator":"31(1):61-67, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the ponies, the number of polymorphonuclear leucocytes (PMNs) was high during the first 3 weeks and subsequently decreased rapidly. In the horses, the initial number of PMNs was lower, but remained persistently elevated during the evalua"}}]},"equine-medicine--equine-ortho--first-intention-healing-primary-closure-ม้าเทียบกับ-pony":{"claims":[{"id":"equine-medicine--equine-ortho--first-intention-healing-primary-closure-ม้าเทียบกับ-pony--v1","statement":"ในการศึกษาย้อนหลังแผลอุบัติเหตุ 89 pony และ 422 ม้า อัตราความสำเร็จของ primary closure สูงกว่าใน pony อย่างมีนัยสำคัญ และเกิด sequestrum น้อยกว่าอย่างมีนัยสำคัญ ทั้งที่ pony ได้รับยาปฏิชีวนะและ NSAIDs น้อยกว่า ตรงกับสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12108745","locator":"34(3):270-273, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Antibiotics and NSAIDs were administered significantly less often to ponies. The success rate of primary closure was significantly higher in ponies than in horses, and sequestra were formed significantly less often in ponies."}}]},"equine-medicine--equine-ortho--second-intention-healing-contraction-เทียบกับ-epithelialization":{"claims":[{"id":"equine-medicine--equine-ortho--second-intention-healing-contraction-เทียบกับ-epithelialization--v1","statement":"Second-intention healing ใน pony เร็วกว่าม้าอย่างมีนัยสำคัญ และความต่างนี้อธิบายได้เป็นส่วนใหญ่จาก wound contraction ที่แรงและเร็วกว่าใน pony ส่วนแผลที่ metatarsus ของม้ากลับขยายใหญ่ขึ้นเกือบสองเท่าของขนาดเดิมในสองสัปดาห์แรก มี exuberant granulation tissue ที่คงอยู่ epithelialization เริ่มช้ากว่า และ contraction แทบไม่มีบทบาท","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9952330","locator":"31(1):53-60, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"these wounds increased to almost twice their original size in the first 2 weeks, exuberant granulation tissue was persistent, epithelialisation started later, and contraction played a minor role in wound closure"}},{"id":"equine-medicine--equine-ortho--second-intention-healing-contraction-เทียบกับ-epithelialization--v2","statement":"Myofibroblast ในแผลของม้าเรียงตัวไม่เป็นระเบียบอย่างมีนัยสำคัญเมื่อเทียบกับ pony โดยเฉพาะแผลที่ metatarsus ซึ่งเป็นคำอธิบายทางเนื้อเยื่อของการหดตัวที่ช้าและไม่มีประสิทธิภาพตามที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9952331","locator":"31(1):61-67, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"myofibroblasts were significantly less regularly organised in the wounds of the horses, particularly in the metatarsal wounds"}},{"id":"equine-medicine--equine-ortho--second-intention-healing-contraction-เทียบกับ-epithelialization--v3","statement":"ระดับ transforming growth factor beta ในแผลของ pony สูงกว่าของม้าอย่างมีนัยสำคัญ และระดับที่สูงกว่านี้อธิบายทั้งการอักเสบที่แรงกว่าและการหดตัวที่มากกว่า ส่วนการที่ระดับยังคงสูงค้างในแผลที่ขาอาจนำไปสู่การเกิด exuberant granulation tissue","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12100380","locator":"10(3):188-194, Results และ Discussion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Levels of TGF-beta were significantly higher in pony wounds than in those of horses... The persistence of elevated levels of TGF-beta may result in the production of exuberant granulation tissue."}}]},"equine-medicine--equine-ortho--inflammatory-response-granulation-tissue-และ-epithelialization":{"claims":[{"id":"equine-medicine--equine-ortho--inflammatory-response-granulation-tissue-และ-epithelialization--v1","statement":"กลไกที่อยู่เบื้องหลังคือ leukocyte ของ pony สร้าง inflammatory mediator ได้มากกว่า จึงป้องกันการติดเชื้อได้ดี กำจัดเนื้อตายเร็ว และเข้าสู่ระยะซ่อมแซมพร้อมการหดตัวที่มากกว่า ขณะที่ leukocyte ของม้าสร้าง mediator น้อยกว่า ทำให้การอักเสบอ่อนแล้วกลายเป็นเรื้อรัง ยับยั้งการหดตัว และก่อให้เกิด exuberant granulation tissue","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15691597","locator":"21(1):15-32, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In horses, leukocytes produce fewer mediators, initiating a weak inflammatory response, which becomes chronic. This inhibits wound contraction and gives rise to the formation of exuberant granulation tissue."}}]},"equine-medicine--equine-ortho--clinical-implications-จะเข้าไปแทรกแซงตอนไหน":{"claims":[{"id":"equine-medicine--equine-ortho--clinical-implications-จะเข้าไปแทรกแซงตอนไหน--v1","statement":"การอักเสบเรื้อรังมักไม่ถูกมองว่าเป็นสาเหตุของ exuberant granulation tissue ทั้งที่ต้องป้องกันและรักษาเพื่อให้แผลหายต่อได้ ซึ่งรองรับแนวทางในสไลด์ที่ให้กดการอักเสบลงในช่วงหลังเพื่อป้องกัน EGT","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15691597","locator":"21(1):15-32, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Chronic inflammation is often not recognized as a cause of exuberant granulation tissue. It must be prevented and treated to promote the healing process."}}]},"equine-medicine--equine-ortho--exuberant-granulation-tissue-egt":{"claims":[{"id":"equine-medicine--equine-ortho--exuberant-granulation-tissue-egt--v1","statement":"EGT เกิดบ่อยเป็นพิเศษที่แผลขาส่วนปลายของม้า โดยในแผลทดลองที่ metatarsus ของม้า granulation tissue คงอยู่แบบ exuberant และ mitotic activity ของ granulation tissue ยังสูงค้างอยู่ ต่างจากแผลตำแหน่งอื่นและจาก pony","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9952331","locator":"31(1):61-67, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The mitotic activity of the granulation tissue was initially high but declined rapidly from week 1 onwards, with the exception of the metatarsal wounds of the horses, in which mitotic activity remained significantly higher."}}]},"equine-medicine--equine-ortho--โครงสร้าง-bandage-สามชั้น":{"claims":[{"id":"equine-medicine--equine-ortho--โครงสร้าง-bandage-สามชั้น--v1","statement":"โครงสร้าง bandage สามชั้นแบบ primary dressing ใต้ชั้น secondary adhesive และชั้น tertiary fabric เป็นเทคนิคมาตรฐานที่ใช้จริงและถูกนำมาทดสอบในงานวิจัยแบบสุ่มของ abdominal bandage ในม้าหลังผ่าตัดช่องท้อง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39967458","locator":"57(6):1466-1477, Methods","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"incisional protection from a primary dressing under a secondary adhesive and tertiary fabric abdominal bandage for anaesthetic recovery"}},{"id":"equine-medicine--equine-ortho--โครงสร้าง-bandage-สามชั้น--v2","statement":"ชั้นนอกสุดเป็นตัวสร้างแรงกดหลักของ bandage ที่ขา โดยแรงกดรวมหลังพัน brown gauze อยู่ที่ 80 mmHg แล้วเพิ่มขึ้นเป็น 165 mmHg หลังพันชั้น elastic ทับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27289022","locator":"49(3):329-333, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Combined sensor pressure after application of the brown gauze was 80 mmHg (95% CI 75-85 mmHg) and rose to 165 mmHg (95% CI 160-170 mmHg) after the elastic layer."}}]},"equine-medicine--equine-ortho--หลักการพันผ้าที่ขา":{"claims":[{"id":"equine-medicine--equine-ortho--หลักการพันผ้าที่ขา--v1","statement":"แม้พัน bandage ตามเทคนิคมาตรฐาน แรงกดใต้ bandage ก็ไม่สม่ำเสมอรอบเส้นรอบวงขา โดยที่ระดับกลาง metacarpus เดียวกัน ด้าน dorsal วัดได้ 187 mmHg ขณะที่ด้าน lateral ได้ 142 mmHg จึงต้องระวังจุดที่แรงกดสูงเกิน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27289022","locator":"49(3):329-333, Results และ Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For the DLC, dorsal and lateral sensor pressures were 187 mmHg (95% CI 185-189 mmHg) and 142 mmHg (95% CI 133-151 mmHg)... Pressure distribution was not uniform."}},{"id":"equine-medicine--equine-ortho--หลักการพันผ้าที่ขา--v2","statement":"Compression bandage ที่ขาส่วนปลายคงแรงกดสูงได้นานถึง 96 ชั่วโมง แต่มีแรงกดลดลงอย่างมีนัยสำคัญระหว่างชั่วโมงที่ 6 ถึง 12 และหากเป้าหมายคือการคง compression ไว้ ระยะเปลี่ยน bandage ทุก 4 วันอาจเหมาะสม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27289022","locator":"49(3):329-333, Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The DLC maintained high pressures for 96 h, but a significant decrease in pressure occurred between 6 and 12 h. Providing there are no other reasons to change a bandage, a 4 day interval between bandages may be appropriate"}}]},"equine-medicine--equine-ortho--carpal-และ-tarsal-bandage":{"claims":[{"id":"equine-medicine--equine-ortho--carpal-และ-tarsal-bandage--v1","statement":"แรงกดของ carpal และ tarsal compression bandage ลดลงอย่างมีนัยสำคัญหลังจูงม้าเดินเพียงประมาณ 50 เมตร ขณะที่ adhesive elastic carpal bandage แรงกดไม่เปลี่ยน จึงอาจเหมาะกว่าสำหรับม้าที่ยังเดินได้และต้องพันนาน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30129061","locator":"47(5):640-647, Results และ Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pressures resulting from CC and TC decreased after walking (P < .001), whereas those associated with C-ELA were not affected... Carpal elastic bandages maintain sub-bandage pressures during ambulation and may be more appropriate for long te"}}]},"equine-medicine--equine-ortho--robert-jones-bandage":{"claims":[{"id":"equine-medicine--equine-ortho--robert-jones-bandage--v1","statement":"เมื่อพัน Robert Jones bandage เสร็จ ความหนาที่ได้ควรเป็นประมาณ 3 เท่าของเส้นผ่านศูนย์กลางขา ตรงกับตัวเลขในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2025","locator":"หัวข้อ Fracture Stabilization, Level 2 injuries","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the bandage should be up to 3 times the diameter of the limb when finished"}},{"id":"equine-medicine--equine-ortho--robert-jones-bandage--v2","statement":"ต้องพันวัสดุแต่ละชั้นแยกกันและพันไปในทิศทางเดียวกัน เพื่อไม่ให้ชั้นวัสดุหรือ splint เลื่อน ซึ่งรองรับหลักการในสไลด์ที่ให้รัดทีละชั้นและหลีกเลี่ยงการวางชั้นหนา","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2025","locator":"หัวข้อ Bandaging and splint application","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Each layer of bandaging material is wrapped separately and in the same direction to prevent shifting"}},{"id":"equine-medicine--equine-ortho--robert-jones-bandage--v3","statement":"ในแบบจำลอง metacarpal fracture ของขาม้า Robert Jones bandage ที่ใส่ splint ตั้งฉากสองแท่ง ต้านแรงดัดได้ไม่ต่างจาก single-stack bandage ที่ใส่ splint แบบเดียวกัน โดยมุมเบี่ยง 10.7 เทียบกับ 9.8 องศา แต่ single-stack ให้แรงกดใต้ bandage สูงกว่าอย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36577447","locator":"36(2):82-86, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There was no significant difference between RJB and SS constructs in change in deflection angle (10.7 +/- 3.0 degrees vs. 9.8 +/- 2.6 degrees)... Sub-bandage pressures were significantly greater for the SS than the RJB both dorsally and lat"}}]},"equine-medicine--equine-ortho--splint-bandage":{"claims":[{"id":"equine-medicine--equine-ortho--splint-bandage--v1","statement":"การใส่ splint ร่วมกับ bandage เพื่อตรึงกระดูกฝ่าเท้าหักในสนามมีหลักฐานรองรับ โดย single-stack bandage ที่ใส่ splint ต้านแรงดัดได้เทียบเท่ากับ Robert Jones bandage ที่ใส่ splint จึงเป็นทางเลือกที่ใช้ได้ในสภาพภาคสนาม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36577447","locator":"36(2):82-86, Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The SS splint construct may be a useful alternative to the RJB splint construct in field situations for metacarpal fracture stabilization."}},{"id":"equine-medicine--equine-ortho--splint-bandage--v2","statement":"Splint สำเร็จรูปเชิงพาณิชย์มีหลายขนาด ใส่ง่าย และได้ผลดีสำหรับการตรึงทันที ส่วนการบาดเจ็บระดับที่สูงขึ้นของขาหลังใช้แผ่นไม้กว้างหรือ splint โลหะดัดรูป และสามารถใช้ fiberglass casting tape ได้ด้วย ซึ่งรองรับหมวดวัสดุ splint ในสไลด์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2025","locator":"หัวข้อ Fracture Stabilization, splint materials","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"available in a number of sizes, easy to apply, and effective for immediate immobilization ... a wide wooden board or a contoured metal splint made of electrical conduit pipe ... Fiberglass casting tape can also be used"}}]},"equine-medicine--equine-ortho--stent-tie-over-bandage":{"claims":[{"id":"equine-medicine--equine-ortho--stent-tie-over-bandage--v1","statement":"การเย็บ stent ติดกับแผลเป็นชั้นแรกของ bandage เพื่อปกป้องแผลผ่าตัดช่วง anaesthetic recovery เป็นเทคนิคที่ใช้จริงในเวชปฏิบัติและถูกนำมาทดสอบเป็น intervention ในงานวิจัยแบบสุ่มควบคุม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39967458","locator":"57(6):1466-1477, Methods","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eligible horses were randomised to a sutured-on stent (intervention) or textile dressing (control) as the primary component of a 3-layer abdominal bandage placed for anaesthetic recovery."}}]},"equine-medicine--equine-ortho--abdominal-bandage":{"claims":[{"id":"equine-medicine--equine-ortho--abdominal-bandage--v1","statement":"CM hernia belt ให้แรงกดใต้ bandage สูงที่สุดที่ค่าเฉลี่ย 39 mmHg รองลงมาคือ elastic bandage 25 mmHg และ nylon binder ต่ำสุดที่ 5 mmHg ซึ่งตรงกับลำดับที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25124529","locator":"47(5):599-602, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mean sub-bandage pressures were different between all treatment groups (P < 0.001) at 39 (95% confidence interval, 36.7-40.5 mmHg), 25 (95% confidence interval, 23.9-27.7 mmHg) and 5 mmHg (95% confidence interval, 4.1-7.8 mmHg) for CM, ELA "}},{"id":"equine-medicine--equine-ortho--abdominal-bandage--v2","statement":"Elastic bandage มีแนวโน้มเลื่อนไปทางด้านท้ายลำตัวมากกว่าทั้ง CM hernia belt และ nylon binder ซึ่งรองรับข้อเสียเรื่องการเลื่อนหลุดที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25124529","locator":"47(5):599-602, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ELA bandages were more likely to displace caudally compared with both CM and NYL bandages."}}]},"equine-medicine--equine-ortho--สรุป-wound-management-ในม้า":{"claims":[{"id":"equine-medicine--equine-ortho--สรุป-wound-management-ในม้า--v1","statement":"Exuberant granulation tissue เป็นภาวะแทรกซ้อนที่พบบ่อยของการหายแบบ second intention ที่ปลายขาม้า และกลไกการเกิดยังไม่ชัดเจน จึงยังไม่มีวิธีป้องกันหรือรักษาที่มีหลักฐานหนักแน่น สนับสนุนหลักการของเอกสารที่ให้เลือกวิธีปิดแผลตามสภาพแผลอย่างระมัดระวัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35093532","locator":"Vol 280:105790, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Exuberant granulation tissue (EGT) is often observed during second intention wound healing in horses. Despite its impact on wound care, the basic mechanisms leading to EGT are still unclear and effective strategies to prevent and/or treat E"}}]},"equine-medicine--equine-ortho--ชนิดของ-bandage-ตามระดับของขา":{"claims":[{"id":"equine-medicine--equine-ortho--ชนิดของ-bandage-ตามระดับของขา--v1","statement":"การเลือกชนิดของ bandage ในม้าถูกกำหนดโดยตำแหน่งของร่างกายที่บาดเจ็บ ซึ่งเป็นหลักการเดียวกับการแบ่ง foot bandage, half limb bandage และ full limb bandage ตามระดับของขา และการพันผ้ากับ external coaptation เป็นเครื่องมือหลักของสัตวแพทย์ม้าเพราะไม่สามารถบังคับให้ม้าอยู่นิ่งหรือรักษาความสะอาดของแผลในระยะแรกได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30342804","locator":"Abstract; 34(3):557-574","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The type of bandage used is dictated by the region of the body that is injured."}}]},"equine-medicine--equine-ortho--head-bandage":{"claims":[{"id":"equine-medicine--equine-ortho--head-bandage--v1","statement":"ตำราระบุว่า head bandage ใช้ปกป้องแผลที่หัวหรือแผลที่ปล่อยให้หายแบบ second intention และองค์ประกอบหลักคือการสวม mesh stockinette คลุมหัวโดยเจาะรูสำหรับหูและตา เพื่อให้แรงกดเบา ๆ ที่ช่วยควบคุมการเกิด subcutaneous emphysema ตรงตามที่สรุประบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1002-9781118999219-ch7","locator":"บทที่ 7 หัวข้อ Head bandages (หน้า 132-156)","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A head bandage is useful to protect the repair of a head wound or a wound left open to heal by second intention. ... The placement of a mesh stockinette over the head, with holes cut out for ears and eyes ... to exert a small amount of pres"}},{"id":"equine-medicine--equine-ortho--head-bandage--v2","statement":"ตำรายืนยันรูปแบบการพันด้วยเทปเป็นเลขแปด (figure-of-eight) โดยพาดระหว่างตาสองข้างแล้วอ้อมรอบขากรรไกรล่าง เพื่อเสริมความมั่นคงของ bandage รวมถึงในเคสหลังการควักลูกตาและหลังซ่อมกระดูก frontal","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1002-9781118999219-ch7","locator":"บทที่ 7 หัวข้อ Head bandages (หน้า 132-156)","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"wrapped in a figure-of-eight pattern between the eyes and around the mandible"}},{"id":"equine-medicine--equine-ortho--head-bandage--v3","statement":"ตำราเตือนอย่างชัดเจนว่าห้ามพันแน่นเกินไปที่ปลายด้าน rostral ของ bandage เพราะจะทำให้ม้าอ้าปากไม่ได้ และห้ามพันแน่นบริเวณ throatlatch ตรงกับข้อควรระวังที่สรุประบุ นอกจากนี้ยังระบุว่าใช้ fly mask หรือหมวกสำเร็จรูปสำหรับขนส่งม้าร่วมด้วยได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1002-9781118999219-ch7","locator":"บทที่ 7 หัวข้อ Head bandages (หน้า 132-156)","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Care should be taken to avoid wrapping too tightly around the rostral extent of the bandage, which might prevent the mouth from opening, or around the throatlatch region. ... Commercial fly masks and helmets designed for the transport of ho"}}]}},"equine-medicine--equine-infectious":{"equine-medicine--equine-infectious--dermatophytosis-การติดเชื้อราตื้นที่ผิวหนัง":{"claims":[{"id":"equine-medicine--equine-infectious--dermatophytosis-การติดเชื้อราตื้นที่ผิวหนัง--v1","statement":"ม้าเป็น reservoir หลักของ Trichophyton equinum ซึ่งเป็น zoophilic dermatophyte และติดต่อสู่คนได้ แม้จะพบไม่บ่อย จึงต้องระวังทั้งผู้จับบังคับและเจ้าของตามที่สไลด์เตือน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37280370","locator":"Abstract; 74(9):707-710","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The horse is the most common reservoir of Trichophyton (T.) equinum. However, this zoophilic dermatophyte only rarely causes infections in humans."}},{"id":"equine-medicine--equine-infectious--dermatophytosis-การติดเชื้อราตื้นที่ผิวหนัง--v2","statement":"เชื้อที่แยกได้จริงจากรอยโรคเชื้อราของม้าคือ Trichophyton equinum และ Microsporum equinum (รวมถึง M. canis และ M. gypseum) และ miconazole (MCZ) ยับยั้งเชื้อกลุ่มนี้ได้ในหลอดทดลองที่ MIC 0.03 ถึง 16 mg/L สนับสนุนการใช้แชมพู miconazole เป็นยาทาภายนอก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34189781","locator":"Results; 32(5):474-e129","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The MICs for all 16 clinical isolates of Trichophyton equinum, Microsporum equinum/canis and M. gypseum for LCZ were <0.03 mg/L. The MICs of all isolates were <0.03-0.5 mg/L for CTZ, 0.03-16 mg/L for MCZ and <0.03-1 mg/L for TRF."}},{"id":"equine-medicine--equine-infectious--dermatophytosis-การติดเชื้อราตื้นที่ผิวหนัง--v3","statement":"การรักษา ringworm ในม้าตามมาตรฐานคือการใช้ยาทาภายนอกในรูปแชมพูยา เพื่อลดการแพร่เชื้อระหว่างตัว สอดคล้องกับที่สไลด์ระบุว่าไม่มียาต้านเชื้อราชนิดกินหรือฉีดที่ขึ้นทะเบียนสำหรับม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19403294","locator":"Introduction; 16(11):1056-8","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The conventional treatment of equine trichophytosis is topic, based upon medicated shampoos to reduce the spread of infection among the animals."}}]},"equine-medicine--equine-infectious--dermatophilosis-จาก-dermatophilus-congolensis":{"claims":[{"id":"equine-medicine--equine-infectious--dermatophilosis-จาก-dermatophilus-congolensis--v1","statement":"Dermatophilus congolensis เป็น actinomycete ที่ก่อโรค rain scald ในม้า (และ dermatophilosis ในโค lumpy wool ในแกะ) ตรงกับชื่อกลุ่มอาการที่สไลด์ใช้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12019944","locator":"Abstract, opening sentence; 49(3):135-41","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dermatophilus congolensis is the pathogenic actinomycete that causes dermatophilosis in cattle, lumpy wool in sheep and rain scald in horses."}},{"id":"equine-medicine--equine-infectious--dermatophilosis-จาก-dermatophilus-congolensis--v2","statement":"Impression smear จากสะเก็ดให้ภาพจำเพาะคือสายใยยาวของแบคทีเรียรูปกลมอ้วนที่แบ่งตัวทั้งแนวขวางและแนวยาว ใช้ยืนยันการวินิจฉัยได้โดยไม่ต้องรอผลเพาะเชื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34213394","locator":"Pathological findings; 70(1):63-68","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Impression smears of the lesions revealed long filamentous chains of plump coccoid bacteria separated by transverse and longitudinal septa"}}]},"equine-medicine--equine-infectious--coital-exanthema-จาก-equine-herpesvirus-3-ehv-3":{"claims":[{"id":"equine-medicine--equine-infectious--coital-exanthema-จาก-equine-herpesvirus-3-ehv-3--v1","statement":"การติดต่อทางการผสมพันธุ์ได้รับการยืนยันในภาคสนาม พ่อม้าขับไวรัสออกมาอย่างน้อย 4 วันก่อนแสดงอาการ และแม่ม้าที่ผสมภายใน 3 วันก่อนพ่อม้าแสดงอาการเกิดรอยโรคที่อวัยวะเพศภายนอก จึงเป็นเหตุผลที่ต้องพักการผสมพันธุ์เมื่อพบรอยโรค","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32684614","locator":"Results and conclusion; 82(9):1299-1305","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ten mares that mated within 3 days before onset showed clinical signs of ECE on the external genitalia ... EHV-3 was excreted from the stallions at least within 4 days before the onset of ECE"}},{"id":"equine-medicine--equine-infectious--coital-exanthema-จาก-equine-herpesvirus-3-ehv-3--v2","statement":"การติดเชื้อ EHV-3 คงอยู่ในฝูงได้โดยม้าไม่แสดงอาการ และมีหลักฐานว่าการติดเชื้อซ้ำหรือการกลับมาแบ่งตัวของเชื้อแฝงเกิดขึ้นในฤดูผสมพันธุ์ สนับสนุนแนวคิดพาหะแฝงที่สไลด์กล่าวถึง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28132964","locator":"Seroepidemiological survey; 79(3):636-643","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection time of the four horses was in the breeding season, and re-infection or reactivation of latently infected EHV-3 might have occurred in one horse. However, these four horses had never shown any clinical symptoms."}},{"id":"equine-medicine--equine-infectious--coital-exanthema-จาก-equine-herpesvirus-3-ehv-3--v3","statement":"ลำดับรอยโรคของ equine coital exanthema คือ papule, vesicle, pustule แล้วเป็นแผลหลุม พบที่อวัยวะเพศภายนอกของทั้งพ่อม้าและแม่ม้า ตรงกับลำดับที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33531030","locator":"Background; 63(1):6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is characterized by the formation of papules, vesicles, pustules and ulcers on the external genitals of both mares and stallions."}}]},"equine-medicine--equine-infectious--viral-papillomatosis-หรือหูด":{"claims":[{"id":"equine-medicine--equine-infectious--viral-papillomatosis-หรือหูด--v1","statement":"Equus caballus papillomavirus type 1 (EcPV-1) ถูกแยกได้จาก cutaneous papilloma ซึ่งเป็นเนื้องอกที่พบบ่อยที่สุดในม้า ยืนยันว่า EcPV-1 คือสาเหตุของหูดที่ผิวหนัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15485669","locator":"Abstract, opening sentence; 324(3):1108-15","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equus caballus papillomavirus type 1 (EcPV-1) was isolated from a cutaneous papilloma, the most common neoplasm in horses."}},{"id":"equine-medicine--equine-infectious--viral-papillomatosis-หรือหูด--v2","statement":"Sarcoid ซึ่งเป็นโรคที่ต้องแยกจากหูด เกิดจาก bovine papillomavirus type 1 และ 2 ไม่ใช่ EcPV และเป็นเนื้องอกผิวหนังที่พบบ่อยที่สุดของม้าที่มีลักษณะคงอยู่นานและกลับเป็นซ้ำ ต่างจากหูดที่ยุบเอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37336425","locator":"Abstract, opening sentences; 298-299:106011","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection with bovine papillomavirus (BPV) types 1 and 2 results in the most common skin tumor of horses, termed equine sarcoid. The persistent and recurrent nature of this tumor stands in contrast to the regressive nature of BPV-1/-2 induc"}}]},"equine-medicine--equine-infectious--ภาพรวมโรคติดเชื้อในม้า":{"claims":[{"id":"equine-medicine--equine-infectious--ภาพรวมโรคติดเชื้อในม้า--v1","statement":"Hendra virus เป็น henipavirus ที่ติดคนได้และตายสูง ก่อการข้ามสปีชีส์ซ้ำในออสเตรเลียตั้งแต่ปี 1994","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42689109","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Hendra virus (HeV) is a highly lethal zoonotic henipavirus that has caused recurrent cross-species spillover events in Australia since 1994."}}]},"equine-medicine--equine-infectious--rabies":{"claims":[{"id":"equine-medicine--equine-infectious--rabies--v1","statement":"เมื่อม้าแสดงอาการ rabies โรคแทบทุกรายถึงตาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-rabies-in-horses-2026","locator":"Rabies in Horses (owner version), overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Once a horse shows signs of rabies, the disease is almost always fatal."}}]},"equine-medicine--equine-infectious--african-horse-sickness-ahs":{"claims":[{"id":"equine-medicine--equine-infectious--african-horse-sickness-ahs--v1","statement":"ในม้า AHS แพร่โดยริ้นกัด Culicoides เป็นพาหะหลักของไวรัสทั้ง 9 serotypes","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-african-horse-sickness-2026","locator":"Transmission of African Horse Sickness","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Culicoides spp are the principal vectors of all 9 known serotypes of AHSV."}}]},"equine-medicine--equine-infectious--equine-herpesvirus-ehv":{"claims":[{"id":"equine-medicine--equine-infectious--equine-herpesvirus-ehv--v1","statement":"EHV-1 ทำให้แท้งช่วงท้ายของการตั้งท้อง หรือโรคระบบประสาท (EHM) ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-equine-herpesvirus-infection-equine-viral-rhinopneumonit","locator":"Introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"EHV-1 may also cause late term abortions or neurologic disease (equine herpesvirus myeloencephalopathy, EHM)."}}]},"equine-medicine--equine-infectious--equine-infectious-anemia-eia":{"claims":[{"id":"equine-medicine--equine-infectious--equine-infectious-anemia-eia--v1","statement":"EIA แพร่ทางกลไกโดยแมลงดูดเลือด โดยเฉพาะ horse flies และ deer flies","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-equine-infectious-anemia-2026","locator":"Etiology and Epidemiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The principal mode of natural transmission of EIA is mechanical transmission by blood-feeding insects, especially horse flies and deer flies."}}]},"equine-medicine--equine-infectious--equine-influenza":{"claims":[{"id":"equine-medicine--equine-infectious--equine-influenza--v1","statement":"ไวรัส equine influenza ชนิด A subtype H3N8 พบครั้งแรกปี 1963 และกลายเป็นโรคประจำถิ่นในหลายประเทศ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-equine-influenza-2026","locator":"Etiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine influenza (Orthomyxovirus) A/equine type-2 H3N8 was first recognized in 1963 and has subsequently become endemic in many countries."}}]},"equine-medicine--equine-infectious--equine-encephalomyelitis-และ-japanese-encephalitis":{"claims":[{"id":"equine-medicine--equine-infectious--equine-encephalomyelitis-และ-japanese-encephalitis--v1","statement":"ในโรค JE ม้าเป็น dead-end host ส่วนสุกรเป็น amplifier ที่สำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-japanese-encephalitis-aetiology-epidemiology-diagnosis-p","locator":"Epidemiology, Hosts","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses are the primary affected domestic animals of JE though essentially a dead-end host; other equids (donkeys) are also susceptible • Pigs act as important amplifiers of the virus producing high viraemias that infect mosquito vectors"}}]},"equine-medicine--equine-infectious--tetanus":{"claims":[{"id":"equine-medicine--equine-infectious--tetanus--v1","statement":"Tetanus เกิดจากพิษที่สร้างโดยแบคทีเรีย Clostridium tetani ซึ่งพบในดิน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tetanus-in-horses-2026","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The toxin is produced by the bacterium Clostridium tetani"}}]},"equine-medicine--equine-infectious--strangles":{"claims":[{"id":"equine-medicine--equine-infectious--strangles--v1","statement":"Strangles แพร่ทางสัมผัสโดยตรงกับม้าป่วย หรือผ่านอุปกรณ์ที่ปนเปื้อน (fomites)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-strangles-in-horses-2026","locator":"Etiology and Epidemiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Transmission is via direct contact with infected horses or with any number of contaminated fomites."}}]},"equine-medicine--equine-infectious--glanders-และ-contagious-equine-metritis-cem":{"claims":[{"id":"equine-medicine--equine-infectious--glanders-และ-contagious-equine-metritis-cem--v1","statement":"Glanders เป็นโรคติดต่อของ equids ที่มักตาย เกิดจากแบคทีเรีย Burkholderia mallei","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-glanders-in-horses-and-other-equids-2026","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Glanders is a contagious, usually fatal disease of Equidae caused by the bacterium Burkholderia mallei"}}]},"equine-medicine--equine-infectious--trypanosomiasis-และ-equine-piroplasmosis":{"claims":[{"id":"equine-medicine--equine-infectious--trypanosomiasis-และ-equine-piroplasmosis--v1","statement":"Equine piroplasmosis เกิดจาก Theileria equi หรือ Babesia caballi","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-babesiosis-in-animals-2026","locator":"Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine piroplasmosis is caused by Theileria (formerly Babesia ) equi or B caballi"}}]},"equine-medicine--equine-infectious--guttural-pouch-mycosis":{"claims":[{"id":"equine-medicine--equine-infectious--guttural-pouch-mycosis--v1","statement":"Guttural pouch mycosis เป็นการติดเชื้อราที่ guttural pouch ซึ่งสาเหตุที่พบบ่อยคือ Aspergillus","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-guttural-pouch-disease-in-horses-2026","locator":"Guttural Pouch Mycosis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Guttural pouch mycosis is a fungal infection of the guttural pouch. Aspergillus species of fungus are common causes of these infections"}}]},"equine-medicine--equine-infectious--equine-biosecurity":{"claims":[{"id":"equine-medicine--equine-infectious--equine-biosecurity--v1","statement":"Biosecurity คือชุดแนวปฏิบัติด้านการจัดการที่จำกัดการแพร่ของโรค","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-biosecurity-handout-2025","locator":"Page 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Biosecurity is a set of management practices that limit the spread of disease."}}]}},"equine-medicine--equine-rvf":{"equine-medicine--equine-rvf--anatomy-rvf-diagram":{"claims":[{"id":"equine-medicine--equine-rvf--anatomy-rvf-diagram--v1","statement":"Third-degree perineal laceration และ rectovaginal / rectovestibular fistula ในแม่ม้าเป็นการบาดเจ็บที่เกิดตามหลังการคลอด และ rectovaginal fistula formation เองก็เป็นหนึ่งใน complication ของการผ่าตัดซ่อมด้วย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15959984","locator":"vol 53(2), pp 257-264","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Complications of the currently used methods include rectovaginal fistula formation, urine pooling, complete dehiscence of the repair, constipation, tenesmus and difficulty of performance in the practice. ... This method was performed on eig"}}]},"equine-medicine--equine-rvf--anesthesia-approach":{"claims":[{"id":"equine-medicine--equine-rvf--anesthesia-approach--v1","statement":"Epidural xylazine ขนาด 0.17-0.22 mg/kg ให้ caudal analgesia นานอย่างน้อย 3.5 ชั่วโมง ซึ่งเพียงพอสำหรับ perineal procedure เช่น rectovaginal laceration repair โดยม้าไม่เกิด ataxia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2361505","locator":"vol 22(3), pp 180-181","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Xylazine was administered into the epidural space of nine horses to facilitate various perineal manipulations (ie rectovaginal laceration repair, replacement of prolapsed rectum and urethral extension). The resulting caudal analgesia was su"}}]},"equine-medicine--equine-rvf--suture-technique-six-bite-auer-equine-surgery":{"claims":[{"id":"equine-medicine--equine-rvf--suture-technique-six-bite-auer-equine-surgery--v1","statement":"Six-bite suture pattern ใช้ reconstruct ชั้น vestibular shelf / vaginal flap ในการซ่อม third-degree perineal laceration และ rectovestibular fistula ในแม่ม้า (รายงานใช้ polyglactin 910 size 2)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40963117","locator":"vol 21(1), article 538","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"While the vestibular shelf/vaginal flap was reconstructed using size 2 polyglactin 910 suture material in six-bite suture pattern."}}]},"equine-medicine--equine-rvf--post-op-complications":{"claims":[{"id":"equine-medicine--equine-rvf--post-op-complications--v1","statement":"Dehiscence และ fistula formation เป็น complication หลักของการซ่อม third-degree perineal laceration แบบ one-stage โดยในแม่ม้า 17 ตัว มี primary healing 14 ตัว, complete dehiscence 1 ตัว และ partial dehiscence ที่เกิด fistula ตามมา 2 ตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1413472","locator":"vol 21(5), pp 378-381","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Third-degree perineal lacerations or rectovestibular fistulae in 17 mares were repaired surgically by a one-stage method. Primary healing occurred in 14 mares; there were one complete dehiscence and two partial dehiscences with fistula form"}},{"id":"equine-medicine--equine-rvf--post-op-complications--v2","statement":"Breeding prognosis หลังผ่าตัดซ่อมค่อนข้างดี จากแม่ม้า 47 ตัวที่มี third-degree perineal laceration หรือ rectovestibular fistula กลุ่มที่นำไปผสม 32 ตัว ตั้งท้อง 24 ตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3882647","locator":"vol 186(3), pp 265-269","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Of 32 mares bred, 24 became pregnant, suggesting that surgical repair is indicated in any mare with sufficient genetic potential. Perineal trauma after surgical repair was recorded in 3 of 20 mares at subsequent parturition."}}]}},"equine-medicine--equine-pythium":{"equine-medicine--equine-pythium--สาเหตุ-ชื่อเรียก-และการติดต่อ":{"claims":[{"id":"equine-medicine--equine-pythium--สาเหตุ-ชื่อเรียก-และการติดต่อ--v1","statement":"Pythiosis ในม้าเกิดจาก Pythium insidiosum เป็นโรค granulomatous เรื้อรังที่มีแผลที่ผิวหนัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42558222","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pythiosis, caused by Pythium insidiosum, is a chronic granulomatous disease of horses characterized by invasive, ulcerative, and pyogranulomatous cutaneous lesions."}}]},"equine-medicine--equine-pythium--อาการและลักษณะแผล":{"claims":[{"id":"equine-medicine--equine-pythium--อาการและลักษณะแผล--v1","statement":"Pythiosis ผิวหนังพบบ่อยที่สุดในม้า มักเป็นแผลเดี่ยวที่บริเวณขา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38967702","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Cutaneous pythiosis was the most prevalent form, generally presenting as single lesions in the appendicular region"}}]},"equine-medicine--equine-pythium--การวินิจฉัย":{"claims":[{"id":"equine-medicine--equine-pythium--การวินิจฉัย--v1","statement":"ตรวจ anti-P. insidiosum IgG ด้วย immunochromatographic test (ICT) ใช้วินิจฉัย pythiosis ในคนและสัตว์ รวมถึงม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27118800","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This study aims to develop an immunochromatographic test (ICT), using the bacterial protein A/G, to detect anti-P. insidiosum IgGs in humans and animals"}}]},"equine-medicine--equine-pythium--การรักษาและความปลอดภัยของผู้ทำแผล":{"claims":[{"id":"equine-medicine--equine-pythium--การรักษาและความปลอดภัยของผู้ทำแผล--v1","statement":"การรักษา pythiosis ในม้าที่พบบ่อยที่สุดคือการผ่าตัด มักร่วมกับ chemotherapy และ immunotherapy","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38967702","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Various treatments have been employed, with surgery, often combined with chemotherapy and immunotherapy, being the most common."}}]}},"equine-medicine--equine-respi":{"equine-medicine--equine-respi--อาการนำของปัญหาระบบหายใจ-sign-of-respiratory-problems":{"claims":[{"id":"equine-medicine--equine-respi--อาการนำของปัญหาระบบหายใจ-sign-of-respiratory-problems--v1","statement":"ม้าเป็น obligate nasal breather จริง คือหายใจผ่านทางจมูกอย่างเดียวและต้องอาศัยความโล่งของ nasal passage ตลอดเวลา ทำให้การอุดตันของ upper respiratory tract มีผลรุนแรง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20632243","locator":"Abstract, opening sentence; vol 64(7):453-5","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses are obligate nasal breathers and depend on patency of their nasal passages."}}]},"equine-medicine--equine-respi--สมรรถภาพการหายใจขณะออกกำลังกาย-กล่อง-exercise":{"claims":[{"id":"equine-medicine--equine-respi--สมรรถภาพการหายใจขณะออกกำลังกาย-กล่อง-exercise--v1","statement":"อัตราการหายใจขณะควบที่วัดได้คือประมาณ 114 ครั้งต่อนาที ซึ่งใกล้เคียงกับตัวเลขประมาณ 120 ครั้งต่อนาทีที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-14766783","locator":"Abstract, breathing frequency data; vol 96(6):2187-93","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"a reduced breathing frequency [113.8 +/- 5.2 breaths/min (at gallop)"}}]},"equine-medicine--equine-respi--poor-performance-และการเลือกเครื่องมือตรวจตามตำแหน่ง":{"claims":[{"id":"equine-medicine--equine-respi--poor-performance-และการเลือกเครื่องมือตรวจตามตำแหน่ง--v1","statement":"ในม้าแข่ง 275 ตัวที่ประเมินเรื่อง poor performance พบว่า 84% มีปัญหามากกว่าหนึ่งอย่างพร้อมกัน จึงต้องประเมินหลายระบบควบคู่กัน ตรงกับโน้ตที่ว่า respiratory และ cardiovascular เชื่อมโยงกันและแยกคิดทีละระบบไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1884697","locator":"Abstract, results; vol 23(3):169-74","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"84 per cent of the horses were diagnosed as suffering from more than one problem leading to the supposition that inadequate athletic performance is often caused by a constellation of abnormalities requiring a comprehensive approach to diagn"}},{"id":"equine-medicine--equine-respi--poor-performance-และการเลือกเครื่องมือตรวจตามตำแหน่ง--v2","statement":"การส่องกล้อง upper respiratory tract เป็นเครื่องมือหลักของ poor performance จริง เพราะพบ dynamic airway obstruction ถึง 77% ของม้ากีฬาที่ส่งมาตรวจ และม้าส่วนใหญ่ตรวจตอนยืนพักไม่พบความผิดปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17402480","locator":"Abstract, results; issue 36:540-5","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dynamic airway obstructions were diagnosed in 77% of horses and were frequently complex in nature... In the majority of horses, no obvious abnormalities were identified at rest."}}]},"equine-medicine--equine-respi--การตรวจร่างกาย-auscultation-และ-percussion":{"claims":[{"id":"equine-medicine--equine-respi--การตรวจร่างกาย-auscultation-และ-percussion--v1","statement":"การฟังปอดในม้าและการแปลผลเสียงปอดทำได้ยาก จึงต้องใช้ rebreathing auscultation ร่วมกับ percussion ของผนังอกและไซนัส ซึ่งตรงกับโน้ตที่ว่าเอาถุงคลุมจมูกให้ม้าหายใจแรงขึ้น และ percussion ทำคู่กับ auscultation เสมอ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9368972","locator":"Abstract; vol 13(3):443-62","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"auscultation with accurate interpretation of lung sounds can be difficult. However, performing a thorough physical examination, including rebreathing auscultation and percussion of the thorax and sinuses, is very useful in elucidating the p"}},{"id":"equine-medicine--equine-respi--การตรวจร่างกาย-auscultation-และ-percussion--v2","statement":"การทำ rebreathing เพิ่มความไวของการฟังปอดจริง โดยในม้าสูงอายุ 200 ตัว พบความผิดปกติจากการฟังตอนพักเพียง 22% แต่หลังทำ rebreathing มี 13.6% ที่แสดงเสียงผิดปกติชัดเจนเข้าได้กับโรคทางเดินหายใจส่วนล่าง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21668494","locator":"Abstract, respiratory findings; vol 44(1):101-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"22% had abnormalities on thoracic auscultation at rest. Following rebreathing, 13.6% developed marked abnormalities consistent with lower airway disease."}}]},"equine-medicine--equine-respi--การส่องกล้องและการเก็บตัวอย่างจากทางเดินหายใจ":{"claims":[{"id":"equine-medicine--equine-respi--การส่องกล้องและการเก็บตัวอย่างจากทางเดินหายใจ--v1","statement":"BAL คือสิ่งส่งตรวจที่แนะนำสำหรับประเมินการอักเสบของทางเดินหายใจส่วนล่าง โดยใช้สัดส่วน neutrophil มากกว่า 10% เป็นเกณฑ์เข้าได้กับ inflammatory airway disease ส่วน cytology จาก tracheal wash ใช้แทน BAL ไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26806374","locator":"Diagnosis section, BALF cytology; vol 30(2):503-15","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"BALF cytology is recommended in practice to confirm a presumptive diagnosis of IAD based on clinical signs and airway endoscopy... BALF cytology values of >10% neutrophils, >5% mast cells and >5% eosinophils are consistent with IAD"}},{"id":"equine-medicine--equine-respi--การส่องกล้องและการเก็บตัวอย่างจากทางเดินหายใจ--v2","statement":"tracheal wash เป็นตัวอย่างที่ใช้ส่งเพาะเชื้อในทางปฏิบัติจริง โดยเป็นปัจจัยที่สัตวแพทย์อ้างถึงมากที่สุดในการตัดสินใจให้ยาปฏิชีวนะในม้าที่มีปัญหาทางเดินหายใจ คือ 62% ของสัตวแพทย์ 131 คนที่ใช้ยาปฏิชีวนะ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38338101","locator":"Abstract, factors influencing prescription; vol 14(3):457","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most selected factors influencing prescription behavior were: 'tracheal wash culture' (62% of 131 veterinarians using antimicrobials in these cases)"}}]},"equine-medicine--equine-respi--sinusitis":{"claims":[{"id":"equine-medicine--equine-respi--sinusitis--v1","statement":"nasal discharge เป็นอาการนำที่พบมากที่สุดของโรคไซนัสและโพรงจมูกในม้า คือพบ 88% ของทุกราย และ sinoscopy ให้ประโยชน์ในการวินิจฉัย 70% ของรายที่ใช้ ขณะที่ภาพรังสีมีความผิดปกติ 81% แต่ช่วยวินิจฉัยได้จริงเพียง 36% จึงสนับสนุนการใช้ endoscope ผ่าน sinus trepanation","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11352350","locator":"Abstract, clinical signs and ancillary diagnostics; vol 33(3):274-82","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Many disorders showed similar clinical signs including nasal discharge (present in 88% of all cases) and facial swelling (46%)... Radiography revealed abnormalities in 81% of cases but was diagnostically useful in only 36%. Sinoscopy was di"}},{"id":"equine-medicine--equine-respi--sinusitis--v2","statement":"สาเหตุของ sinusitis กำหนดชนิดเชื้อที่พบ โดย dental-related sinusitis สัมพันธ์กับ obligate anaerobe ในสัดส่วนสูงกว่าอย่างมีนัยสำคัญ ส่วน primary sinusitis พบเชื้อจำนวนน้อยกว่าและเป็นกลุ่ม facultative anaerobe และ aerobe เป็นหลัก ซึ่งเข้ากันได้กับการที่สไลด์ระบุ Streptococcus ในกลุ่ม primary","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36199163","locator":"Abstract, results; vol 55(5):798-807","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dental-related sinusitis (n = 44) was associated with a significantly higher proportion of obligate anaerobic bacteria, whereas primary sinusitis (n = 12) and other (n = 10) groups were associated with fewer bacteria and higher proportions "}},{"id":"equine-medicine--equine-respi--sinusitis--v3","statement":"หลักที่ว่า nasal discharge ข้างเดียวชี้ไปทางรอยโรคของทางเดินหายใจส่วนต้นมีหลักฐานรองรับ โดยรอยโรคเฉพาะที่ในโพรงจมูกและไซนัส เช่น empyema ของ nasal conchal bulla เป็นสาเหตุของ chronic unilateral nasal discharge","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25041424","locator":"Abstract, conclusions; vol 47(4):445-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Disease of the conchal bullae should be considered as a potential cause of chronic unilateral nasal discharge in horses."}}]},"equine-medicine--equine-respi--แยกสาเหตุ-head-shaking-ตารางในเอกสาร":{"claims":[{"id":"equine-medicine--equine-respi--แยกสาเหตุ-head-shaking-ตารางในเอกสาร--v1","statement":"trigeminal-mediated headshaking เกิดจากเส้นประสาท trigeminal มี activation threshold ต่ำลง คือไวเกินปกติ และอาการถือเป็นการแสดงออกของ trigeminal neuralgia ตรงกับคอลัมน์ CN V hyperexcitable ในตาราง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31047766","locator":"Abstract, opening sentence; vol 35(2):263-74","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses with trigeminal mediated headshaking (TMHS) have a decreased activation threshold of the trigeminal nerve and clinical signs are suspected to be a manifestation of trigeminal neuralgia."}},{"id":"equine-medicine--equine-respi--แยกสาเหตุ-head-shaking-ตารางในเอกสาร--v2","statement":"อาการของ trigeminal-mediated headshaking เป็นได้ทั้งตามฤดูกาลและต่อเนื่อง และถูกกระตุ้นด้วยแสง เสียง การออกกำลังกาย หรือการสัมผัสบริเวณจมูก ซึ่งตรงกับลักษณะที่ตารางระบุว่าสะบัดแม้ไม่ได้ขี่และแย่ลงกลางแจ้ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41723007","locator":"Abstract; vol 42(1):117-31","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Clinical signs may be seasonal or persistent and triggered by light, sound, exercise, or tactile nasal stimulation."}},{"id":"equine-medicine--equine-respi--แยกสาเหตุ-head-shaking-ตารางในเอกสาร--v3","statement":"sinusitis จัดอยู่ในกลุ่มสาเหตุอื่นของ head shaking ได้จริง แต่พบไม่บ่อย โดยม้าที่วินิจฉัย primary หรือ secondary dental sinusitis และติดตามผลได้ 48 ราย มีเพียง 5 รายที่แสดงพฤติกรรมสะบัดหัว และความผิดปกติของ infraorbital canal บนภาพ CT ไม่ทำนายพฤติกรรมนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36641799","locator":"Abstract, results and conclusions; vol 55(6):1038-44","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Follow-up was obtained in 48/61 cases, with five horses showing headshaking behaviour... Computed tomography changes involving the IOC may not predict headshaking behaviours in sinusitis secondary to dental disease."}}]},"equine-medicine--equine-respi--sinusitis-ในม้า":{"claims":[{"id":"equine-medicine--equine-respi--sinusitis-ในม้า--v1","statement":"Sinusitis ในม้าแบ่งเป็น primary และ secondary โดย secondary sinusitis เกิดตามโรคอื่น เช่น การติดเชื้อที่ปลายรากฟัน sinus cyst หรือก้อนในบริเวณ ethmoturbinate","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24467610","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Underlying diseases were primary (n = 1) and secondary sinusitis (4) because of apical dental infection (1), sinus cyst (2), or masses in the ethmoturbinate region (2)."}}]},"equine-medicine--equine-respi--การหายใจขณะพักและขณะออกกำลัง-poor-performance":{"claims":[{"id":"equine-medicine--equine-respi--การหายใจขณะพักและขณะออกกำลัง-poor-performance--v1","statement":"ขณะควบ ม้ามีรูปแบบการหายใจที่เชื่อมกับจังหวะการเคลื่อนที่ (locomotor-respiratory coupling)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17402485","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Locomotor-respiratory coupled (LRC) breath types are a feature of galloping exercise in horses."}}]},"equine-medicine--equine-respi--การเก็บตัวอย่าง-ttw-bal-thoracocentesis-sinocentesis":{"claims":[{"id":"equine-medicine--equine-respi--การเก็บตัวอย่าง-ttw-bal-thoracocentesis-sinocentesis--v1","statement":"Transtracheal aspirate ใช้เก็บตัวอย่างสำหรับ cytology และเพาะเชื้อในม้าที่สงสัย lower respiratory tract disease","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39693736","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Transtracheal aspirate is indicated to collect samples for cytology and bacteriologic culture in cases of suspected pneumonia or other lower respiratory tract disease."}}]},"equine-medicine--equine-respi--ethmoid-hematoma":{"claims":[{"id":"equine-medicine--equine-respi--ethmoid-hematoma--v1","statement":"Progressive ethmoidal hematoma รักษาด้วยการฉีด 4% formaldehyde ผ่านกล้อง endoscope เข้าก้อนโดยตรง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9605229","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"PEHs were injected transendoscopically with 4% formaldehyde solution."}}]},"equine-medicine--equine-respi--guttural-pouch-empyema-mycosis-tympany":{"claims":[{"id":"equine-medicine--equine-respi--guttural-pouch-empyema-mycosis-tympany--v1","statement":"Guttural pouch empyema คือการสะสม purulent exudate ในกระพุ้งคอ มักตามหลังการติดเชื้อแบคทีเรีย (ส่วนใหญ่ Streptococcus spp.) ของทางเดินหายใจส่วนบน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-guttural-pouch-disease-in-horses-2023","locator":"Guttural pouch empyema","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Guttural pouch empyema is defined as unilateral or bilateral accumulation of purulent exudate in the guttural pouch. The infection usually develops subsequent to a bacterial (primarily Streptococcus spp) infection of the upper respiratory tract."}}]},"equine-medicine--equine-respi--pharynx-และ-larynx-lymphoid-hyperplasia-ddsp-epiglottic-entrapme":{"claims":[{"id":"equine-medicine--equine-respi--pharynx-และ-larynx-lymphoid-hyperplasia-ddsp-epiglottic-entrapme--v1","statement":"DDSP คือภาวะที่ขอบ caudal ของ soft palate เคลื่อนขึ้นไปอยู่เหนือ epiglottis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-dorsal-displacement-of-the-soft-palate-in-horses-2023","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dorsal displacement of the soft palate (DDSP) occurs when the caudal free-margin of the soft palate displaces dorsal to the epiglottis."}}]},"equine-medicine--equine-respi--pneumonia-pleuropneumonia-pleural-effusion":{"claims":[{"id":"equine-medicine--equine-respi--pneumonia-pleuropneumonia-pleural-effusion--v1","statement":"Streptococcus equi zooepidemicus เป็นเชื้อที่แยกได้บ่อยที่สุดในม้าที่เป็น pleuropneumonia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-pleuropneumonia-in-horses-pleuritis-pleurisy-2023","locator":"Etiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Streptococcus equi zooepidemicus is most frequently isolated."}}]},"equine-medicine--equine-respi--equine-asthma-iad-และ-rao":{"claims":[{"id":"equine-medicine--equine-respi--equine-asthma-iad-และ-rao--v1","statement":"Neutrophilic airway inflammation เป็นลักษณะของ severe equine asthma ส่วน mild-moderate asthma อาจเป็น neutrophilic, eosinophilic หรือ mastocytic ผสมกันได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-asthma-in-horses-heaves-recurrent-airway-obstruction-inf","locator":"Pathophysiology of equine asthma","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Neutrophilic airway inflammation characterizes severe equine asthma while mild-moderate asthma can present as any combination of neutrophilic, eosinophilic, or mastocytic inflammation."}}]},"equine-medicine--equine-respi--exercise-induced-pulmonary-hemorrhage-eiph":{"claims":[{"id":"equine-medicine--equine-respi--exercise-induced-pulmonary-hemorrhage-eiph--v1","statement":"Epistaxis พบเพียงส่วนน้อย (~5%) ของม้าที่เป็น EIPH ส่วนการส่องกล้องพบเลือดใน tracheobronchial tree 45-75% ของม้าแข่ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-exercise-induced-pulmonary-hemorrhage-in-horses-2023","locator":"Etiology and Pathogenesis","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Epistaxis is seen in a small proportion (~5%) of horses with EIPH. Blood in the tracheobronchial tree is identified in 45%–75% of racehorses via endoscopic examination"}}]}},"equine-medicine--equine-neonatal":{"equine-medicine--equine-neonatal--อายุครรภ์-และนมน้ำเหลืองกับการรับภูมิคุ้มกัน":{"claims":[{"id":"equine-medicine--equine-neonatal--อายุครรภ์-และนมน้ำเหลืองกับการรับภูมิคุ้มกัน--v1","statement":"Colostrum คุณภาพดีมีลักษณะเหนียว สีเหลือง ข้น และมี specific gravity > 1.060 ในแม่ม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-failure-of-transfer-of-passive-immunity-in-large-animals","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Good-quality colostrum tends to be sticky, yellow, and thick with a specific gravity of > 1.060 in mares."}}]},"equine-medicine--equine-neonatal--ระยะคลอดในส่วนที่เกี่ยวกับลูกม้า":{"claims":[{"id":"equine-medicine--equine-neonatal--ระยะคลอดในส่วนที่เกี่ยวกับลูกม้า--v1","statement":"รกม้า (fetal membranes) โดยปกติถูกขับออกภายใน 3 ชั่วโมงหลังคลอด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-retained-fetal-membranes-in-mares-2022","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine fetal membranes are normally expelled within 3 hours after parturition"}}]},"equine-medicine--equine-neonatal--การดูแลลูกม้าหลังคลอดทันที":{"claims":[{"id":"equine-medicine--equine-neonatal--การดูแลลูกม้าหลังคลอดทันที--v1","statement":"ลูกม้าน้ำหนัก 50 kg ควรได้ colostrum คุณภาพดีอย่างน้อย 1.5-2 L (ราว 70-75 g IgG) แบ่งให้หลายมื้อในช่วง 12-18 ชั่วโมงแรกหลังคลอด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-failure-of-transfer-of-passive-immunity-in-large-animals","locator":"Treatment and prevention","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A 50-kg foal requires a minimum 1.5–2 L (ideally 5%–12% of body wt) of good-quality colostrum (~70–75 g of IgG), fed over multiple feedings in the first 12–18 hours after birth."}}]},"equine-medicine--equine-neonatal--ลูกม้ากำพร้า-การหย่านม-วัคซีน-และการถ่ายพยาธิ":{"claims":[{"id":"equine-medicine--equine-neonatal--ลูกม้ากำพร้า-การหย่านม-วัคซีน-และการถ่ายพยาธิ--v1","statement":"ลูกม้าที่เกิดจากแม่ที่ได้รับวัคซีนและได้ colostrum มักมีภูมิคุ้มกันป้องกันโรคได้ถึงราว 6 เดือน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-vaccinations-for-a-horse-2025","locator":"Foals","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Foals (young horses) born to vaccinated mothers usually have protection from diseases for up to 6 months if they drink the mare's colostrum"}}]},"equine-medicine--equine-neonatal--ความผิดปกติที่พบบ่อยในลูกม้าแรกเกิด":{"claims":[{"id":"equine-medicine--equine-neonatal--ความผิดปกติที่พบบ่อยในลูกม้าแรกเกิด--v1","statement":"Meconium impaction ในลูกม้ามักตอบสนองต่อการรักษาทางยา ซึ่งมี enema เป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-meconium-impaction-in-foals-2022","locator":"Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Many cases of meconium impaction respond to medical therapy, including judicious use of analgesics, IV fluid therapy, oral laxatives (4–8 oz mineral oil administered via a nasogastric tube; 1–2 oz milk of magnesia), and enemas as the mainstay of therapy."}}]},"equine-medicine--equine-neonatal--neonatal-isoerythrolysis-ni":{"claims":[{"id":"equine-medicine--equine-neonatal--neonatal-isoerythrolysis-ni--v1","statement":"ม้ามี major blood groups 8 กลุ่ม (A, C, D, K, P, Q, U, T) และภาวะ NI เป็นโรคภูมิคุ้มกันของลูกม้าที่เกิดจากหมู่เลือดแม่กับลูกเข้ากันไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-blood-groups-and-blood-transfusions-in-horses-2019","locator":"Blood groups","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This immune disorder in the foal is called neonatal isoerythrolysis. In horses there are 8 major blood groups: A, C, D, K, P, Q, U, and T."}}]}},"equine-medicine--equine-anesthesia":{"equine-medicine--equine-anesthesia--complete-history-taking-หา-hidden-sign-ที่เพิ่มความเสี่ยงการวางย":{"claims":[{"id":"equine-medicine--equine-anesthesia--complete-history-taking-หา-hidden-sign-ที่เพิ่มความเสี่ยงการวางย--v1","statement":"Hyperkalaemic periodic paralysis (HYPP) ในม้า Quarter Horse สามารถแสดงอาการขึ้นมาระหว่างการวางยาสลบได้จริง โดยพบ hyperkalaemia ร่วมกับ muscle fasciculation, sinus tachycardia และ hypercapnoea ระหว่าง isoflurane anaesthesia ดังนั้นการซักประวัติสายพันธุ์และ HYPP ก่อนวางยาจึงเป็น hidden risk ที่ต้องถาม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21303442","locator":"Vol 38(2), pp. 113-120, Case summary and Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"signs consistent with hyperkalaemic periodic paralysis (HYPP) were exhibited. These included concurrent hyperkalaemia, hypercapnoea, sinus tachycardia, and muscle fasciculations in the presence of normothermia."}},{"id":"equine-medicine--equine-anesthesia--complete-history-taking-หา-hidden-sign-ที่เพิ่มความเสี่ยงการวางย--v2","statement":"ประวัติว่าเคยวางยาสลบมาก่อนแล้วไม่มีปัญหา ไม่สามารถใช้ตัดความเสี่ยง HYPP ออกได้ เพราะม้าตัวเดียวกันเคยผ่านการวางยาโดยไม่มีอาการมาก่อนหน้านั้นเพียง 1 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21303442","locator":"Vol 38(2), Conclusions and clinical relevance","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Clinical cases of intra-operative HYPP can present despite a previous history of uneventful general anaesthesia."}},{"id":"equine-medicine--equine-anesthesia--complete-history-taking-หา-hidden-sign-ที่เพิ่มความเสี่ยงการวางย--v3","statement":"Postanaesthetic rhabdomyolysis (postanesthetic myopathy) ทำให้ม้าลุกยืนช้าในช่วง recovery และอาจต้องการุณยฆาตจากการนอนไม่ลุก จึงเป็นความเสี่ยงจริงที่ประวัติกล้ามเนื้อ/การขนส่งควรถูกซักก่อนวางยา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39454622","locator":"Vol 263(2), pp. 248-258, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Time to standing in recovery was prolonged, 3 horses were euthanized due to persistent recumbency, and rhabdomyolysis recurred in 4 horses 5 to 11 days after anesthesia"}}]},"equine-medicine--equine-anesthesia--งดอาหารและน้ำก่อนผ่าตัด-ชุด-hospital-based":{"claims":[{"id":"equine-medicine--equine-anesthesia--งดอาหารและน้ำก่อนผ่าตัด-ชุด-hospital-based--v1","statement":"การมี reflux จากการใส่ nasogastric tube เป็นเกณฑ์หลักที่ผู้เชี่ยวชาญใช้นิยาม postoperative ileus (POI) หลังผ่าตัดช่องท้อง และการกำหนดจังหวะให้อาหารหลังผ่าตัดอย่างระมัดระวังเป็นหนึ่งในกลยุทธ์จัดการ POI จึงสอดคล้องกับการรอให้ reflux และ POI ทุเลาก่อนเริ่มให้อาหาร","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25256601","locator":"Vol 48(2), pp. 182-187, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The presence of reflux on nasogastric intubation was the main criterion used to define POI... Supplementary preventative and treatment strategies for POI included control of endotoxaemia, fluid therapy, early ambulation and judicious timing"}}]},"equine-medicine--equine-anesthesia--asa-physical-status-classification":{"claims":[{"id":"equine-medicine--equine-anesthesia--asa-physical-status-classification--v1","statement":"การเติมตัว E ต่อท้าย ASA class หมายถึงหัตถการฉุกเฉิน โดยนิยามว่าภาวะฉุกเฉินคือสถานการณ์ที่การเลื่อนการรักษาออกไปจะเพิ่มภัยคุกคามต่อชีวิตหรืออวัยวะอย่างมีนัยสำคัญ ตรงกับที่สไลด์เขียนไว้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-statpearls-publishing--2024","locator":"Section: Function, Emergency modifier","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The addition of 'E' to the ASA physical status classification system, for example, ASA 2E, denotes an emergency surgical procedure. According to the ASA, an emergency is defined as a situation in which a delay in treating the patient signif"}}]},"equine-medicine--equine-anesthesia--preoperative-preparation-ในสนาม-การจัดท่าและอุปกรณ์":{"claims":[{"id":"equine-medicine--equine-anesthesia--preoperative-preparation-ในสนาม-การจัดท่าและอุปกรณ์--v1","statement":"ม้าที่ไม่ได้ถูกจัดท่า dorsal recumbency มีความเสี่ยงตายจากการวางยาต่ำกว่าม้าที่จัดท่านอนหงาย (risk ratio 0.3-0.5) จากข้อมูล CEPEF-1 ซึ่งสนับสนุนคำแนะนำในสไลด์ที่ว่า lateral recumbency ดีกว่า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7556046","locator":"Vol 27(3), pp. 193-200, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Patients not placed in dorsal recumbency were at reduced risk (RR = 0.3-0.5) compared to those which were in dorsal recumbency."}},{"id":"equine-medicine--equine-anesthesia--preoperative-preparation-ในสนาม-การจัดท่าและอุปกรณ์--v2","statement":"ยาสลบส่วนใหญ่ทำให้เกิด arterial hypotension และเลือดไปเลี้ยง capillary ลดลง ซึ่งนำไปสู่ postanesthetic myopathy จึงเป็นเหตุผลเชิงกลไกว่าทำไมต้องรองพื้นให้นุ่มและจัดท่าให้ลดแรงกดทับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20731183","locator":"Vol 13(2), pp. 287-292, Introduction/abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The majority of general anesthetics used in veterinary practice lead to arterial hypotension, decreased capillary perfusion and ventilatory depression leading to pathological changes referred to as postanesthetic myopathy."}}]},"equine-medicine--equine-anesthesia--pain-management":{"claims":[{"id":"equine-medicine--equine-anesthesia--pain-management--v1","statement":"Opioid ในม้าทำให้เกิด excitement จริง โดยการผสม butorphanol เข้ากับ detomidine ทำให้ผลต่อรูปแบบการเดินสั้นลงกว่าการใช้ detomidine เดี่ยว ซึ่งผู้วิจัยอธิบายว่าเกิดจาก excitement ที่ opioid กระตุ้น สนับสนุนคำแนะนำในสไลด์ที่ให้ opioid หลังจากม้าซึมแล้วเท่านั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30866108","locator":"Vol 51(6), pp. 825-830, Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The combination of detomidine and butorphanol produces a shorter effect on almost all accelerometric parameters, probably due to the excitement produced by the opioid drug causing a quicker return to normal values."}},{"id":"equine-medicine--equine-anesthesia--pain-management--v2","statement":"พฤติกรรมตื่นเต้นที่ opioid เหนี่ยวนำในม้าไม่ใช่แค่ทฤษฎี แต่รบกวนการประเมินความปวดจริง โดยในงานวิจัยหนึ่ง buprenorphine ทำให้ pain scale EQUUS-FAP ใช้ไม่ได้เพราะพฤติกรรม excitement","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34975166","locator":"Vol 63(1), pp. 39-46, Results/conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the EQUUS-FAP pain scale became unreliable because of BUP-induced excitement behavior."}}]},"equine-medicine--equine-anesthesia--restraint-physical-และ-chemical":{"claims":[{"id":"equine-medicine--equine-anesthesia--restraint-physical-และ-chemical--v1","statement":"Alpha-2 adrenoceptor agonist เป็นกลุ่มยาที่ใช้บ่อยที่สุดในการทำ chemical restraint ของม้าสำหรับหัตถการวินิจฉัยและผ่าตัดเล็ก ตรงกับที่สไลด์ระบุ xylazine และ detomidine","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30866108","locator":"Vol 51(6), pp. 825-830, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Chemical restraint is often used to perform diagnostic and minor surgical procedures; alpha-adrenoceptor agonists are the most commonly used drugs"}},{"id":"equine-medicine--equine-anesthesia--restraint-physical-และ-chemical--v2","statement":"การเลือกทำหัตถการแบบยืน (standing sedation) แทนการวางยาสลบมีผลต่อความเสี่ยงตายอย่างมาก โดยข้อมูล CEPEF4 พบอัตราตายภายใน 7 วันของ standing sedation อยู่ที่ 0.2% เทียบกับ 1.0% ของ general anaesthesia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34573515","locator":"Vol 11(9), 2549, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the overall mortality rate for general anaesthesia within the seven-day outcome period was 1.0%... For standing sedations, the overall mortality rate was 0.2%."}}]},"equine-medicine--equine-anesthesia--recovery-ช่วงที่เสี่ยงที่สุดของทั้งกระบวนการ":{"claims":[{"id":"equine-medicine--equine-anesthesia--recovery-ช่วงที่เสี่ยงที่สุดของทั้งกระบวนการ--v1","statement":"ช่วง recovery เป็นช่วงที่การตายเกิดขึ้นเด่นชัดในการวางยาสลบม้ายุคปัจจุบัน โดย catastrophic fracture กลายเป็นสาเหตุการตายอันดับหนึ่งที่สัมพันธ์กับช่วง recovery หลังยุคที่เลิกใช้ halothane เป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26970940","locator":"Vol 43(3), pp. 242-255, Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Catastrophic fractures, however, have become the greatest cause of recovery-associated mortality."}}]},"equine-medicine--equine-anesthesia--key-takeaways-ของ-field-anesthesia":{"claims":[{"id":"equine-medicine--equine-anesthesia--key-takeaways-ของ-field-anesthesia--v1","statement":"แม้ยาและการ monitor จะพัฒนาขึ้น ความเสี่ยงตายจากการวางยาสลบในม้าก็ยังสูงกว่าสัตว์เลี้ยงชนิดอื่นและมนุษย์ โดยลดจากราว 1% ในปี 2002 มาเป็นราว 0.6% ในม้าสุขภาพดี แต่ยังถือว่าร้ายแรง สนับสนุนข้อสรุปในสไลด์ที่ให้ยึดความปลอดภัยไว้ก่อน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40914732","locator":"Vol 52(6), pp. 720-729, Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These changes appear to be associated with a decrease in the mortality risk in healthy horses from around 1% in 2002 to 0.6% in 2025. However, the risk of mortality is still serious"}}]},"equine-medicine--equine-anesthesia--field-based-surgery-คืออะไร-และเตรียมสัตว์อย่างไร":{"claims":[{"id":"equine-medicine--equine-anesthesia--field-based-surgery-คืออะไร-และเตรียมสัตว์อย่างไร--v1","statement":"ม้าในงานเดียวกันได้รับน้ำอย่างอิสระตลอดช่วงก่อนวางยา ตรงกับที่สไลด์ระบุว่าไม่จำกัดน้ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25935721","locator":"Methods, animals and preparation","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All the animals were fasted for 6 hours before anaesthesia, but free access to the water was granted."}}]},"equine-medicine--equine-anesthesia--monitoring-และ-safety-ในสนาม":{"claims":[{"id":"equine-medicine--equine-anesthesia--monitoring-และ-safety-ในสนาม--v1","statement":"Nystagmus เกิดขึ้นได้จริงในม้าที่วางยาด้วย ketamine โดยพบทั้งช่วงต้นของการวางยา ช่วงที่ถูกกระตุ้นด้วยการดึงอัณฑะ และตลอดการผ่าตัดในบางตัว ตรงกับที่สไลด์ระบุว่า nystagmus จากฤทธิ์ ketamine เกิดขึ้นได้ และเป็นเหตุผลว่าทำไมตำแหน่งตากับ reflex ต้องอ่านร่วมกับ muscle tone และการหายใจ ไม่ใช่ดูอย่างเดียว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25935721","locator":"Results, clinical observations","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nystagmus was observed at the beginning of anaesthesia in 2 horses, when the testicles were pulled in 2 other horses, and during the whole surgical procedure in 3 horses."}},{"id":"equine-medicine--equine-anesthesia--monitoring-และ-safety-ในสนาม--v2","statement":"การเติมยาซ้ำเพื่อยืดเวลา surgical anaesthesia ในสนามใช้ขนาดที่ต่ำกว่าโด๊สนำสลบชัดเจน ในงานนี้ม้า 7 ตัวจาก 28 ตัวต้องได้ S-ketamine เพิ่ม โดยโด๊สเสริมคือ 1 มก./กก. เทียบกับโด๊สนำสลบ 2.5 มก./กก. ซึ่งอยู่ระหว่างหนึ่งในสามถึงครึ่งหนึ่งตามที่สไลด์แนะนำ และการเติมซ้ำไม่ทำให้คุณภาพการฟื้นแย่ลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25935721","locator":"Abstract and Results, redosing","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Seven horses required additional administration of S-ketamine to prolong the duration of surgical anaesthesia. Redosing did not compromise recovery quality."}}]},"equine-medicine--equine-anesthesia--ทำไมการวางยาม้าจึงต่างออกไป":{"claims":[{"id":"equine-medicine--equine-anesthesia--ทำไมการวางยาม้าจึงต่างออกไป--v1","statement":"หลังวางยาสลบม้าอาจเกิด myopathy จาก hypoperfusion ของกล้ามเนื้อที่ถูกกดทับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-traumatic-toxic-and-anesthetic-myopathies-in-horses-2026","locator":"Postanesthetic Myopathy","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After anesthesia, horses may develop severe muscle pain and weakness in one or more muscle groups. Hypoperfusion of compressed muscle groups with resultant high intracompartmental pressure is the most important causative factor for focal muscle involvement."}}]},"equine-medicine--equine-anesthesia--ประเมินก่อนวางยา":{"claims":[{"id":"equine-medicine--equine-anesthesia--ประเมินก่อนวางยา--v1","statement":"ในการศึกษา CEPEF4 (ม้า 47,396 ตัว) odds ของการตายเพิ่มขึ้นใน ASA grade สูงขึ้นและหัตถการเร่งด่วน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40695694","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Logistic regression analyses revealed an increase in the odds of death for pregnant mares, geriatrics, thin horses, those with a higher American Society of Anesthesiologists grade, urgent procedures and those lasting < 1 hour or > 2 hours."}}]},"equine-medicine--equine-anesthesia--เลือก-standing-หรือ-general-anesthesia":{"claims":[{"id":"equine-medicine--equine-anesthesia--เลือก-standing-หรือ-general-anesthesia--v1","statement":"standing sedation เป็นทางเลือกที่ปลอดภัยและคุ้มค่ากว่า general anesthesia ในม้า แต่ต้องให้ยาพอบล็อก stimulus response โดยไม่ทำให้ ataxia หรือล้มนอน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41200548","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Standing sedation is a safe and cost-effective alternative to general anesthesia in horses, but challenges include achieving adequate drug effect to block the stimulus response without inducing ataxia or recumbency."}}]},"equine-medicine--equine-anesthesia--sedation-alpha-2-agonists-และ-tranquilizers":{"claims":[{"id":"equine-medicine--equine-anesthesia--sedation-alpha-2-agonists-และ-tranquilizers--v1","statement":"หลังใช้ acepromazine ในม้าพบ penile prolapse ค้างได้ และเสี่ยงมากขึ้นเมื่อโดสสูง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tranquilizers-sedatives-and-analgesics-for-treatment-of","locator":"Acepromazine, Pearls & Pitfalls","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In horses, persistent penile prolapse has been reported after the use of acepromazine and might depend on the dose, with higher doses being associated with increased risk."}}]},"equine-medicine--equine-anesthesia--opioids-neuroleptanalgesia-guaifenesin-และยาชาเฉพาะที่":{"claims":[{"id":"equine-medicine--equine-anesthesia--opioids-neuroleptanalgesia-guaifenesin-และยาชาเฉพาะที่--v1","statement":"การเติม butorphanol และ midazolam ขนาดต่ำเข้ากับ detomidine CRI ทำให้ sedation เพิ่มขึ้นเป็นขั้นและ ataxia เพิ่มขึ้นด้วย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41200548","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the sequential addition of low-dose CRIs of butorphanol and midazolam to detomidine CRIs is associated with a stepwise increase in sedation and ataxia."}}]},"equine-medicine--equine-anesthesia--induction-และ-intubation":{"claims":[{"id":"equine-medicine--equine-anesthesia--induction-และ-intubation--v1","statement":"งานเปรียบเทียบ induction ในม้าใช้ xylazine 1 mg/kg ร่วมกับ ketamine 2 mg/kg เป็น protocol มาตรฐานก่อนวางยา TIVA ด้วย guaifenesin-ketamine-xylazine","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42716191","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"randomly assigned to XC (xylazine 1 mg/kg and ketamine 2 mg/kg) or XCM (xylazine 0.5 mg/kg, ketamine 2 mg/kg, and midazolam 0.1 mg/kg). Anesthesia was maintained with continuous guaifenesin, ketamine, and xylazine infusion."}}]},"equine-medicine--equine-anesthesia--ท่านอนและการป้องกันการบาดเจ็บ":{"claims":[{"id":"equine-medicine--equine-anesthesia--ท่านอนและการป้องกันการบาดเจ็บ--v1","statement":"ภาวะ arterial oxygen ต่ำเป็นภาวะแทรกซ้อนที่พบบ่อยในม้าที่วางยาสลบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33066990","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Low arterial oxygen is a common complication in anesthetized horses"}}]},"equine-medicine--equine-anesthesia--maintenance-inhalant-mac-tiva-piva":{"claims":[{"id":"equine-medicine--equine-anesthesia--maintenance-inhalant-mac-tiva-piva--v1","statement":"ในม้า การคงสลบด้วย isoflurane หรือ sevoflurane ทำที่ความเข้มข้น 1.2 เท่าของ minimum alveolar concentration (MAC)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22126682","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Anesthesia was maintained for 2 hours with isoflurane or sevoflurane at 1.2 times the minimum alveolar concentration"}}]},"equine-medicine--equine-anesthesia--monitoring":{"claims":[{"id":"equine-medicine--equine-anesthesia--monitoring--v1","statement":"ภาวะความดันต่ำระหว่างวางยาม้านิยามที่ MAP ต่ำกว่า 70 mmHg และแก้ด้วยสารน้ำและ dobutamine","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16476002","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"hypotension was redefined as MAP <70 mmHg, and was managed using high-volume fluid therapy and dobutamine"}}]},"equine-medicine--equine-anesthesia--ยาเสริม-inotropes-vasopressors-anticholinergics":{"claims":[{"id":"equine-medicine--equine-anesthesia--ยาเสริม-inotropes-vasopressors-anticholinergics--v1","statement":"ในม้าที่วางยาสลบด้วย isoflurane หรือ sevoflurane ใช้ dobutamine infusion เพื่อคงความดันให้ปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22126682","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Normotension was maintained via a dobutamine infusion."}}]},"equine-medicine--equine-anesthesia--multimodal-analgesia-และ-nsaids":{"claims":[{"id":"equine-medicine--equine-anesthesia--multimodal-analgesia-และ-nsaids--v1","statement":"right dorsal colitis ทำให้ colic เรื้อรังและสัมพันธ์กับการใช้ NSAIDs ระยะยาวในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38113643","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Right dorsal colitis causes chronic colic associated with long-term treatment with nonsteroidal antiinflammatory drugs (NSAIDs)."}}]},"equine-medicine--equine-anesthesia--recovery-และภาวะแทรกซ้อน":{"claims":[{"id":"equine-medicine--equine-anesthesia--recovery-และภาวะแทรกซ้อน--v1","statement":"กระดูกหักรุนแรง (catastrophic fracture) เป็นสาเหตุหลักของการตายช่วง recovery จากการวางยาสลบม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26970940","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Catastrophic fractures, however, have become the greatest cause of recovery-associated mortality."}}]},"equine-medicine--equine-anesthesia--การวางยาภาคสนาม-field-anesthesia":{"claims":[{"id":"equine-medicine--equine-anesthesia--การวางยาภาคสนาม-field-anesthesia--v1","statement":"โปรโตคอลวางยาภาคสนามในม้าต้องให้ระยะเวลาและความลึกพอ โดยไม่เสียความปลอดภัยหรือคุณภาพการฟื้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31965616","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The ideal field anaesthetic protocol for castration will offer an adequate duration and depth of anaesthesia using a single injection without compromising safety or recovery quality."}}]},"equine-medicine--equine-anesthesia--การุณยฆาต":{"claims":[{"id":"equine-medicine--equine-anesthesia--การุณยฆาต--v1","statement":"AAEP ยอมรับ potassium chloride หรือ magnesium sulfate เข้มข้นทางหลอดเลือดดำ เมื่อม้าอยู่ใน surgical plane ของ general anesthesia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-euthanasia-guidelines-2026","locator":"Acceptable euthanasia techniques list","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A concentrated solution of either potassium chloride (intravenous) or magnesium sulfate (intravenous) with the horse in a surgical plane of general anesthesia."}}]}},"equine-medicine--equine-acupuncture":{"equine-medicine--equine-acupuncture--tcvm-theory-cases":{"claims":[{"id":"equine-medicine--equine-acupuncture--tcvm-theory-cases--v1","statement":"systematic review ของ controlled clinical trials ทาง veterinary acupuncture (randomized controlled trials 14 เรื่อง และ nonrandomized controlled trials 17 เรื่อง) สรุปว่ายังไม่มีหลักฐานหนักแน่นพอที่จะแนะนำหรือปฏิเสธ acupuncture สำหรับภาวะใดๆ ในสัตว์เลี้ยง โดยคุณภาพ methodology ของ trial เหล่านี้ประเมินด้วย Jadad score แล้วอยู่ในระดับต่ำโดยเฉลี่ย และมีเพียง cutaneous pain กับ diarrhea ที่ข้อมูลชวนให้ศึกษาต่อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16734078","locator":"J Vet Intern Med 20(3):480-488, Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"there is no compelling evidence to recommend or reject acupuncture for any condition in domestic animals"}},{"id":"equine-medicine--equine-acupuncture--tcvm-theory-cases--v2","statement":"ใน randomized controlled crossover ในม้า 8 ตัว การทำ electroacupuncture 2 ชั่วโมงที่จุด Bladder 21, Bladder 25 และ Bladder 27 ทั้งสองข้าง ร่วมกับ Bai hui และ Stomach 36 (ข้างขวา) เพิ่ม rectal pain threshold ได้ แต่ได้น้อยกว่า butorphanol 0.1 mg/kg IV (174 ± 35 เทียบกับ 214 ± 24 mmHg balloon pressure) ขณะที่ electroacupuncture ทำให้เกิดการเปลี่ยนแปลงทาง cardiovascular และ respiratory น้อยมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12602580","locator":"Am J Vet Res 64(2):137-144, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Butorphanol produced greater increases in rectal pain threshold, compared with EA (mean +/- SD, 214 +/- 24 vs 174 +/- 35 mm Hg of balloon pressure)."}},{"id":"equine-medicine--equine-acupuncture--tcvm-theory-cases--v3","statement":"prospective randomized single-blinded crossover pilot ในม้า 8 ตัว พบว่า acupuncture 3 ครั้งภายใน 8 วัน ลด hip hike difference อย่างมีนัยสำคัญในทุกเงื่อนไขการเดิน (เช่น control 6.3 ± 6.4 mm เทียบกับ treatment -0.2 ± 6.4 mm, p = 0.007) และลด subjective lameness score (OR 0.51, 95% CI 0.34-0.78) แต่ global score ไม่ต่างกันอย่างมีนัยสำคัญ (OR 0.53, p = 0.12)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26946316","locator":"Vet Anaesth Analg 44(1):154-162, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Acupuncture can change horses' gaits to a degree appreciable by objective and subjective analyses."}},{"id":"equine-medicine--equine-acupuncture--tcvm-theory-cases--v4","statement":"ใน controlled blinded randomized block pilot (ม้า 4 ตัว, ทำ corneal epithelial debridement) กลุ่ม electroacupuncture ได้ ocular pain score รวม 1356 ซึ่งดีกว่า control 1580 และดีกว่า phenylbutazone 1397 แต่กลุ่มเดียวที่ต่างจาก control อย่างมีนัยสำคัญคือ flunixin meglumine (score 1114, p = 0.01 ในช่วง 46 ชั่วโมงแรก) ผู้เขียนจึงสรุปว่า flunixin meglumine ลดปวดตาได้ดีที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33663725","locator":"J Equine Vet Sci 98:103375, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Flunixin meglumine was the most effective treatment at reducing ocular pain in the horse."}},{"id":"equine-medicine--equine-acupuncture--tcvm-theory-cases--v5","statement":"overview of systematic reviews ที่ตีพิมพ์ระหว่าง ค.ศ. 2000-2022 ประเมิน systematic review ของ veterinary acupuncture ด้วยเครื่องมือ AMSTAR 2 แล้วพบว่าอยู่ในระดับคุณภาพต่ำทั้งหมด จนไม่สามารถประเมินความน่าเชื่อถือของ primary RCT และ CCT 35 เรื่องที่รวมอยู่ในนั้นได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39284363","locator":"Homeopathy 114(2):106-116, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The systematic reviews of acupuncture and phytotherapy were all of low quality, preventing formal assessment of their reviewed RCTs/CCTs."}}]},"equine-medicine--equine-acupuncture--covering-topics-3-หมวด":{"claims":[{"id":"equine-medicine--equine-acupuncture--covering-topics-3-หมวด--v1","statement":"scoping review ของหลักฐาน acupuncture ในสัตว์เลี้ยง (สุนัข แมว ม้า) พบ citation ที่เกี่ยวข้อง 843 เรื่อง โดย narrative review เป็นสัดส่วนมากที่สุด (43%) มี experimental studies 179 เรื่อง และ case report หรือ case series 175 เรื่อง สุนัขเป็นสัตว์ที่ถูกศึกษามากที่สุด และ musculoskeletal conditions เป็นข้อบ่งใช้ที่พบบ่อยที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29224586","locator":"Anim Health Res Rev 18(2):177-185, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We identified 179 experimental studies and 175 case reports/case series that examined the efficacy of acupuncture."}}]}},"equine-medicine--equine-parasites":{"equine-medicine--equine-parasites--แผนที่ตำแหน่งของปรสิตในม้า":{"claims":[{"id":"equine-medicine--equine-parasites--แผนที่ตำแหน่งของปรสิตในม้า--v1","statement":"ระยะตัวอ่อนของ Strongylus vulgaris เดินทางในหลอดเลือดไปที่ cranial mesenteric artery ทำให้เกิด endarteritis และ thromboembolism จนเกิด non-strangulating intestinal infarction ที่ถึงตายได้ ตรงกับที่แผนที่ระบุว่าพบ S. vulgaris ระยะตัวอ่อนในระบบไหลเวียนเลือด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38827589","locator":"Vol 65(6):587-593, Background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Larval migration through the cranial mesenteric artery (CMA) with attendant arteritis and thromboembolism can result in fatal non-strangulating intestinal infarction."}},{"id":"equine-medicine--equine-parasites--แผนที่ตำแหน่งของปรสิตในม้า--v2","statement":"ระยะตัวอ่อนของ cyathostomin ฝังตัวอยู่ในเยื่อบุของ cecum, ventral colon และ dorsal colon ซึ่งยืนยันตำแหน่งของ Cyathostomum spp. ในลำไส้ใหญ่ตามที่แผนที่ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33482426","locator":"Vol 290:109349, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Larval stages encyst in the mucosa of the cecum, ventral and dorsal colon and can induce an inflammatory response leading to larval cyathostominosis, a life-threatening generalized typhlocolitis."}}]},"equine-medicine--equine-parasites--tapeworm-anoplocephala-perfoliata":{"claims":[{"id":"equine-medicine--equine-parasites--tapeworm-anoplocephala-perfoliata--v1","statement":"Anoplocephala perfoliata ทำให้เกิดรอยโรคที่ ileocaecal junction โดยความรุนแรงสัมพันธ์กับจำนวนพยาธิ ตั้งแต่ enteritis กับ erosion เล็กน้อย ไปจนถึง regional necrotizing enteritis ในตัวที่มีพยาธิมากที่สุด และผู้เขียนอภิปรายบทบาทของรอยโรคเหล่านี้ในการก่อ colic","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10445000","locator":"Vol 46(5):261-9, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the third grade (grade III) was a regional necrotizing enteritis, present in the animals (21%) with the highest burden (72-248 tapeworms). The possible role of the lesions caused by this parasite in the aetiology of colic is discussed."}},{"id":"equine-medicine--equine-parasites--tapeworm-anoplocephala-perfoliata--v2","statement":"การทดสอบแบบ dose titration ยืนยันว่า praziquantel ขนาด 1.0 มก./กก. ให้ประสิทธิภาพเฉลี่ย 99.7% ต่อ A. perfoliata ขณะที่ขนาด 0.5 มก./กก. ได้เพียง 85.5% ตรงกับขนาดยาที่เอกสารระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16309843","locator":"Vol 136(2):127-35, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"mean efficacies for 0.5, 1.0, 1.5 and 2.0 mg praziquantel/kg body weight were 85.5, 99.7, 100 and 100%, respectively."}}]},"equine-medicine--equine-parasites--trichostrongylus-axei":{"claims":[{"id":"equine-medicine--equine-parasites--trichostrongylus-axei--v1","statement":"Trichostrongylus axei ติดสู่คนได้จริง การตรวจอุจจาระคนที่เป็นบวกในภาคเหนือของอิหร่านด้วยวิธี ITS2-PCR พบ T. axei 4 จาก 33 ราย คิดเป็น 12.1% ยืนยันสถานะ zoonosis ตามที่เอกสารระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25904953","locator":"Vol 10(1):110-5, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A total of 33 positive fecal specimens, 29(78.9%), 4(12.1%) were found T. colubriformis and T. axei respectively. Our data appear the molecular evidence of both human T. colubriformis and T. axei infections in North of Iran."}}]},"equine-medicine--equine-parasites--habronema-และ-cutaneous-habronemosis":{"claims":[{"id":"equine-medicine--equine-parasites--habronema-และ-cutaneous-habronemosis--v1","statement":"รอยโรค cutaneous habronemosis เป็น eosinophilic granuloma จริง การตรวจทางจุลพยาธิวิทยาพบ granuloma ที่มี necrotic debris ตรงกลาง ล้อมด้วย eosinophil, macrophage และ lymphocyte จำนวนมาก พร้อมซากตัวอ่อน Habronema","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31303226","locator":"Vol 17:100295, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Histopathological study revealed eosinophilic granuloma and in the center of the granuloma with necrotic debris. Remnants of the Hebronema larvae with infiltrating neutrophils surrounded by proliferating fibrous tissue with numerous eosinop"}},{"id":"equine-medicine--equine-parasites--habronema-และ-cutaneous-habronemosis--v2","statement":"ivermectin ฉีดเข้ากล้าม 0.2 มก./กก. ครั้งเดียว ทำให้แผล summer sore ดีขึ้นชัดเจนใน 26 จาก 31 ตัว คิดเป็น 84% ภายใน 7 วัน และชิ้นเนื้อหลังรักษา 18 จาก 21 ตัวตรวจไม่พบตัวอ่อนแล้ว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-6461283","locator":"Vol 42(11):1953-5, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There was a marked clinical improvement in 26 horses (84%) 7 days after ivermectin was given. The typical summer sore was replaced by healthy pink granulation tissue at 7 days and this healed after 1 to 5 weeks."}},{"id":"equine-medicine--equine-parasites--habronema-และ-cutaneous-habronemosis--v3","statement":"ตำแหน่งที่พบรอยโรคบ่อยที่สุดจากเคส 63 ตัวคือ medial canthus ของตา อวัยวะเพศผู้ หนังตาที่สาม และปลายขา และพบมากในฤดูร้อนกับต้นฤดูใบไม้ร่วง ตรงกับที่เอกสารระบุว่าเจอที่หัวตาและข้อเท้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12685790","locator":"Vol 222(7):978-82, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lesions were identified most often during the summer and early fall. The medial canthus of the eye, male genitalia, third eyelid, and distal portions of the extremities were the most commonly affected locations."}}]},"equine-medicine--equine-parasites--strongyloides-westeri":{"claims":[{"id":"equine-medicine--equine-parasites--strongyloides-westeri--v1","statement":"แหล่งติดเชื้อหลักของลูกม้าคือการถ่ายทอดผ่านน้ำนมแม่ ตรงกับที่เอกสารระบุว่าติดผ่าน transmammary infection และ Strongyloides westeri พบในลำไส้เล็กของม้าอายุน้อย โดยเฉพาะลูกม้าอายุไม่เกินราว 16 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34479608","locator":"Vol 14(1):444, Background","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Strongyloides westeri is found in the small intestine of young horses, mainly in foals up to about 16 weeks of age. The main source of infection for foals is through transmammary transmission"}}]},"equine-medicine--equine-parasites--oxyuris-equi-pinworm":{"claims":[{"id":"equine-medicine--equine-parasites--oxyuris-equi-pinworm--v1","statement":"การวินิจฉัย Oxyuris equi ควรใช้ Scotch tape test หรือขูดผิวหนังบริเวณ perineum แล้วส่องกล้อง ซึ่งมีความไวมากกว่าการตรวจอุจจาระ เพราะไข่ติดอยู่บริเวณรอบทวารหนักไม่ได้ถูกขับออกมากับอุจจาระ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Section 3.6 Pinworms, page 10 and Box 1, page 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pinworm eggs (O. equi) can sometimes be found on a fecal exam, but the Scotch tape test or a microscopic examination of perineal scrapings (using a tongue depressor and lube) are expected to be more sensitive."}},{"id":"equine-medicine--equine-parasites--oxyuris-equi-pinworm--v2","statement":"อาการคันเกิดจากสารที่ตัวเมียหลั่งออกมาขณะวางไข่รอบทวารหนัก และในรายที่รุนแรงจะเห็นการถูหางอย่างรุนแรงกับผิวหนังบริเวณสะโพกและ perineum ถลอก ตรงกับที่เอกสารบรรยาย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Section 2.6 Oxyuris equi (Pinworms), page 6 and Section 9.8, page 25","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the pruritus secondary to pinworm infections is caused by the material secreted by the female when depositing her eggs"}}]},"equine-medicine--equine-parasites--parascaris-equorum":{"claims":[{"id":"equine-medicine--equine-parasites--parascaris-equorum--v1","statement":"ตัวอ่อนที่ migrate ทำให้เกิดอาการอักเสบของทางเดินหายใจ ทั้งไอและมีน้ำมูก ส่วนอาการทางคลินิกที่สำคัญที่สุดคือ small intestinal impaction ซึ่งพยากรณ์โรคระวัง และอาจแทรกซ้อนด้วย volvulus, intussusception หรือลำไส้แตก ตรงกับอาการที่เอกสารระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Section 2.4 Parascaris spp. (Roundworms; Ascarids), page 5","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Migrating larvae can cause signs of airway inflammation, including cough and nasal discharge (Clayton, 1986) ... The most clinically important manifestation of Parascaris spp. infection in horses is a verminous small intestinal impaction"}}]},"equine-medicine--equine-parasites--large-strongyles":{"claims":[{"id":"equine-medicine--equine-parasites--large-strongyles--v1","statement":"ระยะก่อนออกไข่ของ Strongylus vulgaris ยาวประมาณ 6 เดือน ตรงกับตัวเลขที่เอกสารระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24433851","locator":"Vol 200(3-4):265-70, Introduction","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A recently developed serum ELISA allows detection of S. vulgaris-specific antibodies during the six-month-long prepatent period."}},{"id":"equine-medicine--equine-parasites--large-strongyles--v2","statement":"Strongylus vulgaris ถือเป็นหนอนพยาธิทางเดินอาหารที่ก่อโรครุนแรงที่สุดในม้า ทำให้เกิด thromboembolism และ peritonitis ที่ถึงตายได้ สนับสนุนข้อความว่าตัวเล็กแต่อันตรายที่สุด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Section 2.2 Large strongyles, page 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The group of large strongyles includes Strongylus vulgaris, which is considered the most pathogenic equine gastrointestinal helminth. Also known as the bloodworm, this parasite can cause thromboembolism and life-threatening peritonitis"}}]},"equine-medicine--equine-parasites--small-strongyles-cyathostomes":{"claims":[{"id":"equine-medicine--equine-parasites--small-strongyles-cyathostomes--v1","statement":"Cyathostomin เป็นกลุ่มปรสิตภายในที่พบบ่อยที่สุดในม้าทั่วโลก และพบได้แทบทุกตัวในม้าที่เลี้ยงแบบปล่อยแทะเล็ม สนับสนุนข้อความว่าพบบ่อยกว่า large strongyles","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Section 2.1 Cyathostomins (Small Strongyles), page 4","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine strongyles represent the most commonly encountered internal parasite group in horses worldwide. Cyathostomins (small strongyles) are truly ubiquitous in grazing horses, but they are rarely associated with disease."}},{"id":"equine-medicine--equine-parasites--small-strongyles-cyathostomes--v2","statement":"ระยะตัวอ่อนของ cyathostomin ฝังตัวใน mucosa ของ cecum และ colon แล้วกระตุ้นการอักเสบ จนเกิด larval cyathostominosis ซึ่งเป็น typhlocolitis ที่ถึงตายได้ ตรงกับข้อความเรื่อง nodule ใน colonic mucosa","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33482426","locator":"Vol 290:109349, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Larval stages encyst in the mucosa of the cecum, ventral and dorsal colon and can induce an inflammatory response leading to larval cyathostominosis"}},{"id":"equine-medicine--equine-parasites--small-strongyles-cyathostomes--v3","statement":"รูปร่างของไข่แยก large strongyle ออกจาก small strongyle ไม่ได้ และแยกชนิดของ small strongyle ก็ไม่ได้ จึงต้องเพาะเลี้ยงอุจจาระเพื่อดูระยะ L3 ตามที่เอกสารระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Box 1 Use of Fecal Egg Counts, Limitations, page 8","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Egg morphology does not allow identification of large strongyles, nor species differentiation of small strongyles."}}]},"equine-medicine--equine-parasites--epg-การประเมินการดื้อยา-และ-metabarcoding":{"claims":[{"id":"equine-medicine--equine-parasites--epg-การประเมินการดื้อยา-และ-metabarcoding--v1","statement":"การตรวจซ้ำหลังให้ยาถ่ายพยาธิที่ 14 วัน คือช่วงเวลาที่แนวทางกำหนด และเกณฑ์คือยาต้องลดจำนวนไข่ทั้ง ascarid และ strongyle ได้มากกว่า 95% ตรงกับที่เอกสารระบุว่าตรวจซ้ำหลังให้ยา 2 สัปดาห์","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-american-association-o-2024","locator":"Section 4 Anthelmintic Treatment Evaluation, page 10 and Section 4.4, page 16","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"any anthelmintic should reduce both ascarid and strongyle fecal egg counts by more than 95% at 14 days after treatment."}},{"id":"equine-medicine--equine-parasites--epg-การประเมินการดื้อยา-และ-metabarcoding--v2","statement":"Nemabiome metabarcoding ใช้การอ่านลำดับเบสเชิงลึกของบริเวณ ITS-2 เพื่อบรรยายองค์ประกอบชนิดของชุมชนพยาธิทางเดินอาหารในม้า โดยในการศึกษาหนึ่งจำแนกได้ถึง 16 ชนิด ซึ่งละเอียดกว่าการดูรูปร่างอย่างมาก ตรงกับที่เอกสารระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36208676","locator":"Vol 52(12):763-774, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We have used nemabiome deep amplicon sequencing of internal transcribed spacer-2 (ITS-2) ribosomal DNA to describe the temporal and host species composition of gastrointestinal nematode communities ... Sixteen presumptive strongylid species"}}]},"equine-medicine--equine-parasites--setaria-spp":{"claims":[{"id":"equine-medicine--equine-parasites--setaria-spp--v1","statement":"Setaria สามารถ migrate ผิดที่เข้าไปอยู่ใน anterior chamber ของตาม้าได้จริง รายงานชุดหนึ่งมีม้า 12 ตัวที่มาด้วยพยาธิเคลื่อนไหวอยู่ในช่องหน้าลูกตา และเอาออกได้สำเร็จ 11 จาก 12 ตา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42175543","locator":"Vol 29(4):e70197, Animals and Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Twelve client-owned horses (2021-2026) presented with a motile intracameral worm ... Worm removal was successful in 11/12 eyes (91.7%)."}},{"id":"equine-medicine--equine-parasites--setaria-spp--v2","statement":"ชนิดที่พบในช่องหน้าลูกตาของม้าในรายงานชุดนี้คือ Setaria digitata ซึ่งเป็น filarial nematode ของสัตว์เคี้ยวเอื้อง สอดคล้องกับข้อสังเกตในเอกสารว่าชนิดที่เจอในม้าน่าจะข้ามมาจากวัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42175543","locator":"Vol 29(4):e70197, Objective","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"To describe a rapid surgical technique for removal of the intraocular nematode Setaria digitata from the anterior chamber of horses under standing sedation"}},{"id":"equine-medicine--equine-parasites--setaria-spp--v3","statement":"Setaria equina ก็ migrate ผิดที่ได้เช่นกัน มีรายงานก้อนใต้เยื่อบุตาในม้าที่ตรวจพบการอักเสบแบบ eosinophilic และยืนยันชนิดด้วยการวิเคราะห์ยีน cox1 กับ 12S rRNA ว่าเป็น S. equina","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31045314","locator":"Vol 22(6):921-927, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"molecular analysis of the mitochondrial cytochrome c oxydase subunit 1 (cox1) and 12S rRNA gene sequences led to further identification of the specimen as Setaria equina"}}]},"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis":{"claims":[{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v1","statement":"ระยะฟักตัวที่ตัวเลขในเอกสารระบุตรงกับบทปริทัศน์ปัจจุบัน คือ Babesia caballi เริ่มแสดงอาการที่ 10-30 วันหลังติดเชื้อ ส่วน Theileria equi ที่ 12-19 วันหลังติดเชื้อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39205808","locator":"Vol 11:1459989, Clinical signs section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"milder signs that may start manifesting at 10-30 days post-infection [B. caballi]; 12-19 days post-infection [T. equi]"}},{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v2","statement":"WOAH ระบุว่าเห็บ Ixodid ราว 14 ชนิดในสกุล Dermacentor, Rhipicephalus และ Hyalomma เป็น transstadial vector ของทั้ง B. caballi และ T. equi โดยมี 8 ชนิดที่ถ่ายทอด B. caballi แบบ transovarial ได้ด้วย ยืนยันว่า T. equi ถ่ายทอดแบบ transstadial เท่านั้น ต่างจาก B. caballi","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Section A. Introduction, page 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Approximately fourteen species of Ixodid ticks in the genera Dermacentor, Rhipicephalus and Hyalomma have been identified as transstadial vectors of B. caballi and T. equi, while eight of these species were also able to transmit B. caballi "}},{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v3","statement":"เชื้อ piroplasm ของม้าแพร่ผ่านเครื่องมือที่ปนเปื้อนเลือดได้ง่าย ซึ่งครอบคลุมเข็มฉีดยาและการถ่ายเลือดตามที่เอกสารระบุว่าเป็น mechanical transmission","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2021","locator":"Summary, page 1","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These parasites are also easily spread by blood contaminated instruments."}},{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v4","statement":"Imidocarb dipropionate เป็นยามาตรฐานที่ใช้รักษา equine piroplasmosis ในปัจจุบัน แต่บทปริทัศน์เตือนว่ามีผลข้างเคียงและมีรายงานการรักษาล้มเหลวซ้ำ ๆ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39205808","locator":"Vol 11:1459989, Treatment section","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"ID is the current gold-standard treatment for EP ... while ID has several side and toxic effects and recurrent failures of treatment have been reported"}},{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v5","statement":"Trypanosoma evansi มีแมลงวันดูดเลือดหลายชนิด รวมถึง Tabanid และ Stomoxys เป็นพาหะเชิงกล ตรงกับที่เอกสารระบุว่า vector คือ Tabanus","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Summary, Definition of the disease, page 660","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It is an arthropod-borne disease; several species of haematophagous flies, including Tabanids and Stomoxes, are implicated in transferring infection from host to host, acting as mechanical vectors."}},{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v6","statement":"Woo technique หรือ haematocrit centrifugation technique ตรวจพบเชื้อได้ที่ระดับราว 50-200 trypanosomes ต่อมิลลิลิตร โดยดูตัวเชื้อที่เคลื่อนไหวอยู่ตรงรอยต่อระหว่าง buffy coat กับพลาสมา ขณะที่ stained thin smear มีความไวต่ำมากคือต้องมีเชื้อมากกว่า 500,000 ตัวต่อมิลลิลิตร แต่ใช้ศึกษารูปร่างและระบุชนิดของ Trypanosoma ได้ ตรงกับที่เอกสารระบุว่า Woo เห็นเชื้อขยับแต่บอกชนิดไม่ได้ ส่วน smear จำเพาะกว่า","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Sections 1.1.4 Stained thin smears (page 662) and 1.2.1 Haematocrit centrifugation technique (page 663)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This technique permits detailed morphological studies and identification of the Trypanosoma species, but it is of a very low sensitivity (it can detect parasitaemia >500,000 trypanosomes/ml of blood) ... This technique can detect around 50-"}},{"id":"equine-medicine--equine-parasites--blood-parasites-piroplasmosis-และ-trypanosomosis--v7","statement":"อาการของ surra คือไข้เป็นพัก ๆ ร่วมกับโลหิตจางที่ค่อย ๆ รุนแรงขึ้น และในระยะท้ายเชื้อเข้าสู่ระบบประสาทส่วนกลางทำให้เกิดอาการทางประสาทโดยเฉพาะในม้า แต่อาการที่ WOAH ระบุคืออัมพาตของขาหลังที่ค่อยเป็นค่อยไปและ paraplegia ไม่ใช่ ataxia, blindness หรือ circling ตามที่เอกสารระบุ","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2018","locator":"Section A. Introduction, page 661","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Such recurrent episodes lead to intermittent fever ... In advanced cases, parasites invade the central nervous system (CNS), which can lead to nervous signs (progressive paralysis of the hind quarters and, exceptionally, paraplegia), especi"}}]},"equine-medicine--equine-parasites--ectoparasites-เหา-louse":{"claims":[{"id":"equine-medicine--equine-parasites--ectoparasites-เหา-louse--v1","statement":"ม้ามีเหาสองกลุ่มตามที่เอกสารแบ่ง คือ biting louse ชื่อ Werneckiella equi ซึ่งเป็นชื่อปัจจุบันของ Damalinia equi และ sucking louse ชื่อ Haematopinus asini การสำรวจม้า 140 ตัวพบการระบาดของทั้งสองชนิด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7491867","locator":"Vol 43(2-3):287-9, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"One hundred fourteen (of the 136) halfbred and 26 thoroughbred horses were examined for ectoparasites, and all were found to be infested with biting lice (Werneckiella equi equi) and sucking lice (Haematopinus asini)."}}]},"equine-medicine--equine-parasites--ectoparasites-ไร-mite":{"claims":[{"id":"equine-medicine--equine-parasites--ectoparasites-ไร-mite--v1","statement":"Psoroptes equi เป็นสาเหตุของ psoroptic mange ในม้าจริง และการทดลองแบบสุ่มมีกลุ่มควบคุมยืนยันว่ายาในกลุ่ม macrocyclic lactone คือ eprinomectin แบบราดหลัง ได้ผลและปลอดภัยในการรักษา สนับสนุนแนวทางการรักษาที่เอกสารระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18667276","locator":"Vol 156(3-4):353-7, Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In conclusion, eprinomectin was effective and safe therapy against natural infestations of P. equi in the horses included in this study."}}]},"equine-medicine--equine-parasites--ภาพรวม-ปรสิตเรียงตามอวัยวะ":{"claims":[{"id":"equine-medicine--equine-parasites--ภาพรวม-ปรสิตเรียงตามอวัยวะ--v1","statement":"ปรสิตหลายชนิดติดเชื้อในระบบทางเดินอาหารของม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-gastrointestinal-parasites-of-horses-2026","locator":"Introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Numerous parasites can infect the digestive system of horses"}}]},"equine-medicine--equine-parasites--พยาธิตัวตืด-anoplocephalidae":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิตัวตืด-anoplocephalidae--v1","statement":"Oribatid mite ที่ม้ากินโดยบังเอิญขณะเล็มหญ้าเป็น intermediate host ของ Anoplocephala perfoliata","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-diseases-resulting-from-gastrointestinal-parasites-in-ho","locator":"Anoplocephala perfoliata","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Free-living and commonly occurring oribatid mites, accidentally ingested by horses while grazing, act as intermediate hosts for A perfoliata"}}]},"equine-medicine--equine-parasites--พยาธิในกระเพาะ-trichostrongylus-axei-habronema-และ-draschia":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิในกระเพาะ-trichostrongylus-axei-habronema-และ-draschia--v1","statement":"ม้าติด stomach worms (Habronema และ Draschia) จากการกินแมลงวันบ้านหรือแมลงวันคอก (หรือตัวอ่อน) ที่มีตัวอ่อนพยาธิ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-gastrointestinal-parasites-of-horses-2026","locator":"Table: Common Gastrointestinal Parasites of Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses ingest house or stable flies (or their larvae) that contain larvae of the stomach worms."}}]},"equine-medicine--equine-parasites--พยาธิเส้นด้าย-strongyloides-westeri":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิเส้นด้าย-strongyloides-westeri--v1","statement":"Strongyloides westeri ติดจากแม่ม้าสู่ลูกม้าทางน้ำนม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-gastrointestinal-parasites-of-horses-2026","locator":"Table: Common Gastrointestinal Parasites of Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Strongyloides westeri Transmitted from mares to foals in milk."}}]},"equine-medicine--equine-parasites--พยาธิไส้เดือนม้า-parascaris-equorum":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิไส้เดือนม้า-parascaris-equorum--v1","statement":"ไข่ Parascaris ที่ม้ากินเข้าไปฟักเป็นตัวอ่อน L3 ซึ่งเริ่มเดินทางผ่านตับสู่ปอด (hepatotracheal migration)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-diseases-resulting-from-gastrointestinal-parasites-in-ho","locator":"Ascarid-Associated Colic in Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Once ingested by a horse, ascarid eggs hatch, and L3 larvae begin hepatotracheal migration, arriving in the lungs approximately 1 week after infection."}}]},"equine-medicine--equine-parasites--พยาธิหัวเข็มหมุด-oxyuris-equi":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิหัวเข็มหมุด-oxyuris-equi--v1","statement":"ไข่ของ Oxyuris equi ที่รอบทวารหนักเห็นเป็นก้อนสีขาวถึงเหลืองคล้ายสะเก็ด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-gastrointestinal-parasites-of-horses-2026","locator":"Table: Common Gastrointestinal Parasites of Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Egg masses around anus appear as white to yellow crusty mass."}}]},"equine-medicine--equine-parasites--พยาธิสตรองกายม้า-large-และ-small-strongyles":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิสตรองกายม้า-large-และ-small-strongyles--v1","statement":"S. vulgaris เป็นหนึ่งในพยาธิที่ก่อโรครุนแรงที่สุดในม้า ตัวอ่อนเคลื่อนผ่าน cranial mesenteric artery ทำให้เกิด arteritis และ thromboembolism","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38827589","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Strongylus vulgaris is one of the most pathogenic nematodes affecting equids. Larval migration through the cranial mesenteric artery (CMA) with attendant arteritis and thromboembolism can result in fatal non-strangulating intestinal infarction."}}]},"equine-medicine--equine-parasites--strongylidosis-การวินิจฉัยและงานวิจัยในไทย":{"claims":[{"id":"equine-medicine--equine-parasites--strongylidosis-การวินิจฉัยและงานวิจัยในไทย--v1","statement":"ในไทย ivermectin กำจัด strongyle ตัวเต็มวัยได้ภายใน 2 สัปดาห์ แต่ egg reappearance period สั้นลงเหลือ 6 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38396542","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"although ivermectin effectively eliminated adult strongyle parasites within two weeks post-treatment, the ERP was shortened to 6 weeks post-treatment with a mean FECR of 70.4% (95% CI 46.1-84.0)"}}]},"equine-medicine--equine-parasites--strongylidosis-รักษา-ควบคุม-และการดื้อยา":{"claims":[{"id":"equine-medicine--equine-parasites--strongylidosis-รักษา-ควบคุม-และการดื้อยา--v1","statement":"Egg reappearance period ที่สั้นลงใช้เป็นตัวชี้วัดว่าพยาธิไวต่อยาลดลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-42731192","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A shortened egg reappearance period (ERP) is frequently used as an indicator of reduced susceptibility."}}]},"equine-medicine--equine-parasites--พยาธิในเลือด-equine-piroplasmosis-และ-trypanosomiasis":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิในเลือด-equine-piroplasmosis-และ-trypanosomiasis--v1","statement":"Equine piroplasmosis เป็นโรคที่เห็บนำจากเชื้อ Theileria equi และ Babesia caballi ซึ่งอยู่ในเม็ดเลือดแดง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39205808","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine piroplasmosis (EP) is a global tick-borne disease of equids caused by the intraerythrocytic apicomplexan parasites Theileria equi and Babesia caballi"}}]},"equine-medicine--equine-parasites--โรคผิวหนังจากปรสิต-เหา-ไร-summer-sores-และหนอนแมลงวัน":{"claims":[{"id":"equine-medicine--equine-parasites--โรคผิวหนังจากปรสิต-เหา-ไร-summer-sores-และหนอนแมลงวัน--v1","statement":"Habronemiasis ติดต่อผ่านแมลงวัน ตัวอ่อนที่ตกบนแผลทำให้เกิด summer sores ที่หายยาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40816495","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The parasite is transmitted via flies, and larvae deposited in wounds result in difficult-to-heal \"summer sores\"."}}]},"equine-medicine--equine-parasites--พยาธิในตา-setaria":{"claims":[{"id":"equine-medicine--equine-parasites--พยาธิในตา-setaria--v1","statement":"ตัวเต็มวัย Setaria อยู่ในช่องท้อง แต่ตัวอ่อนอาจเคลื่อนผิดที่เข้าตาม้า ทำให้กระจกตาขุ่นและตาบอด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39180621","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Adult worms belong to the Setariidae family and typically reside in the peritoneal cavity of ungulates. However, immature forms of these species may aberrantly migrate to the eyes of cattle, buffalo, goats, horses and several other hosts, leading to corneal opacity and blindness."}}]}},"equine-medicine--equine-nutrition":{"equine-medicine--equine-nutrition--ทางเดินอาหารม้ากับหลักการให้อาหาร":{"claims":[{"id":"equine-medicine--equine-nutrition--ทางเดินอาหารม้ากับหลักการให้อาหาร--v1","statement":"ระบบ hindgut ของม้าเป็นระบบที่พัฒนามาเพื่อหมักไฟเบอร์จากอาหารโดยเฉพาะ เพื่อสร้างพลังงานให้ม้าและส่งเสริมสุขภาพ สนับสนุนแนวคิด hindgut fermenter ที่สไลด์อธิบาย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33841371","locator":"Introduction; 12:646294","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The equine hindgut ecosystem is specialized in dietary fibers' fermentation to provide horses' energy and contribute to its health."}},{"id":"equine-medicine--equine-nutrition--ทางเดินอาหารม้ากับหลักการให้อาหาร--v2","statement":"วิธีแปรรูปธัญพืชมีผลต่อการย่อยแป้งก่อนถึง cecum จริง โดยข้าวโพดและวิธี micronizing ให้ starch disappearance สูงที่สุด และ toasting ให้ผลด้อยกว่า micronizing สนับสนุนแนวโน้มที่สไลด์สรุปว่ายิ่งแปรรูปละเอียดยิ่งย่อยได้มากขึ้น แต่การศึกษาเดียวกันพบว่าปริมาณแป้งที่หลุดรอดการย่อยในลำไส้เล็กยังสูงกว่าที่คาดไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33150365","locator":"Results and conclusion; 98(12):skaa353","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Maize and micronizing had the highest starch disappearance (P = 0.048) compared with barley and toasting ... toasting was not as efficient as micronizing to improve pre-cecal starch digestibility ... the amount of starch escaping enzymatica"}},{"id":"equine-medicine--equine-nutrition--ทางเดินอาหารม้ากับหลักการให้อาหาร--v3","statement":"ม้าที่กินอาหารหญ้าล้วนมีระดับ acetate ในพลาสมาสูงกว่าม้าที่กินหญ้าร่วมอาหารข้นทั้งก่อนและหลังออกกำลังกาย แสดงว่ากรดไขมันสายสั้นจากการหมักไฟเบอร์ใน hindgut เป็นแหล่งพลังงานที่ใช้ได้จริงในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22717208","locator":"Results; 6(12):1939-46","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Plasma acetate concentration was higher before and after exercise in horses on diet F compared with diet FC, and there was a tendency (P = 0.09) for increased VLa4 on diet F."}}]},"equine-medicine--equine-nutrition--hindgut-acidosis":{"claims":[{"id":"equine-medicine--equine-nutrition--hindgut-acidosis--v1","statement":"การเปลี่ยนอาหารจากหญ้าล้วนเป็นหญ้าผสมข้าวบาร์เลย์ (แป้งสูง) ทำให้ระบบนิเวศจุลชีพใน cecum และ colon เปลี่ยนจริง คือแบคทีเรียกลุ่ม amylolytic และ lactate-utilizing เพิ่มขึ้น แบคทีเรียกลุ่ม cellulolytic ลดลง และความเข้มข้นของ lactate เพิ่มขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28065211","locator":"Results; 11(7):1136-1145","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The variations observed in the caecal and colonic bacterial composition (increase in total anaerobic, amylolytic and lactate-utilizing and decrease in cellulolytic bacteria concentrations) and microbial activity (changes in volatile fatty a"}},{"id":"equine-medicine--equine-nutrition--hindgut-acidosis--v2","statement":"อาหารแป้งสูงทำให้ความเข้มข้นของ lipopolysaccharide ซึ่งเป็น endotoxin ของแบคทีเรียแกรมลบในอุจจาระสูงขึ้น สนับสนุนกลไกที่สไลด์อธิบายว่าแบคทีเรียแกรมลบตายแล้วปล่อย endotoxin ออกมา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28065211","locator":"Results; 11(7):1136-1145","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Feeding the hay+barley diet resulted in higher concentrations of faecal lipopolysaccharides."}}]},"equine-medicine--equine-nutrition--น้ำและพฤติกรรมการกิน":{"claims":[{"id":"equine-medicine--equine-nutrition--น้ำและพฤติกรรมการกิน--v1","statement":"ปริมาณน้ำที่ม้ากิน รวมทั้งจำนวนครั้งและระยะเวลาการกินน้ำ เป็นตัวชี้วัดภาวะขาดน้ำที่เชื่อถือได้ที่สุดในม้าโตเต็มวัย ขณะที่ skin tent test และความแห้งของเยื่อเมือกไม่ใช่ตัวชี้วัดที่ valid สนับสนุนคำแนะนำให้ม้าที่มีปัญหากินน้ำจากถังเพื่อวัดปริมาณได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18356129","locator":"Conclusions; 40(6):558-64","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The volume of water consumed and the number and duration of drinking bouts were the most reliable guide to hydration status currently available for mature working horses."}}]},"equine-medicine--equine-nutrition--ความต้องการพลังงาน-energy-requirement":{"claims":[{"id":"equine-medicine--equine-nutrition--ความต้องการพลังงาน-energy-requirement--v1","statement":"ความต้องการ digestible energy ของม้าโตที่ไม่ทำงานและมี body condition ดี อยู่ที่ประมาณ 0.03 Mcal ต่อน้ำหนักตัว 1 กิโลกรัม โดยใช้ 0.033 คูณน้ำหนักตัวเป็นค่าตั้งต้นได้ ตรงกับสูตร DE = BW x 0.0333 ที่สไลด์ใช้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2026","locator":"Management and Nutrition: Nutrition in Horses, Energy section","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the digestible energy (DE) requirement of nonworking adult horses in good body condition is estimated to be on average 0.03 Mcal/kg body weight"}},{"id":"equine-medicine--equine-nutrition--ความต้องการพลังงาน-energy-requirement--v2","statement":"แม่ม้าระยะให้นมต้องการโปรตีนในสัดส่วนสูงกว่าระยะตั้งท้องช่วงท้าย คือประมาณ 12 ถึง 14% ของอาหารรวม เทียบกับ 10 ถึง 11% ในช่วงหนึ่งในสามสุดท้ายของการตั้งท้อง สนับสนุนคำตอบว่าม้าวัยให้นมต้องการโปรตีนสูงที่สุด","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2026","locator":"Management and Nutrition: Nutrition in Horses, Protein section","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"during the final third of pregnancy, mares require roughly 10-11% protein in their total ration ... lactating mares need a higher amount: approximately 12-14% protein of their total ration"}}]},"equine-medicine--equine-nutrition--คาร์โบไฮเดรตและขีดจำกัดของ-starch":{"claims":[{"id":"equine-medicine--equine-nutrition--คาร์โบไฮเดรตและขีดจำกัดของ-starch--v1","statement":"การได้รับแป้งเกิน 2 กรัมต่อกิโลกรัมน้ำหนักตัวต่อวัน หรือเกิน 1 กรัมต่อกิโลกรัมน้ำหนักตัวต่อมื้อ สัมพันธ์อย่างมีนัยสำคัญกับ EGUS ระดับตั้งแต่ 2 ขึ้นไป และการเกิน 1 กรัมต่อกิโลกรัมต่อมื้อสัมพันธ์กับแผลที่ nonglandular โดยเฉพาะ ตรงกับขีดจำกัดที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19927579","locator":"Results; 41(7):625-30","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Three variables were significantly (P<0.05) associated with EGUS >= 2: straw being the only forage available; exceeding 2 g/kg bwt of starch intake/day or >1 g/kg bwt/meal; and water not being available in the turn out paddock."}}]},"equine-medicine--equine-nutrition--ไขมันและโปรตีน":{"claims":[{"id":"equine-medicine--equine-nutrition--ไขมันและโปรตีน--v1","statement":"การเสริมน้ำมันข้าวโพดในอาหารทำให้ acid output ของกระเพาะลดลงและ PGE2 กับ sodium output เพิ่มขึ้นอย่างมีนัยสำคัญ จึงอาจเพิ่มคุณสมบัติป้องกันของ glandular mucosa ซึ่งเป็นประโยชน์คนละประเด็นกับ colic ที่สไลด์กล่าวถึง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15320596","locator":"Results and conclusion; 18(4):545-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"During the diet supplemented with corn oil, the ponies had, under basal and pentagastrin-stimulated conditions, significantly decreased acid output and significantly increased PGE2 and sodium outputs compared to those measured before corn o"}}]},"equine-medicine--equine-nutrition--topline-evaluation-scoring-tes-และ-bcs":{"claims":[{"id":"equine-medicine--equine-nutrition--topline-evaluation-scoring-tes-และ-bcs--v1","statement":"ระบบ condition score ของม้าถูกพัฒนาและตรวจสอบความสัมพันธ์กับเปอร์เซ็นต์ไขมันในร่างกายและการวัดขนาดร่างกายของแม่ม้าโดยตรง ยืนยันว่า BCS เป็นเครื่องมือประเมินไขมันสะสม ไม่ใช่มวลกล้ามเนื้อ จึงต้องใช้คู่กับการประเมิน topline","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-6641685","locator":"Title and study design; 15(4):371-2 (no abstract available in PubMed record)","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Relationship between condition score, physical measurements and body fat percentage in mares."}}]},"equine-medicine--equine-nutrition--แร่ธาตุและอิเล็กโทรไลต์":{"claims":[{"id":"equine-medicine--equine-nutrition--แร่ธาตุและอิเล็กโทรไลต์--v1","statement":"ตัวเลขที่วัดได้จริงในม้าที่ออกกำลังกายให้อัตราส่วนประมาณ 10 กรัมของอิเล็กโทรไลต์ต่อเหงื่อ 1 ลิตร คือสูญเสียเหงื่อ 11.7 ลิตรพร้อมไอออน 112.2 กรัมในสภาพเย็นแห้ง และ 19.2 ลิตรพร้อมไอออน 200.6 กรัมในสภาพร้อนแห้ง ตรงกับตัวเลขที่สไลด์ใช้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8894551","locator":"Results; (22):54-62","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"sweat fluid losses associated with the SEET in HD were almost double (19.2 litres) the losses in CD (11.7 litres) ... total ion losses in CD were 3636 mmol (112.2 g) compared with 6519 mmol (200.6 g) in HD"}},{"id":"equine-medicine--equine-nutrition--แร่ธาตุและอิเล็กโทรไลต์--v2","statement":"ปริมาณโซเดียม โพแทสเซียม และคลอไรด์ที่สูญเสียไปกับเหงื่อระหว่างการทดสอบในสภาพร้อน มากกว่าปริมาณที่ได้รับจากอาหารประจำวัน จึงจำเป็นต้องเสริมอิเล็กโทรไลต์ในช่วงฝึกและแข่งในอากาศร้อน สนับสนุนที่สไลด์ระบุว่าม้าต้องการ Na และ Cl มากกว่าที่ได้จากอาหารปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8894551","locator":"Conclusion; (22):54-62","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the quantity of sodium, potassium and chloride calculated to have been lost in sweat during the SEET in HD exceeded the daily dietary intake of these ions and suggests the need for appropriate ion supplementation during training and competi"}},{"id":"equine-medicine--equine-nutrition--แร่ธาตุและอิเล็กโทรไลต์--v3","statement":"อัตราส่วน calcium ต่อ phosphorus ในอาหารม้าควรมากกว่า 1 ต่อ 1 โดยค่าที่เหมาะสมคือประมาณ 1.5 ต่อ 1 และการมีฟอสฟอรัสมากเกินไปหรือกลับอัตราส่วนจะยับยั้งการดูดซึมแคลเซียม สอดคล้องกับช่วง 1 ถึง 2 ต่อ 1 ที่สไลด์ระบุ และอธิบายว่าทำไมรำข้าวที่มีฟอสฟอรัสสูงจึงอันตราย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2026","locator":"Management and Nutrition: Nutrition in Horses, Minerals section","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the calcium:phosphorus ratio should be maintained at > 1:1. A desirable ratio is approximately 1.5:1"}},{"id":"equine-medicine--equine-nutrition--แร่ธาตุและอิเล็กโทรไลต์--v4","statement":"ลูกม้าที่กินนมทดแทน แม้จะเป็นสูตรที่ทำมาสำหรับลูกม้าโดยเฉพาะ ยังเจริญเติบโตช้ากว่าลูกม้าที่ดูดนมแม่ 12 ถึง 28% ในช่วงสองสัปดาห์แรก สนับสนุนที่สไลด์ระบุว่าการใช้นมชนิดอื่นแทนนมม้าไม่เทียบเท่ากับนมแม่ในช่วงแรกของชีวิต","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17424268","locator":"Results; 34(8):479-86","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Foals fed replacer diets gained 12% to 28% less weight than mare-nursed foals up to two weeks of age."}}]},"equine-medicine--equine-nutrition--วิตามิน":{"claims":[{"id":"equine-medicine--equine-nutrition--วิตามิน--v1","statement":"ม้าจัดเป็นสัตว์ชนิดที่สังเคราะห์ ascorbate หรือวิตามินซีได้เอง (ascorbate-synthesising species) ตรงกับที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12747741","locator":"Title and abstract; 37(4):461-7","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"To examine possible therapeutic regimens in a species with ascorbate-synthesising capacity, we studied the effects of oral supplementation of two forms of ascorbic acid ... on the pulmonary and systemic antioxidant status of six healthy pon"}},{"id":"equine-medicine--equine-nutrition--วิตามิน--v2","statement":"การเสริม biotin 0.12 มิลลิกรัมต่อกิโลกรัมน้ำหนักตัวเป็นเวลา 5 เดือน เพิ่มทั้งความยาวและอัตราการเจริญของผนังกีบราว 15% เทียบกับกลุ่มควบคุม แสดงว่าผลต่ออัตราการงอกวัดได้เร็วกว่าผลต่อคุณภาพกีบโดยรวม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9932094","locator":"Results; (26):51-7","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Treatment animals had a 15% higher growth rate of hoof horn and 15% more hoof growth at the midline dead centre, after 5 months of biotin supplementation compared to control ponies."}}]},"equine-medicine--equine-nutrition--forage-การจัดการแปลงหญ้า-และ-concentrate":{"claims":[{"id":"equine-medicine--equine-nutrition--forage-การจัดการแปลงหญ้า-และ-concentrate--v1","statement":"ม้าควรได้ forage อย่างน้อย 1.5 ถึง 2 เปอร์เซ็นต์ของน้ำหนักตัวต่อวันในรูป dry matter ตรงกับที่สไลด์ระบุว่าระดับที่ดีกว่าคือ 1.5-2 เปอร์เซ็นต์ และ forage สามารถเป็นแหล่งอาหารหลักหรือแหล่งเดียวได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2026","locator":"หัวข้อ Feeding Management and Forage Intake","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"horses receive at least 1.5-2% of their body weight (BW) in forage per day on a DM basis"}},{"id":"equine-medicine--equine-nutrition--forage-การจัดการแปลงหญ้า-และ-concentrate--v2","statement":"Nonstructural carbohydrate ในหญ้าแปลง ได้แก่ น้ำตาลเชิงเดี่ยว แป้ง และ fructan สะสมได้สูงเกิน 400 กรัมต่อกิโลกรัม dry matter และเหนี่ยวนำให้เกิด laminitis ได้ในการทดลอง จึงเป็นเหตุผลที่ต้องจำกัดเวลาปล่อยแทะเล็ม แต่ผลลัพธ์ที่มีหลักฐานรองรับคือ laminitis ไม่ใช่ท้องเสียอย่างที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16772510","locator":"136(7 Suppl):2099S-2102S, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nonstructural carbohydrates (NSC) (simple sugars, starch, and fructan) can induce laminitis experimentally, and NSC can accumulate to >400 g/kg of dry matter (DM) in pasture grasses."}},{"id":"equine-medicine--equine-nutrition--forage-การจัดการแปลงหญ้า-และ-concentrate--v3","statement":"ปริมาณ vitamin A ในอาหารหยาบลดลงระหว่างการเก็บรักษาจากการ oxidation ของ beta carotene และหญ้าแห้งที่เก็บนานเกิน 1 ปี อาจให้ vitamin A activity ไม่พอ ตรงกับที่สไลด์ระบุว่าการเก็บหญ้าทำให้สูญเสีย vitamin A","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2026","locator":"หัวข้อ Vitamins, vitamin A","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"because of oxidation of beta carotene during storage, its content in forages decreases with storage. Hays stored > 1 year may not furnish sufficient vitamin A activity."}}]},"equine-medicine--equine-nutrition--การประเมินคุณภาพอาหารหยาบ-ddm-dmi-และ-rfv":{"claims":[{"id":"equine-medicine--equine-nutrition--การประเมินคุณภาพอาหารหยาบ-ddm-dmi-และ-rfv--v1","statement":"สูตรทั้งสามของ Relative Feed Value ตรงกับที่สไลด์เขียน คือ digestible dry matter เท่ากับ 88.9 ลบด้วย 0.779 คูณเปอร์เซ็นต์ ADF, dry matter intake เท่ากับ 120 หารด้วยเปอร์เซ็นต์ NDF และ RFV เท่ากับ DDM คูณ DMI หารด้วย 1.29 โดย ADF เข้าสูตร DDM ส่วน NDF เข้าสูตร DMI","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-virginia-cooperative-e-2006","locator":"Dairy Pipeline, May 2006","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"digestible dry matter = (88.9 - (.779 * % ADF)) ... dry matter intake = (120/% NDF) ... multiplying digestible dry matter by dry matter intake and then dividing by 1.29"}},{"id":"equine-medicine--equine-nutrition--การประเมินคุณภาพอาหารหยาบ-ddm-dmi-และ-rfv--v2","statement":"ค่าคงที่ 1.29 ปรับสเกลให้ alfalfa ระยะ full bloom มีค่า RFV ประมาณ 100 ตรงกับที่สไลด์อธิบายว่า RFV 100 คือคุณภาพหญ้าแห้ง alfalfa มาตรฐาน","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-virginia-cooperative-e-2006","locator":"Dairy Pipeline, May 2006","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The RFV for full-bloom alfalfa would be expected to be 100."}}]},"equine-medicine--equine-nutrition--balancing-the-diet":{"claims":[{"id":"equine-medicine--equine-nutrition--balancing-the-diet--v1","statement":"การตั้งต้นสูตรอาหารจาก forage ก่อนมีเหตุผลรองรับ เพราะม้าสามารถใช้หญ้าแปลง หญ้าแห้ง และพืชตระกูลถั่ว เป็นแหล่งอาหารหลักหรือแหล่งเดียวได้","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-merck-co-merck-veterin-2026","locator":"หัวข้อ Feeds and Feeding Management","kind":"textbook"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine animals...can use forages such as pasture/range grasses and legumes, preserved hays...as major or sole sources of nutrition"}}]},"equine-medicine--equine-nutrition--ธรรมชาติของม้าและทางเดินอาหาร":{"claims":[{"id":"equine-medicine--equine-nutrition--ธรรมชาติของม้าและทางเดินอาหาร--v1","statement":"ม้าหมักอาหารหยาบในลำไส้ส่วนหลัง (cecum และ large colon) ส่วนสารอาหารที่หนีการย่อยในลำไส้เล็กจะถูกจุลินทรีย์ใน large intestine ย่อยต่อ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Nutritional Requirements, introduction (digestive physiology)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Any nutrient sources that escape small intestinal digestion and absorption are passed on for microbial degradation in the large intestine."}}]},"equine-medicine--equine-nutrition--อาหารต้องให้อะไร-และความต้องการเคี้ยว":{"claims":[{"id":"equine-medicine--equine-nutrition--อาหารต้องให้อะไร-และความต้องการเคี้ยว--v1","statement":"ม้าใช้อาหารหยาบ เช่น หญ้า ถั่ว และหญ้าแห้ง เป็นแหล่งอาหารหลักหรือแหล่งเดียวได้ เพราะมีการหมักใน cecum และ large colon","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Nutritional Requirements, introduction","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"can use forages such as pasture/range grasses and legumes, preserved hays, and other forage-based feeds as major or sole sources of nutrition because of fermentation in the cecum and large colon."}}]},"equine-medicine--equine-nutrition--น้ำ":{"claims":[{"id":"equine-medicine--equine-nutrition--น้ำ--v1","statement":"ม้าโตที่อยู่ในสภาพ thermoneutral ต้องการน้ำขั้นต่ำเพื่อคงสภาพ 5 ลิตรต่อ 100 kg ต่อวัน และม้า 500 kg ที่ทำงานน้อยกินน้ำ 21-29 ลิตรต่อวัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Water Requirements of Horses and Other Equids","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The average minimal maintenance daily water requirement of a sedentary adult horse in a thermoneutral environment is 5 L/100 kg body weight/day . A 500-kg adult horse in minimal work will typically drink 21–29 L of water per day"}}]},"equine-medicine--equine-nutrition--โปรตีนและกรดอะมิโน":{"claims":[{"id":"equine-medicine--equine-nutrition--โปรตีนและกรดอะมิโน--v1","statement":"โปรตีนคุณภาพสูงสำหรับม้าต้องมีกรดอะมิโนจำเป็น โดยเฉพาะ lysine, methionine และ threonine","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Protein and Amino Acids Requirements of Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A high-quality protein includes essential amino acids —in particular, lysine, methionine, and threonine ."}}]},"equine-medicine--equine-nutrition--พลังงาน":{"claims":[{"id":"equine-medicine--equine-nutrition--พลังงาน--v1","statement":"ความต้องการพลังงานของม้า (Mcal digestible energy) ต่างกันตามระยะ maintenance, growth, pregnancy, lactation และงาน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Energy Requirements of Horses and Other Equids","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Energy requirements (expressed as Mcal digestible energy for horses) are different for maintenance, growth, pregnancy, lactation, and work."}}]},"equine-medicine--equine-nutrition--แหล่งพลังงาน-ชนิดกล้ามเนื้อ-และการเลือกอาหารตามงาน":{"claims":[{"id":"equine-medicine--equine-nutrition--แหล่งพลังงาน-ชนิดกล้ามเนื้อ-และการเลือกอาหารตามงาน--v1","statement":"พลังงานของม้าส่วนใหญ่มาจากคาร์โบไฮเดรตและไขมัน โปรตีนปกติไม่ได้ใช้เป็นแหล่งพลังงานและให้พลังงานน้อยมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Protein and Amino Acids Requirements of Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Energy predominantly comes from carbohydrates and fat, whereas dietary protein is normally not used as an energy source and contributes very little to overall energy production."}}]},"equine-medicine--equine-nutrition--แร่ธาตุ-dod-ในลูกม้า-และน้ำนมแม่ม้า":{"claims":[{"id":"equine-medicine--equine-nutrition--แร่ธาตุ-dod-ในลูกม้า-และน้ำนมแม่ม้า--v1","statement":"ทองแดงเป็นแร่ธาตุสำคัญต่อเอนไซม์ที่เกี่ยวกับเนื้อเยื่อเกี่ยวพัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Copper Requirements of Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Copper is an important mineral for enzymes that affect connective tissue, mobilization of iron stores, mitochondrial integrity, melanin, and detoxification of superoxide"}}]},"equine-medicine--equine-nutrition--อิเล็กโทรไลต์และ-heat-stress-index":{"claims":[{"id":"equine-medicine--equine-nutrition--อิเล็กโทรไลต์และ-heat-stress-index--v1","statement":"เหงื่อม้าเป็น hypertonic ม้าจึงเสียอิเล็กโทรไลต์ โดยเฉพาะโซเดียม คลอไรด์ และโพแทสเซียมมากเมื่อเหงื่อออก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Sodium/salt requirements (sweat losses)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses are able to sweat at higher rates than any other mammal, and equine sweat is hypertonic. As such, horses can lose high quantities of electrolytes, particularly sodium, chloride, and potassium, when they sweat"}}]},"equine-medicine--equine-nutrition--วิตามิน-bcs-และ-tes":{"claims":[{"id":"equine-medicine--equine-nutrition--วิตามิน-bcs-และ-tes--v1","statement":"การป้อนอาหารควรปรับให้ BCS อยู่ระหว่าง 4 ถึง 6 ตามมาตรา Henneke 9 คะแนน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Table notes, Body Condition Scores for Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Amounts fed should be adjusted to maintain a body condition score (BCS) between 4 and 6 on the Henneke Body Condition 9-point scale"}}]},"equine-medicine--equine-nutrition--อาหารหยาบ-ปริมาณ-แปลงหญ้า-และหญ้าแห้ง":{"claims":[{"id":"equine-medicine--equine-nutrition--อาหารหยาบ-ปริมาณ-แปลงหญ้า-และหญ้าแห้ง--v1","statement":"คำแนะนำปัจจุบันให้ม้าได้อาหารหยาบอย่างน้อย 1.5-2% ของน้ำหนักตัวต่อวันตามฐาน dry matter","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Feeding forage (Nutritional Requirements)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Current recommendations are that horses receive at least 1.5–2% of their body weight (BW) in forage per day on a DM basis."}}]},"equine-medicine--equine-nutrition--คุณภาพหญ้าและ-rfv":{"claims":[{"id":"equine-medicine--equine-nutrition--คุณภาพหญ้าและ-rfv--v1","statement":"หญ้าที่มี lignin ต่ำกว่า (ในแอลฟัลฟา) ถูกมองว่าเป็นแหล่งอาหารหยาบคุณภาพสูงกว่า เพราะย่อยได้ดีขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34013333","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Reduced lignin alfalfa (Medicago sativa L.) has the potential to provide a higher-quality forage source for livestock by improving forage digestibility."}}]},"equine-medicine--equine-nutrition--เมื่อหญ้าไม่พอ-อาหารแทนหญ้า-อาหารข้น-ไขมัน-ธัญพืช-และฉลาก":{"claims":[{"id":"equine-medicine--equine-nutrition--เมื่อหญ้าไม่พอ-อาหารแทนหญ้า-อาหารข้น-ไขมัน-ธัญพืช-และฉลาก--v1","statement":"การเพิ่มแคลอรีทำได้โดยค่อยๆ เพิ่มอาหารข้นไขมันสูงหรือน้ำมัน ซึ่งเหมาะกับม้าผอมที่ต้องใช้อาหาร NSC ต่ำ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Energy Requirements, increasing caloric intake","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"slowly adding a high-fat concentrate, adding oil (ideal for underweight metabolic horses that require low-NSC diets)"}}]},"equine-medicine--equine-nutrition--แป้ง-hindgut-acidosis-และ-gastric-ulcer":{"claims":[{"id":"equine-medicine--equine-nutrition--แป้ง-hindgut-acidosis-และ-gastric-ulcer--v1","statement":"การให้อาหารเป็นมื้อห่าง การได้น้ำตาลและแป้งสูง และการขาดอาหารหยาบ สัมพันธ์กับความเสี่ยง equine squamous gastric disease ที่เพิ่มขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31637798","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nutritional factors such as intermittent feeding, high sugars and starch intake, large amounts of straw as forage and prolonged time without access to forage have all been associated with an increased risk of equine squamous gastric disease (ESGD)."}}]},"equine-medicine--equine-nutrition--จัดอาหารทั้งชุด-ติดตาม-และตัวอย่าง":{"claims":[{"id":"equine-medicine--equine-nutrition--จัดอาหารทั้งชุด-ติดตาม-และตัวอย่าง--v1","statement":"อาหารข้นสูตรเฉพาะหรือ ration balancer ใช้เสริมอาหารหยาบได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-nutritional-requirements-of-horses-and-other-equids-2026","locator":"Pregnancy and Lactation Requirements","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In general, a concentrate specifically formulated for broodmares and growing foals is recommended to supplement forage; an alternative is adding an appropriate amount of a ration balancer to the diet"}}]}},"equine-medicine--equine-dentistry":{"equine-medicine--equine-dentistry--สิ่งที่เอกสารนี้มีและไม่มีเรื่องฟัน":{"claims":[{"id":"equine-medicine--equine-dentistry--สิ่งที่เอกสารนี้มีและไม่มีเรื่องฟัน--v1","statement":"การประมาณอายุม้าจากฟันไม่มีทางแม่นยำ เพราะความแปรปรวนระหว่างตัวม้ากว้างมากจนกำหนดอายุที่แน่นอนให้ลักษณะฟันแต่ละแบบไม่ได้ สนับสนุนการเขียนกำกับว่า estimated by dental แทนการระบุปีเกิดเป็นค่าจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8533255","locator":"Vol 137(5), pp. 117-121, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The results show that specific ages cannot be assigned to these dental criteria owing to the wide variation between horses, and that as a result the estimation of age from dentition can never be precise."}}]},"equine-medicine--equine-dentistry--โครงสร้างฟันม้า-hypsodont-anisognathism-infundibulum-และ-dental-":{"claims":[{"id":"equine-medicine--equine-dentistry--โครงสร้างฟันม้า-hypsodont-anisognathism-infundibulum-และ-dental---v1","statement":"ฟัน cheek teeth ของม้าเป็น hypsodont มี crown ยาวที่ถูก coronal cementum คลุมทั้งหมดตั้งแต่ฟันขึ้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24470439","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"they possess long crowns that are completely covered by coronal cement at eruption"}}]},"equine-medicine--equine-dentistry--สูตรฟัน-และศัพท์บอกด้านของฟัน":{"claims":[{"id":"equine-medicine--equine-dentistry--สูตรฟัน-และศัพท์บอกด้านของฟัน--v1","statement":"wolf tooth คือ premolar ซี่แรกของม้า ซึ่งเป็นฟันเหลือร่องรอยที่ไม่มีบทบาทในการเคี้ยว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31547760","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The equine first premolar is now considered a vestigial tooth that does not play a role in mastication."}}]},"equine-medicine--equine-dentistry--ระบบเรียกชื่อฟัน-3-ระบบ-anatomical-cheek-teeth-modified-triadan":{"claims":[{"id":"equine-medicine--equine-dentistry--ระบบเรียกชื่อฟัน-3-ระบบ-anatomical-cheek-teeth-modified-triadan--v1","statement":"ในระบบ Triadan เลข 108 คือ premolar ซี่ที่ 4 ด้านขวาบน (หลักแรก 1 = upper right, 08 = premolar 4)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41457381","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the right permanent fourth premolar (Triadan 108)"}}]},"equine-medicine--equine-dentistry--การคะเนอายุจากฟัน-หลักการ-และฟันน้ำนม":{"claims":[{"id":"equine-medicine--equine-dentistry--การคะเนอายุจากฟัน-หลักการ-และฟันน้ำนม--v1","statement":"การประมาณอายุม้าจากฟันไม่เคยแม่นยำ เพราะแต่ละตัวต่างกันมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8533255","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the estimation of age from dentition can never be precise"}}]},"equine-medicine--equine-dentistry--การคะเนอายุ-ฟันแท้ตั้งแต่-2-ปีครึ่งถึงม้าแก่":{"claims":[{"id":"equine-medicine--equine-dentistry--การคะเนอายุ-ฟันแท้ตั้งแต่-2-ปีครึ่งถึงม้าแก่--v1","statement":"การขึ้นของฟันตัดเป็นลักษณะที่คงเส้นคงวาที่สุดในการคะเนอายุ แต่ไม่น่าเชื่อถือสมบูรณ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8533255","locator":"abstract","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The eruption of the incisor teeth was the most consistent feature but it was not totally reliable."}}]},"equine-medicine--equine-dentistry--การตรวจช่องปาก-อุปกรณ์-sedation-ประวัติ-และการตรวจภายนอก":{"claims":[{"id":"equine-medicine--equine-dentistry--การตรวจช่องปาก-อุปกรณ์-sedation-ประวัติ-และการตรวจภายนอก--v1","statement":"การตรวจช่องปากม้าอย่างครบถ้วนทำภายใต้ sedation และใช้ full-mouth speculum","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17286128","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All horses were sedated and a full-mouth speculum was used to facilitate a complete oral examination."}}]},"equine-medicine--equine-dentistry--การตรวจในช่องปาก-ความถี่การตรวจ-และกฎการวินิจฉัย":{"claims":[{"id":"equine-medicine--equine-dentistry--การตรวจในช่องปาก-ความถี่การตรวจ-และกฎการวินิจฉัย--v1","statement":"ม้าที่ปล่อยแทะหญ้าตามแปลงมักต้องทำฟันปีละครั้ง ส่วนม้าที่เลี้ยงในคอกกินหญ้าแห้งและอาหารเม็ดอาจต้องตรวจช่องปากและทำฟันปีละสองครั้ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-overview-of-general-dentistry-in-horses-2024","locator":"Routine Dental Prophylaxis and Extractions","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses that graze on free range or grass usually require yearly dental prophylaxis; horses that are confined to stalls and essentially fed hay and grain may require twice-yearly oral examinations and dental prophylaxis."}}]},"equine-medicine--equine-dentistry--ความผิดปกติของฟันม้า":{"claims":[{"id":"equine-medicine--equine-dentistry--ความผิดปกติของฟันม้า--v1","statement":"sharp enamel point เกิดที่ขอบ buccal ของฟันบนและขอบ lingual ของฟันล่าง และแก้ด้วยการตะไบฟัน (floating)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-irregular-wear-of-the-dentition-in-horses-2024","locator":"Irregular wear of the dentition","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"results in the development of enamel points on the buccal edges of the upper arcades and on the lingual edges of the lower arcades. Enamel points are best treated by regular dental equilibration (ie, teeth floating)."}}]}},"equine-medicine--equine-tumors":{"equine-medicine--equine-tumors--4-tumor-types-covered":{"claims":[{"id":"equine-medicine--equine-tumors--4-tumor-types-covered--v1","statement":"Sarcoid เป็น cutaneous neoplasm ที่พบบ่อยที่สุดในม้า — ใน survey ของ equine cutaneous/mucocutaneous neoplasms 536 ราย sarcoid คิดเป็น 51.4% ของเนื้องอกทั้งหมด และ mean age ตอนวินิจฉัยคือ 9 ปี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16566271","locator":"J Vet Diagn Invest 18(1):123-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sarcoids represented 51.4% of all neoplasms and 15.18% of total equine accessions."}},{"id":"equine-medicine--equine-tumors--4-tumor-types-covered--v2","statement":"Squamous cell carcinoma (SCC) เป็นเนื้องอกผิวหนัง/เยื่อเมือกที่พบรองจาก sarcoid (18.3% ของ 536 neoplasms) โดย ocular SCC พบบ่อยใน Paint และ Quarter Horse ส่วน penile/preputial SCC พบบ่อยใน Appaloosa และ Quarter Horse; mean age ของม้าที่เป็น ocular SCC = 13 ปี ซึ่งน้อยกว่ากลุ่ม penile/preputial (21 ปี)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16566271","locator":"J Vet Diagn Invest 18(1):123-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Squamous cell carcinoma constituted 18.3% of all neoplasms and 5.41% of total equine accessions. Ocular squamous cell carcinoma was most common in paints and quarter horses, and penile/preputial squamous cell carcinoma was most common in ap"}},{"id":"equine-medicine--equine-tumors--4-tumor-types-covered--v3","statement":"Equine sarcoid สัมพันธ์กับ bovine papillomavirus โดย BPV-1 เป็น type หลักที่พบในยุโรป — ในการศึกษาม้าที่โปแลนด์ ตรวจพบ BPV DNA ใน 21/40 (52.5%) ของ sarcoid ที่วินิจฉัยทางคลินิก และในจำนวนนี้เป็น BPV-1 20 ราย ส่วน BPV-2 พบเพียง 1 ราย (4.8%)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30997762","locator":"Pol J Vet Sci 22(1):25-29","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The DNA was detected in 21/40 (52.5%) of clinically diagnosed sarcoids."}},{"id":"equine-medicine--equine-tumors--4-tumor-types-covered--v4","statement":"Melanoma ในม้าสีเทา (gray) พบได้บ่อยมากและเพิ่มตามอายุ — epidemiological survey ใน Camargue-type gray-skinned horses 264 ตัว พบ prevalence รวม 31.4% และสูงถึง 67% ในม้าอายุมากกว่า 15 ปี โดยตำแหน่งที่พบบ่อยที่สุดคือใต้โคนหาง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10761996","locator":"Pigment Cell Res 13(1):47-51","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the prevalence of melanomas in the overall population was 31.4%; ... the incidence of melanomas was significantly correlated with age, giving a prevalence of 67% at ages > 15 years; ... the most frequently occurring body site of these tumor"}}]},"equine-medicine--equine-tumors--case-01-scc-at-medial-canthus":{"claims":[{"id":"equine-medicine--equine-tumors--case-01-scc-at-medial-canthus--v1","statement":"SCC เป็นมะเร็งที่พบบ่อยที่สุดของตาม้า และมักเริ่มต้นที่ limbus แล้วลุกลามเข้า cornea ทำให้เสียการมองเห็นหรือเสียลูกตาได้ ซึ่งตรงกับ case นี้ที่มี mass ที่ medial palpebral conjunctiva และ corneal limbus","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28425625","locator":"Int J Cancer 141(2):342-353","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Squamous cell carcinoma (SCC) is the most common cancer of the equine eye, frequently originating at the limbus, with the potential to invade the cornea, cause visual impairment, and result in loss of the eye."}},{"id":"equine-medicine--equine-tumors--case-01-scc-at-medial-canthus--v2","statement":"Intratumoral (intralesional) cisplatin ใน purified sesame oil ขนาด 1 mg ต่อเนื้อเยื่อ 1 cm³ ให้ 4 ครั้ง ห่างกันครั้งละ 2 สัปดาห์ โดยเริ่มครั้งแรกตอนผ่าตัด ให้ relapse-free survival ประมาณ 92 ± 5% ที่ 1 ปี และ 77 ± 11% ที่ 4 ปี ในม้า 27 ตัว (32 tumors) โดย local toxicosis น้อยและไม่รบกวนการหายของแผล","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7890578","locator":"J Am Vet Med Assoc 205(8):1170-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dosage was 1 mg of cisplatin/cm3 of tissue. The mean relapse-free interval was 41 +/- 3.7 months. The estimates of overall relapse-free survival rates were 92 +/- 5% at 1 year and 77 +/- 11% at 4 years."}}]},"equine-medicine--equine-tumors--sarcoid":{"claims":[{"id":"equine-medicine--equine-tumors--sarcoid--v1","statement":"sarcoid เป็นเนื้องอกผิวหนังที่พบบ่อยที่สุดในม้าจริง และเกิดจากการติดเชื้อ bovine papillomavirus type 1 และ type 2 ตรงกับที่สไลด์ระบุว่า BPV-1 เป็นหลักหรือ BPV-2","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37336425","locator":"Abstract, opening sentence; vol 298-299:106011","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Infection with bovine papillomavirus (BPV) types 1 and 2 results in the most common skin tumor of horses, termed equine sarcoid."}},{"id":"equine-medicine--equine-tumors--sarcoid--v2","statement":"ความไวต่อ sarcoid ถ่ายทอดแบบ polygenic จริง และในม้าพันธุ์ Franches-Montagnes ของสวิตเซอร์แลนด์ heritability บน liability scale ประมาณ 21% ซึ่งตรงกับตัวเลขมากกว่า 20% ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24152383","locator":"Abstract, results; vol 199(1):68-71","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The analyses reveal that variation in susceptibility to ES is best explained by a model incorporating polygenic variation... A corrected value for the heritability on a liability scale was estimated at 21%"}},{"id":"equine-medicine--equine-tumors--sarcoid--v3","statement":"การพยากรณ์โรคแย่ลงในก้อนที่เคยรักษาแล้วไม่สำเร็จจริง โดยโอกาสกลับเป็นซ้ำหลังผ่าตัดสูงขึ้นอย่างมีนัยสำคัญทั้งในก้อนขนาดใหญ่และก้อนที่เคยไม่ตอบสนองต่อการรักษามาก่อน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11765322","locator":"Abstract, recurrence analysis; vol 149(22):665-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The probability of local recurrence after excision was significantly higher for large sarcoids and sarcoids which had previously failed to respond to treatment."}},{"id":"equine-medicine--equine-tumors--sarcoid--v4","statement":"การฉีด cisplatin เข้าก้อนได้ผลสูงใน sarcoid จริง โดยในซีรีส์ 630 ก้อน อัตราการควบคุมโรคเฉพาะที่หลังการรักษาหนึ่งคอร์สอยู่ที่ 96.3% สำหรับ sarcoid ซึ่งอยู่ในช่วง 87 ถึง 97% ที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17504043","locator":"Abstract, cure rates by tumour type; vol 230(10):1506-13","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For all tumor stages combined, cure rates after 1 course of treatment were 96.3% for sarcoids, 96% for lymphomas, 88% for squamous cell carcinomas, 85% for soft tissue sarcomas, and 81% for melanomas."}}]},"equine-medicine--equine-tumors--squamous-cell-carcinoma-scc":{"claims":[{"id":"equine-medicine--equine-tumors--squamous-cell-carcinoma-scc--v1","statement":"SCC เป็นเนื้องอกผิวหนังที่พบมากเป็นอันดับสองในม้ารองจาก sarcoid โดยการทบทวนชิ้นเนื้อ 3,351 ชิ้นจากม้า 3,272 ตัว พบว่า sarcoid, squamous cell carcinoma และ melanoma เป็นสามอันดับแรก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23234288","locator":"Abstract, results; vol 242(1):99-104","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sarcoid, squamous cell carcinoma (SCC), and melanoma were the 3 most common tumors diagnosed."}},{"id":"equine-medicine--equine-tumors--squamous-cell-carcinoma-scc--v2","statement":"แสง UV บนผิวที่ไม่มีเม็ดสีเป็นปัจจัยเสี่ยงจริง โดยเนื้องอกที่สัมพันธ์กับรังสี UV รวมถึง SCC พบมากกว่า 2.3 เท่าในพื้นที่ที่ได้รับ UV สูงกว่า และม้าพันธุ์ Appaloosa กับ American Paint ซึ่งมีผิวไม่มีเม็ดสีเป็นหย่อม มีโอกาสเป็นเนื้องอกกลุ่มนี้สูงกว่าพันธุ์อื่น 7.2 เท่าและ 4.4 เท่าตามลำดับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23234288","locator":"Abstract, UV-associated tumour analysis; vol 242(1):99-104","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Appaloosa horses and American Paint horses, respectively, were 7.2 (95% CI, 5.6 to 9.2) and 4.4 (95% CI, 3.6 to 5.4) times as likely as other breeds to have tumors associated with UV radiation."}},{"id":"equine-medicine--equine-tumors--squamous-cell-carcinoma-scc--v3","statement":"EcPV-2 สัมพันธ์กับรอยโรคที่องคชาตและหนังหุ้มจริง โดยตัวอย่าง penile papilloma และ squamous cell carcinoma ที่ตรวจทุกตัวอย่างมี DNA ของ EcPV2 และตรวจพบ DNA ของไวรัสอยู่ในนิวเคลียสของ koilocyte ด้วย in situ hybridization","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23064881","locator":"Abstract, results; vol 50(4):686-92","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All tested papilloma and squamous cell carcinoma samples were found to contain DNA of either of 2 previously published EcPV2 variants."}},{"id":"equine-medicine--equine-tumors--squamous-cell-carcinoma-scc--v4","statement":"การฉีด cisplatin เข้าก้อนใช้รักษา SCC ได้จริง โดยอัตราการควบคุมโรคเฉพาะที่หลังการรักษาหนึ่งคอร์สอยู่ที่ 88% สำหรับ squamous cell carcinoma","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17504043","locator":"Abstract, cure rates by tumour type; vol 230(10):1506-13","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"cure rates after 1 course of treatment were 96.3% for sarcoids, 96% for lymphomas, 88% for squamous cell carcinomas"}}]},"equine-medicine--equine-tumors--melanoma":{"claims":[{"id":"equine-medicine--equine-tumors--melanoma--v1","statement":"melanoma พบในม้าสีเทาที่อายุมากจริง และตำแหน่งของก้อนตั้งต้นที่พบบ่อยคือโคนหางด้านล่าง ฝีเย็บ และต่อมน้ำลาย parotid โดยม้าทั้ง 14 ตัวในซีรีส์ metastatic melanoma เป็นม้าสีเทาสูงอายุ อายุเฉลี่ย 16 ปี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12141308","locator":"Abstract, signalment and primary sites; vol 16(4):452-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All were older gray horses, with an average age of 16 years. The most common sites of primary tumors were the ventral tail, perineum, and parotid salivary gland."}},{"id":"equine-medicine--equine-tumors--melanoma--v2","statement":"การพยากรณ์โรคที่ guarded ถึง poor ในรายที่เป็นมานานมีหลักฐานรองรับ โดยม้าหลายตัวมี dermal melanoma อยู่นาน 1 ถึง 6 ปีก่อนเสียชีวิตจากการแพร่กระจาย และตำแหน่งแพร่กระจายที่พบบ่อยคือต่อมน้ำเหลือง ตับ ม้าม กล้ามเนื้อลาย และปอด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12141308","locator":"Abstract, metastasis and course; vol 16(4):452-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most common sites for metastases were the lymph nodes, liver, spleen, skeletal muscle, lungs, and surrounding or within blood vessels throughout the body. Many of the horses had dermal melanomas for years (range 1-6 years) before succum"}},{"id":"equine-medicine--equine-tumors--melanoma--v3","statement":"cimetidine ให้ผลไม่น่าเชื่อถือจริง โดยม้า 4 ตัวที่ได้รับการผ่าตัดลดขนาดก้อนร่วมกับ cimetidine หรือวัคซีนจากเนื้องอกของตัวเอง ไม่มีผลต่อผลลัพธ์ของโรค","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12141308","locator":"Abstract, treatment; vol 16(4):452-6","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Treatment consisting of surgical debulking and administration of cimetidine, an autogenous vaccine, or both was attempted in 4 horses with no effect on outcome."}},{"id":"equine-medicine--equine-tumors--melanoma--v4","statement":"การฉีด cisplatin เข้าก้อนใช้กับ melanoma ได้จริง แต่ได้ผลต่ำที่สุดในบรรดาเนื้องอกผิวหนังที่ศึกษา คืออัตราการควบคุมโรคเฉพาะที่ 81% เทียบกับ 96.3% ใน sarcoid","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17504043","locator":"Abstract, cure rates by tumour type; vol 230(10):1506-13","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"cure rates after 1 course of treatment were 96.3% for sarcoids... 85% for soft tissue sarcomas, and 81% for melanomas."}}]},"equine-medicine--equine-tumors--eosinophilic-granuloma":{"claims":[{"id":"equine-medicine--equine-tumors--eosinophilic-granuloma--v1","statement":"eosinophilic granuloma เป็นรอยโรคก้อนที่ไม่ใช่เนื้องอกที่พบบ่อยในม้าจริง โดยอยู่ในกลุ่มห้าอันดับแรกร่วมกับ exuberant granulation tissue, fungal granuloma, cyst และ habronemiasis ซึ่งรวมกันเป็น 91% ของรอยโรคที่ไม่ใช่เนื้องอกทั้งหมด และรายชื่อนี้ตรงกับการวินิจฉัยแยกโรคในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16359312","locator":"Abstract, results; vol 16(6):425-8","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Exuberant granulation tissue, eosinophilic granuloma, fungal granuloma, cysts and habronaemiasis were most common, and constituted 91% of non-neoplastic lesions, 16% of all lesions studied"}}]},"equine-medicine--equine-tumors--ppid-หรือ-equine-cushing-s-disease-pituitary-pars-intermedia-dys":{"claims":[{"id":"equine-medicine--equine-tumors--ppid-หรือ-equine-cushing-s-disease-pituitary-pars-intermedia-dys--v1","statement":"พยาธิกำเนิดของ PPID คือการเสื่อมของ dopaminergic neuron ใน hypothalamus ทำให้ melanotrope ของ pars intermedia เพิ่มจำนวนเป็น hyperplasia และ adenoma จริง และขนาดยา pergolide เริ่มต้นที่ 2 ug/kg กินวันละครั้งเป็นขนาดที่ใช้ได้ผลในการศึกษา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32977825","locator":"Abstract, background and methods; vol 16(1):356","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pituitary pars intermedia dysfunction (PPID) develops slowly in aged horses as degeneration of hypothalamic dopaminergic neurons leads to proliferation of pars intermedia (PI) melanotropes through hyperplasia and adenoma formation... six PP"}},{"id":"equine-medicine--equine-tumors--ppid-หรือ-equine-cushing-s-disease-pituitary-pars-intermedia-dys--v2","statement":"PPID เป็นโรคเสื่อมของระบบประสาทที่สัมพันธ์กับอายุและพบมากกว่า 20% ของม้าสูงอายุ การแปลผล basal ACTH และ TRH stimulation test ต้องอิงค่าตัดตามฤดูกาลจริง โดยค่า ACTH หลังกระตุ้นด้วย TRH ต่ำสุดในเดือนกุมภาพันธ์ถึงพฤษภาคม และสูงสุดในเดือนสิงหาคมถึงตุลาคม และ TRH stimulation ให้ความแม่นยำในการวินิจฉัยดีกว่า basal ACTH โดยเฉพาะในรายที่อาการยังไม่ชัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37802466","locator":"Abstract, background and results; vol 300-302:106035","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pituitary pars intermedia dysfunction (PPID) is an age-related neurodegenerative disorder, affecting >20 % of older horses... TRH-stimulated ACTH concentrations were lowest in February-May and highest in August-October... TRH stimulation ha"}}]}},"equine-medicine--equine-ophth":{"equine-medicine--equine-ophth--กายวิภาคและการมองเห็นของม้า":{"claims":[{"id":"equine-medicine--equine-ophth--กายวิภาคและการมองเห็นของม้า--v1","statement":"ม้ามีบริเวณบอดอยู่ตรงหน้าผากพอดี และ binocular overlap ชี้เฉียงลงไปตามแนวจมูก ทำให้การมองด้านหน้าตรงไม่ดี ซึ่งเป็นเหตุผลจริงที่ม้าเงยหน้าเพื่อมองวัตถุไกล ตรงกับที่สไลด์ระบุว่า binocular vision ด้านหน้าไม่ดี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10505953","locator":"31(5):384-390, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the horse rotates the nose up high to observe distant objects because binocular overlap is oriented down the nose, with a blind area directly in front of the forehead"}},{"id":"equine-medicine--equine-ophth--กายวิภาคและการมองเห็นของม้า--v2","statement":"ความคมชัดของภาพในม้าไม่ได้กระจายเท่ากันทั่วจอตา บริเวณ visual streak ในจอตาส่วนล่างให้ความคมชัด 16.5 cycles per degree ขณะที่ส่วนรอบนอกได้เพียง 2.7 cycles per degree และแนวคิด ramp retina ที่เคยใช้อธิบายพฤติกรรมการหมุนหัวของม้านั้นได้รับการยืนยันแล้วว่าไม่มีจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10505953","locator":"31(5):384-390, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"acuity in the narrow, intense visual streak in the inferior retina is 16.5 cycles per degree compared with 2.7 cycles per degree in the periphery"}}]},"equine-medicine--equine-ophth--เปลือกตา-ท่อน้ำตา-และ-conjunctiva":{"claims":[{"id":"equine-medicine--equine-ophth--เปลือกตา-ท่อน้ำตา-และ-conjunctiva--v1","statement":"ปัญหาทางจักษุคิดเป็นสัดส่วนสูงถึงร้อยละ 20 ของเคสฉุกเฉินในเวชปฏิบัติม้า และการเย็บซ่อมเปลือกตาจัดเป็นหัตถการยืนที่พบบ่อย ซึ่งรองรับความสำคัญของหัวข้อ eyelid laceration ในสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34119404","locator":"37(2):441-460, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ophthalmic problems account for up to 20% of emergencies in equine practice."}},{"id":"equine-medicine--equine-ophth--เปลือกตา-ท่อน้ำตา-และ-conjunctiva--v2","statement":"การอุดตันของ nasolacrimal duct ในม้าแสดงอาการเป็นน้ำตาหรือขี้ตาชนิด mucoid ที่เป็นเรื้อรัง ร่วมกับ Jones I test ให้ผลลบ และไม่พบ nasal punctum โดยยืนยันการวินิจฉัยด้วย CT ร่วมกับสารทึบรังสี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30767380","locator":"22(4):538-544, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"copious yellow-tan mucoid ocular discharge with a negative Jones I test, absent nasal punctum, and unsuccessful anterograde nasolacrimal duct (NLD) irrigation"}}]},"equine-medicine--equine-ophth--กระจกตาและ-keratitis":{"claims":[{"id":"equine-medicine--equine-ophth--กระจกตาและ-keratitis--v1","statement":"น้ำตาของม้าที่มีแผลหลุมกระจกตามีทั้ง latent และ active form ของ matrix metalloproteinase 2 และ 9 และ N-acetylcysteine 10 เปอร์เซ็นต์ กับ EDTA 0.2 เปอร์เซ็นต์ ยับยั้งการทำงานของ MMP ได้ 98.8 และ 99.4 เปอร์เซ็นต์ ตามลำดับ ตรงกับที่สไลด์แนะนำ NAC และ Na EDTA เป็น anti-collagenase","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-13677383","locator":"64(9):1081-1087, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"total MMP activity (sum of all bands detected) observed on the gelatin zymogram gels was reduced by 99.4% by EDTA, 96.3% by doxycycline, 98.8% by NAC"}},{"id":"equine-medicine--equine-ophth--กระจกตาและ-keratitis--v2","statement":"เชื้อแบคทีเรียที่แยกได้บ่อยที่สุดจาก ulcerative keratitis ในม้าคือ Streptococcus equi subspecies zooepidemicus รองลงมาคือ Pseudomonas aeruginosa และ Staphylococcus spp ตรงกับสามสกุลที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15892227","locator":"37(3):207-211, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Streptococcus equi subspecies zooepidemicus was the most commonly isolated organism, accounting for 33.3% of all isolates, followed by Pseudomonas aeruginosa (11.8%), Staphylococcus spp. (11.8%)"}},{"id":"equine-medicine--equine-ophth--กระจกตาและ-keratitis--v3","statement":"เชื้อราที่แยกได้บ่อยที่สุดจาก ulcerative keratomycosis ในม้าคือ Aspergillus และ Fusarium และการรักษาเชิงรุกให้ผลด้านการมองเห็นดีถึงร้อยละ 92.3 ของตา 39 ตา โดยยาต้านเชื้อราชนิดหยอดที่ใช้บ่อยที่สุดคือ miconazole","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9535066","locator":"30(2):109-116, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Aspergillus (n = 13) and Fusarium (n = 10) were the most commonly isolated fungi. Miconazole (n = 35) was the most common topical antifungal medication utilised."}},{"id":"equine-medicine--equine-ophth--กระจกตาและ-keratitis--v4","statement":"Cyclosporin A ชนิดหยอดตาถูกใช้อย่างปลอดภัยในม้าที่เป็น keratitis และ keratouveitis 11 เคส และให้ผลเป็นยาต้านการอักเสบที่ได้ผลใน 9 เคส รวมถึงกลุ่มที่เป็น interstitial keratouveitis และ endotheliitis ซึ่งรองรับการใช้ยากดภูมิเฉพาะที่ในกลุ่ม immune mediated keratitis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8654346","locator":"27(5):327-333, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Topical cyclosporine A was safely used in a series of 11 cases of equine keratitis and keratouveitis and appeared to be an effective anti-inflammatory agent in 9 cases."}}]},"equine-medicine--equine-ophth--การให้ยาที่ตาในม้า":{"claims":[{"id":"equine-medicine--equine-ophth--การให้ยาที่ตาในม้า--v1","statement":"Subpalpebral lavage system ทำให้หยอดยาน้ำเข้าผิวตาม้าได้สะดวก ปลอดภัย และบ่อยครั้ง โดยจากเคส 61 ระบบ มีภาวะแทรกซ้อนร้อยละ 13.1 ได้แก่ แผลหลุมกระจกตาจากตัวสาย ฝีที่เปลือกตา เยื่อตาคลุม footplate และ cellulitis ที่เปลือกตา ระยะเวลาใช้เฉลี่ย 7.5 วัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35830905","locator":"117:104076, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Subpalpebral lavage (SPL) treatment systems allow topical aqueous medications to be conveniently, safely, and frequently administered to the ocular surface."}},{"id":"equine-medicine--equine-ophth--การให้ยาที่ตาในม้า--v2","statement":"ตำแหน่งวาง SPL มีผลต่อภาวะแทรกซ้อน โดยระบบที่วางเปลือกตาบนเกิดภาวะแทรกซ้อน 7 จาก 30 ระบบ ขณะที่เปลือกตาล่างเกิดเพียง 1 จาก 24 ระบบ และผู้เขียนเลือกใช้ inferior fornix เป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35830905","locator":"117:104076, Results และ Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Seven complications were reported for upper eyelid systems (23.3%) and 1 complication for lower eyelid systems (4.2%)... encourage the authors to favor the lower fornix for subpalpebral lavage treatment systems"}}]},"equine-medicine--equine-ophth--scc-และก้อนเนื้อที่ตา":{"claims":[{"id":"equine-medicine--equine-ophth--scc-และก้อนเนื้อที่ตา--v1","statement":"ความชุกของ ocular และ adnexal squamous cell carcinoma ในม้าเพิ่มขึ้นตามระดับ mean annual solar radiation และระดับความสูง และม้าทุกสีขนมีความชุกสูงกว่าม้าสี bay brown หรือ black อย่างมีนัยสำคัญ ตรงกับที่สไลด์ระบุว่าเกิดในม้าสีอ่อนที่โดนแสง UV","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2004985","locator":"198(2):251-256, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"an increased prevalence of SCC with an increase in longitude, altitude, or mean annual solar radiation... The prevalence of ocular/adnexal SCC was significantly greater for all hair colors when compared with bay, brown, or black (P less tha"}},{"id":"equine-medicine--equine-ophth--scc-และก้อนเนื้อที่ตา--v2","statement":"ตำแหน่งที่พบ ocular และ adnexal SCC บ่อยที่สุดในม้า 147 ตัว คือ nictitating membrane หรือ nasal canthus ร้อยละ 28.1 รองลงมาคือ limbus ร้อยละ 27.5 และเปลือกตาร้อยละ 22.8 รองรับทั้งประเด็นก้อนที่ medial canthus และการที่รอยโรคเกาะอยู่กับหนังตาที่สาม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2004996","locator":"198(2):298-303, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The nictitating membrane, nasal canthus, or both (28.1%); limbus (27.5%); and eyelid (22.8%) were most commonly affected."}},{"id":"equine-medicine--equine-ophth--scc-และก้อนเนื้อที่ตา--v3","statement":"การผ่าตัดอย่างเดียวสัมพันธ์กับการกลับเป็นซ้ำอย่างมีนัยสำคัญ ขณะที่เคสที่ใช้ adjunctive therapy ร่วมด้วยมีอัตราการกลับเป็นซ้ำต่ำกว่า ตรงกับที่สไลด์ระบุว่าต้องใช้หลายวิธีร่วมกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1778163","locator":"23(6):449-452, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tumour recurrence was significant when surgery alone was performed... Cases in which adjunctive therapy was used correlated with a lower rate of recurrence."}},{"id":"equine-medicine--equine-ophth--scc-และก้อนเนื้อที่ตา--v4","statement":"การผ่าตัดกระจกตาที่ต้องอาศัยความแม่นยำระดับ microsurgery ทำในม้ายืนไม่ได้ เพราะไม่สามารถใช้ operating microscope และไม่สามารถกำจัดการเคลื่อนไหวของตาและศีรษะได้ ซึ่งรองรับข้อความในสไลด์ว่า keratectomy ต้องวางยาสลบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24680208","locator":"30(1):91-110, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The inability to use an operating microscope in standing surgery in horses prevents performing precise corneal and intraocular microsurgeries."}}]},"equine-medicine--equine-ophth--uvea-และ-equine-recurrent-uveitis-eru":{"claims":[{"id":"equine-medicine--equine-ophth--uvea-และ-equine-recurrent-uveitis-eru--v1","statement":"ม้าพันธุ์ Appaloosa มีโอกาสเกิด uveitis สูงกว่าม้าพันธุ์อื่นด้วย odds ratio 8.3 ซึ่งตรงกับตัวเลข 8 เท่าในสไลด์ และยังมีโอกาสตาบอดสูงกว่าด้วย odds ratio 3.8","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7591929","locator":"207(10):1327-1331, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Of the 112 horses with uveitis, 28 (25%) were Appaloosas, compared with only 10 of the 260 (4%) horses without uveitis (odds ratio, 8.3)."}},{"id":"equine-medicine--equine-ophth--uvea-และ-equine-recurrent-uveitis-eru--v2","statement":"Posterior synechia เป็นหนึ่งในอาการทางคลินิกที่จำเพาะของ chronic ERU ร่วมกับ corneal edema, aqueous flare, การเสื่อมของ corpora nigra และ cataract และรอยโรคเป็นการแทรกของ lymphocyte ชนิด CD4 positive แบบ T helper 1 ซึ่งเป็นเหตุผลที่ต้องใช้ยากดภูมิในการรักษา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10522783","locator":"71(1):17-28, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eyes with ERU exhibited characteristic clinical signs, including corneal edema, aqueous flare, posterior synechia, corpora nigra degeneration, and cataract formation."}}]},"equine-medicine--equine-ophth--lens-cataract-และ-glaucoma":{"claims":[{"id":"equine-medicine--equine-ophth--lens-cataract-และ-glaucoma--v1","statement":"เพราะขนาดลูกตาของม้าโตเต็มวัย จึงต้องมีเครื่องมือผ่าตัดที่ออกแบบเฉพาะสำหรับม้า ซึ่งเป็นรากฐานของการเปลี่ยนแปลงเทคนิคผ่าตัดต้อกระจกในม้าช่วง 15 ถึง 20 ปีที่ผ่านมา ตรงกับที่สไลด์เตือนว่าเครื่องมือของม้าใหญ่กว่าสัตว์เล็กและใช้แทนกันไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20939165","locator":"Suppl 37:38-45, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Due to the size of the adult equine globe, the introduction of species-specific instrumentation has provided the cornerstone to many of the changes made regarding surgical technique over the last 15-20 years."}},{"id":"equine-medicine--equine-ophth--lens-cataract-และ-glaucoma--v2","statement":"ผลลัพธ์ของ phacoemulsification and aspiration ในม้า 46 ตา คือมองเห็นได้ 25 ตา คิดเป็นร้อยละ 54 และตาที่มี chronic uveitis อยู่ก่อนมีโอกาสมองเห็นต่ำกว่าอย่างมีนัยสำคัญ คือร้อยละ 25 เทียบกับร้อยละ 65 ส่วนอายุและการใส่ IOL ไม่สัมพันธ์กับผลลัพธ์ที่แย่ลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24862225","locator":"17 Suppl 1:160-167, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Eyes with preoperative chronic uveitis were significantly less likely to be visual (3 of 12 eyes [25%]) than horses without preoperative chronic uveitis (22 of 34 eyes [65%]) (P = 0.023)."}},{"id":"equine-medicine--equine-ophth--lens-cataract-และ-glaucoma--v3","statement":"Glaucoma ในม้าเกิดตามหลัง uveitis เป็นส่วนใหญ่ โดยพบหลักฐานของ uveitis ใน 20 จาก 23 ตา คิดเป็นร้อยละ 87 และม้าพันธุ์ Appaloosa กับม้าอายุมากมีความเสี่ยงสูง อีกทั้งพบ corneal striae ถึงร้อยละ 70 ตรงกับสาเหตุโน้มนำและรอยโรคที่สไลด์ระบุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23859597","locator":"17(5):334-342, Results และ Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Equine glaucoma most commonly occurs secondary to uveitis with Appaloosas and older horses predisposed."}}]},"equine-medicine--equine-ophth--retina-และ-fundus-ปกติของม้า":{"claims":[{"id":"equine-medicine--equine-ophth--retina-และ-fundus-ปกติของม้า--v1","statement":"ม้ามี cone เพียงสองชนิดคือ short wavelength sensitive ที่ยอดการตอบสนอง 428 นาโนเมตร และ middle to long wavelength sensitive ที่ 539 นาโนเมตร จึงเป็น dichromat ซึ่งสอดคล้องกับที่สไลด์ระบุว่าม้าเห็นเฉพาะช่วงสีฟ้าและสีเขียว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12678603","locator":"1(2):80-87, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The spectral sensitivity of the S cone was estimated to have a peak of 428 nm, while the M/L cone had a peak of 539 nm. These two cone types would provide the basis for dichromatic color vision"}}]},"equine-medicine--equine-ophth--ค่าเฝ้าระวังขณะวางยาสลบม้า-กล่องที่แทรกอยู่หน้าเดียวกัน":{"claims":[{"id":"equine-medicine--equine-ophth--ค่าเฝ้าระวังขณะวางยาสลบม้า-กล่องที่แทรกอยู่หน้าเดียวกัน--v1","statement":"การรักษา mean arterial blood pressure ไว้ที่ 55 ถึง 65 mmHg นาน 3.5 ชั่วโมง ทำให้ม้าทุกตัวเกิด muscle dysfunction หลังฟื้น ขณะที่การรักษาไว้ที่ 85 ถึง 95 mmHg ม้าฟื้นได้ปกติทุกตัว ซึ่งรองรับขอบล่างของ MBP ที่ 70 mmHg ในกล่องค่าอ้างอิงของสไลด์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3826855","locator":"48(2):192-197, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All horses recovered uneventfully from normotensive anesthesia, but all had some muscle dysfunction after prolonged hypotensive anesthesia."}},{"id":"equine-medicine--equine-ophth--ค่าเฝ้าระวังขณะวางยาสลบม้า-กล่องที่แทรกอยู่หน้าเดียวกัน--v2","statement":"การเปลี่ยนนิยาม hypotension จาก MAP ต่ำกว่า 60 mmHg เป็นต่ำกว่า 70 mmHg แล้วรักษาด้วยสารน้ำปริมาณสูงร่วมกับ dobutamine ทำให้จำนวนม้าที่เอนไซม์กล้ามเนื้อสูงลดจาก 5 ใน 17 ตัว เหลือ 1 ใน 18 ตัว รองรับเกณฑ์ MBP 70 ถึง 90 mmHg","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16476002","locator":"33(2):122-127, Results และ Conclusion","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Maintaining MAP >70 mmHg with high-volume fluid therapy and dobutamine may help to reduce the severity of myopathy."}}]},"equine-medicine--equine-ophth--orbit-การมองเห็น-และ-reflex":{"claims":[{"id":"equine-medicine--equine-ophth--orbit-การมองเห็น-และ-reflex--v1","statement":"ม้ามี binocular overlap ที่ชี้ลงตามแนวจมูก และมีจุดบอดตรงหน้าหน้าผาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10505953","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"binocular overlap is oriented down the nose, with a blind area directly in front of the forehead."}}]},"equine-medicine--equine-ophth--เปลือกตา-eyelid":{"claims":[{"id":"equine-medicine--equine-ophth--เปลือกตา-eyelid--v1","statement":"การซ่อมเปลือกตา (eyelid repair) เป็นหัตถการ standing ที่พบบ่อยในเวชปฏิบัติม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34119404","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"common standing surgical procedures such as eyelid repair or instillation of a subpalpebral lavage system"}}]},"equine-medicine--equine-ophth--conjunctiva-และท่อน้ำตา":{"claims":[{"id":"equine-medicine--equine-ophth--conjunctiva-และท่อน้ำตา--v1","statement":"Nasolacrimal duct atresia ในม้ามีขี้ตาเป็นหนองเรื้อรัง และไม่มีรูเปิดท่อน้ำตาในโพรงจมูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24666475","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The nasolacrimal orifice was absent in the left nasal meatum, and anterograde irrigation of left nasolacrimal duct was not possible."}}]},"equine-medicine--equine-ophth--กระจกตา-cornea-กายวิภาค-การตรวจ-และหลักการ":{"claims":[{"id":"equine-medicine--equine-ophth--กระจกตา-cornea-กายวิภาค-การตรวจ-และหลักการ--v1","statement":"การตรวจผิวตาม้าแนะนำให้ย้อม fluorescein และ Rose Bengal","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11397288","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"slit-lamp examination of the ocular surface before and after fluorescein dye application is recommended to detect dry eye problems. Rose Bengal dye application is also recommended in many cases."}}]},"equine-medicine--equine-ophth--keratitis-และการรักษากระจกตา":{"claims":[{"id":"equine-medicine--equine-ophth--keratitis-และการรักษากระจกตา--v1","statement":"sub-palpebral lavage system มีภาวะแทรกซ้อน โดยที่พบบ่อยที่สุดคือ footplate หลุดจาก conjunctival fornix","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40567141","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most common major complication was displacement of the lavage footplate from the conjunctival fornix (7/69; 10%)."}}]},"equine-medicine--equine-ophth--squamous-cell-carcinoma-ของตาและ-adnexa":{"claims":[{"id":"equine-medicine--equine-ophth--squamous-cell-carcinoma-ของตาและ-adnexa--v1","statement":"UV exposure มีส่วนทำให้เกิด squamous cell carcinoma ของตาม้า ผ่านการกลายพันธุ์ของ TP53","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41748902","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"TP53 mutations appear to contribute to eoSCC development, potentially as a consequence of UV-light exposure"}}]},"equine-medicine--equine-ophth--uvea-uveitis-และ-equine-recurrent-uveitis-eru":{"claims":[{"id":"equine-medicine--equine-ophth--uvea-uveitis-และ-equine-recurrent-uveitis-eru--v1","statement":"Recurrent uveitis เป็นสาเหตุนำของตาบอดในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7591929","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Recurrent uveitis, a leading cause of blindness in horses, often develops as a sequela to systemic leptospirosis."}}]},"equine-medicine--equine-ophth--เลนส์-ต้อกระจก-และ-glaucoma":{"claims":[{"id":"equine-medicine--equine-ophth--เลนส์-ต้อกระจก-และ-glaucoma--v1","statement":"Transscleral cyclophotocoagulation ด้วย diode laser ลด IOP ในม้าที่เป็น glaucoma","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20500721","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"IOP remained significantly lower than pretreatment values at all periods of clinical follow-up"}}]},"equine-medicine--equine-ophth--retina-equine-fundus-และโรคของ-retina":{"claims":[{"id":"equine-medicine--equine-ophth--retina-equine-fundus-และโรคของ-retina--v1","statement":"ม้ามีหลอดเลือด retina ขนาดเล็กอยู่เฉพาะบริเวณใกล้ optic disc (paurangiotic pattern)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2772405","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In the horse and the guinea pig the retinal blood vessels are minute and restricted to the direct neighbourhood of the optic disc (paurangiotic pattern)."}}]}},"equine-medicine--equine-poa":{"equine-medicine--equine-poa--pe-lameness-diagnostic-workflow-กรอบ-poa":{"claims":[{"id":"equine-medicine--equine-poa--pe-lameness-diagnostic-workflow-กรอบ-poa--v1","statement":"Palmar digital (PD) nerve block ด้วย mepivacaine ให้ analgesia เต็มที่ในช่วง 15 นาที ถึง 1 ชั่วโมงหลังฉีด จึงต้องประเมิน lameness ในหน้าต่างเวลานี้ หลังจาก 1-2 ชั่วโมงฤทธิ์เริ่มลดลง และกลับสู่ค่าก่อน block ที่ 24 ชั่วโมง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15656504","locator":"Equine Vet J 2004;36(8):723-6, Results and Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The palmar digital nerve block was fully effective between 15 mins and 1 h. The analgesic effect began to subside between 1 and 2 h but sufficient analgesia persisted to affect gait characteristics beyond 2 h. When using a palmar digital ne"}},{"id":"equine-medicine--equine-poa--pe-lameness-diagnostic-workflow-กรอบ-poa--v2","statement":"การตอบสนองต่อ perineural analgesia (palmar digital หรือ abaxial sesamoid block) บอกได้เพียงว่า pain อยู่ในเท้า แต่ไม่น่าเชื่อถือพอที่จะแยกว่า pain มาจาก distal interphalangeal joint (coffin joint) หรือจาก navicular bursa","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35488427","locator":"Equine Vet J 2023;55(2):253-260, Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Our results suggest that perineural analgesia is not reliable enough to differentiate pain originating from DIPJ and NB. Early evaluation of the DIPJ-A and NB-A can determine the origin of the pain."}},{"id":"equine-medicine--equine-poa--pe-lameness-diagnostic-workflow-กรอบ-poa--v3","statement":"เมื่อทำ intra-synovial analgesia ผลของ navicular bursa block จะดีขึ้นแล้วคงที่ ส่วนผลของ distal interphalangeal joint block ยังเปลี่ยนแปลงต่อได้ถึง 10 นาที จึงควรอ่านผล DIPJ block ตั้งแต่ระยะแรก (2 และ 5 นาที)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35488427","locator":"Equine Vet J 2023;55(2):253-260, Results and Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A positive NB-A produced a high degree of improvement that remained stable, whereas the DIPJ-A improved over time... An improvement following NB-A was constant over time, but an improvement following DIPJ-A varied by up to 10 min."}}]},"equine-medicine--equine-poa--poa-answer-key-station-2-lameness-video-questions":{"claims":[{"id":"equine-medicine--equine-poa--poa-answer-key-station-2-lameness-video-questions--v1","statement":"ในม้าที่พบ radiographic abnormality ของ navicular bone 35 ตัว มี 25 ตัว (71%) ที่เห็นรอยโรคได้เฉพาะในท่า palmaroproximal-palmarodistal oblique เท่านั้น ดังนั้นการถ่ายภาพรังสียืนยัน navicular disease ต้องมีท่านี้เสมอ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8467786","locator":"Equine Vet J 1993;25(2):93-8, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Radiographic abnormalities of the navicular bone in the lame or lamer limb were detected in 35 horses, all of which showed some response to analgesia of the navicular bursa. In 25 of these horses (71%) changes were only identifiable in the "}},{"id":"equine-medicine--equine-poa--poa-answer-key-station-2-lameness-video-questions--v2","statement":"การให้ lameness grade แบบ subjective ตาม AAEP lameness scale มี inter-observer agreement ต่ำเมื่อ lameness เบา (mean score ≤ 1.5 agreement 61.9%, kappa 0.23) แต่สูงเมื่อ mean score > 1.5 (agreement 93.1%, kappa 0.86)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20156242","locator":"Equine Vet J 2010;42(2):92-7, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"When the mean AAEP lameness score was >1.5 clinicians agreed whether or not a limb was lame 93.1% of the time (kappa= 0.86), but when the mean score was < or = 1.5 they agreed 61.9% (kappa= 0.23) of the time."}}]},"equine-medicine--equine-poa--poa1-ม้าผอม-มีจุดเลือดออกที่-vulva-mucosa":{"claims":[{"id":"equine-medicine--equine-poa--poa1-ม้าผอม-มีจุดเลือดออกที่-vulva-mucosa--v1","statement":"AGID เป็นการทดสอบที่จำเพาะสำหรับ equine infectious anaemia และมีข้อได้เปรียบคือแยกปฏิกิริยาของ EIA ออกจากปฏิกิริยา antigen-antibody อื่นได้ อีกทั้งยังใช้ยืนยันผล ELISA ที่เป็นบวก สนับสนุนคำตอบที่บันทึกว่าต้องตอบ AGID","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Section B. Diagnostic Techniques, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The AGID test is specific, thus has the advantage of distinguishing between EIA and non-EIA antigen-antibody reactions."}}]},"equine-medicine--equine-poa--poa1-ต่อ-การแปลผลเลือดและการอธิบายเจ้าของ":{"claims":[{"id":"equine-medicine--equine-poa--poa1-ต่อ-การแปลผลเลือดและการอธิบายเจ้าของ--v1","statement":"ผลตรวจ EIA ที่ไม่สอดคล้องกันอธิบายได้ด้วยชีววิทยาของโรค ไม่จำเป็นต้องโทษว่าแล็บผิดพลาด WOAH ระบุว่าผลลวงเกิดได้เมื่อไวรัสที่ไหลเวียนในระยะเฉียบพลันจับแอนติบอดีที่มีอยู่ไปหมด หรือเมื่อระดับแอนติบอดีเริ่มต้นไม่เคยสูงพอที่จะตรวจพบ สนับสนุนคำตอบที่บันทึกว่าติดเชื้อจริงแต่ปริมาณเชื้อหรือแอนติบอดียังน้อย","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2019","locator":"Section B. Diagnostic Techniques, page 2","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"misleading results may occur when the level of virus circulating in the blood during an acute episode of the disease is sufficient to bind available antibody, and if initial antibody levels never rise high enough to be detectable"}}]},"equine-medicine--equine-poa--poa2-ม้าขาหลังซ้ายบวม":{"claims":[{"id":"equine-medicine--equine-poa--poa2-ม้าขาหลังซ้ายบวม--v1","statement":"การหักของ proximal sesamoid bone วินิจฉัยและจำแนกชนิดด้วยภาพรังสีที่ข้อ metacarpophalangeal และ metatarsophalangeal จริง และชิ้นกระดูกแบบ abaxial ที่นำออกด้วยการส่องกล้องข้อมีพยากรณ์โรคดีสำหรับการกลับไปแข่ง ยืนยันว่า fracture of proximal sesamoid bone เป็นคำวินิจฉัยที่เข้ากับรอยโรคที่ fetlock","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9777001","locator":"Vol 213(7):1016-21, Procedure and Conclusions","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Information obtained from dorsopalmar and dorsoplantar radiographic views of metacarpophalangeal and metatarsophalangeal joints was used to classify fractures ... horses with abaxial fractures of the proximal sesamoid bone have a favorable "}}]},"equine-medicine--equine-poa--post-operative-care-nsaid-abo-จากเคสจริง":{"claims":[{"id":"equine-medicine--equine-poa--post-operative-care-nsaid-abo-จากเคสจริง--v1","statement":"การติดเชื้อราหรือยีสต์ในมดลูกม้าเป็นภาวะที่มีอยู่จริง Candida albicans เป็นหนึ่งในหกชนิดของจุลชีพที่แยกได้จากม้าที่มี clinical endometritis สนับสนุนผลการตรวจในเคสที่บันทึกว่าเจอการติดเชื้อราในมดลูก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38430797","locator":"Vol 219:132-137, Methods","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"6 different species of microorganisms isolated from mares with clinical endometritis, namely Escherichia coli, Staphylococcus aureus, Streptococcus equi subsp. Zooepidemicus, Pseudomonas aeruginosa, Klebsiella pneumoniae and Candida albican"}}]},"equine-medicine--equine-poa--เคสตัดก้อน-melanoma":{"claims":[{"id":"equine-medicine--equine-poa--เคสตัดก้อน-melanoma--v1","statement":"ม้าสีเทาเป็นกลุ่มเสี่ยงของ melanoma จริง ในชุดเคส metastatic melanoma 14 ตัว ทุกตัวเป็นม้าสีเทาสูงอายุ อายุเฉลี่ย 16 ปี และตำแหน่งของก้อนปฐมภูมิที่พบบ่อยที่สุดคือใต้โคนหาง perineum และต่อมน้ำลาย parotid ตรงกับตำแหน่ง perineal mass ในเคส","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12141308","locator":"Vol 16(4):452-6, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All were older gray horses, with an average age of 16 years. The most common sites of primary tumors were the ventral tail, perineum, and parotid salivary gland."}},{"id":"equine-medicine--equine-poa--เคสตัดก้อน-melanoma--v2","statement":"มีวัคซีน melanoma ใช้ในม้าจริง คือ ONCEPT ซึ่งเป็นวัคซีน human tyrosinase ที่ใช้เป็นการรักษาเชิงระบบ แต่ผลยังไม่แน่นอน ในชุดเคส 8 ตัวมีเพียง 4 ตัวที่ก้อนโตช้าลง หยุดโต หรือเล็กลง และครึ่งหนึ่งมีผลข้างเคียง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39623874","locator":"Vol 166(12):648-656, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Vaccination with human tyrosinase, ONCEPT vaccine, is a newer type of systemic melanoma therapy ... In half of the horses (4) a positive change in tumor growth in the sense of retardation, stagnation and, in one of these horses, even reduct"}}]},"equine-medicine--equine-poa--การจัดการที่เหมาะสมสำหรับปัญหาโคลิกในม้า":{"claims":[{"id":"equine-medicine--equine-poa--การจัดการที่เหมาะสมสำหรับปัญหาโคลิกในม้า--v1","statement":"การให้ NSAID ซ้ำ ๆ เกินขนาดเป็นพิษรุนแรงจริง phenylbutazone ขนาด 10 มก./กก. วันละครั้งนาน 14 วันทำให้ม้าแคระตาย 6 จาก 10 ตัว แต่รอยโรคหลักคือแผลในช่องปากและทางเดินอาหารร่วมกับการเปลี่ยนแปลงที่ไต จึงไม่ควรอธิบายอันตรายของยาแก้ปวดว่าเป็นเรื่องไตอย่างเดียว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-6660616","locator":"Vol 44(12):2277-9, Abstract","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Six ponies died in 7 to 20 days; 1 pony was euthanatized during an acute abdominal crisis; and 3 ponies survived the study. At necropsy, the major lesions were oral and gastrointestinal ulcerations and renal changes."}},{"id":"equine-medicine--equine-poa--การจัดการที่เหมาะสมสำหรับปัญหาโคลิกในม้า--v2","statement":"การใช้อาการทางคลินิกที่ตรวจได้ในภาคสนามมาตัดสินใจส่งผ่าตัดมีหลักฐานรองรับ บทปริทัศน์ระบุว่าพารามิเตอร์ทางคลินิกก่อนผ่าตัดบางอย่างของ acute abdomen ในม้า ซึ่งหลายอย่างใช้เทคนิคที่สัตวแพทย์ภาคสนามทำได้ มี positive predictive value สูงต่อความจำเป็นในการผ่าตัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30808489","locator":"Vol 34:1-9, Results","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There is a high positive predictive value of specific clinical preoperative parameters of the equine acute abdomen, many of which rely on techniques available to field practitioners, relative to the need for surgical intervention."}}]}},"equine-medicine--equine-lapove":{"equine-medicine--equine-lapove--title-lecturer":{"claims":[{"id":"equine-medicine--equine-lapove--title-lecturer--v1","statement":"ข้อบ่งชี้ของ laparoscopic ovariectomy ในม้า ได้แก่ การทำหมัน (neutering) ปัญหา fertility การกำจัดพฤติกรรมผิดปกติที่สัมพันธ์กับฮอร์โมน ovarian tumour และ ovarian haematoma หรือ cyst ที่ไม่ยุบเอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22092147","locator":"Vet Surg 2011;40(8):1009-14, Methods","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Indications for surgery were neutering, fertility problems, elimination of hormone-related abnormal behavior, ovarian tumors as well as nonregressive ovarian hematomas or cysts."}}]},"equine-medicine--equine-lapove--01-laparoscopic-fundamental-mis-principles":{"claims":[{"id":"equine-medicine--equine-lapove--01-laparoscopic-fundamental-mis-principles--v1","statement":"Laparoscopic ovariectomy ทำได้ในม้ายืน sedate โดยมี morbidity ต่ำ จากรายงาน 157 ตัว มีม้าเกิดภาวะแทรกซ้อนหลังผ่าตัด 17 ตัว (10.8%) เช่น incisional drainage, incisional infection, seroma, dehiscence, ไข้ชั่วคราว และปวดท้องเล็กน้อย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22092147","locator":"Vet Surg 2011;40(8):1009-14, Results and Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Seventeen mares (10.8%) developed postoperative complications (eg, incisional drainage, incisional infection, seroma formation, dehiscence, transient fever and mild abdominal discomfort)... Laparoscopic ovariectomy in standing sedated mares"}},{"id":"equine-medicine--equine-lapove--01-laparoscopic-fundamental-mis-principles--v2","statement":"ในม้าที่ผ่าตัด laparoscopic ovariectomy ภาวะแทรกซ้อนที่แผล flank พบเฉพาะในม้าที่มี ovary ขนาดมากกว่า 12 ซม. และ 15 ใน 17 ตัวนั้น (88%) ใช้ electrosurgical instrument ในการ dissect mesovarium","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22092147","locator":"Vet Surg 2011;40(8):1009-14, Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All mares with flank incisional problems had ovarian size >12 cm and in 15 (88%) of these mares electrosurgical instruments were used for mesovarial dissection."}}]},"equine-medicine--equine-lapove--case-study-ovariectomy-steps":{"claims":[{"id":"equine-medicine--equine-lapove--case-study-ovariectomy-steps--v1","statement":"Standing laparoscopic ovariectomy เข้าถึง ovary ผ่าน 3 portal ต่อข้าง คือ 2 portal ที่ paralumbar fossa และอีก 1 portal ระหว่างซี่โครงที่ 17 และ 18 ข้างเดียวกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20459500","locator":"Vet Surg 2010;39(6):737-41, Methods","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Ovaries were approached via 3 portal sites, 2 in the paralumbar fossa and a 3rd between the 17th and 18th ribs on the ipsilateral side."}},{"id":"equine-medicine--equine-lapove--case-study-ovariectomy-steps--v2","statement":"Pneumoperitoneum ด้วย CO2 ที่ความดัน 15 mmHg ในม้ายืนที่ sedate ด้วย detomidine 0.02 มก./กก. ร่วมกับ butorphanol 0.02 มก./กก. IV ไม่ทำให้เกิดผลเสียต่อ cardiopulmonary function, blood gas, haematology หรือ plasma chemistry แต่กระตุ้น inflammatory response เล็กน้อยในช่องท้อง (total nucleated cell count ใน peritoneal fluid สูงขึ้นที่ 24 ชั่วโมง)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12755432","locator":"Equine Vet J 2003;35(3):283-90, Methods, Results and Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pneumoperitoneum with CO2 during standing laparoscopy in healthy horses does not cause adverse alterations in cardiopulmonary, haematology or plasma chemistry variables, but does induce a mild inflammatory response within the peritoneal cav"}},{"id":"equine-medicine--equine-lapove--case-study-ovariectomy-steps--v3","statement":"ขั้นตอนสำคัญคือทำให้ mesovarium ชาด้วยยาชาเฉพาะที่ก่อน แล้วจึงตัดแยกด้วย vessel sealing device ปล่อย ovary ค้างไว้ในช่องท้อง ก่อนนำออกในขั้นตอนถัดไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-24962687","locator":"Vet Surg 2014;43(6):663-7, Methods","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After sedation, 3 laparoscopic portals were made in the paralumbar fossa. The mesovarium was desensitized and dissected using a vessel sealing device, and the ovary was left free in the abdomen."}}]}},"equine-medicine--equine-farabella":{"equine-medicine--equine-farabella--lecture-content-จาก-pdf-preview":{"claims":[{"id":"equine-medicine--equine-farabella--lecture-content-จาก-pdf-preview--v1","statement":"Complicated mandibular fracture ในม้าซ่อมได้ด้วย locking compression plate (LCP) osteosynthesis โดยใช้ LCP ขนาด 4.5/5.0 มม. จำนวน 1-3 แผ่นที่ด้าน ventral, lateral หรือ caudal ของ mandible (ในลูกม้าใช้ LCP 3.5 มม. 2 แผ่น) รายงาน 6 ตัวหายสนิททุกตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19151871","locator":"Vet Comp Orthop Traumatol 2009;22(1):54-8, Methods and Results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Each horse underwent locking compression plate (LCP) osteosynthesis consisting of open fracture reduction and application of one to three 4.5/5.0 mm LCP at the ventral, lateral or caudal aspect of the mandible under fluoroscopic control. Tw"}},{"id":"equine-medicine--equine-farabella--lecture-content-จาก-pdf-preview--v2","statement":"Fracture ของส่วน rostral ของ mandible และ maxilla ในม้า 89 ตัว เกิด short-term complication 24 ตัว (27%) โดย soft tissue infection และ wire loosening หรือ wire failure พบบ่อยที่สุด แต่ long-term functional และ cosmetic outcome ดีในทุก fracture type และทุกวิธีซ่อม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10363097","locator":"J Am Vet Med Assoc 1999;214(11):1648-52, Results and Conclusions","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Short-term complications developed in 24 of 89 (27%) horses. Soft tissue infections and wire loosening or failure were the most common short-term and long-term complications... Long-term functional and cosmetic outcomes were favorable for a"}}]},"equine-medicine--equine-farabella--falabella-breed-orthopedic-relevance":{"claims":[{"id":"equine-medicine--equine-farabella--falabella-breed-orthopedic-relevance--v1","statement":"Chondrodysplastic dwarfism ใน Miniature horse เป็น autosomal recessive disorder ที่สัมพันธ์กับ mutation ในยีน aggrecan (ACAN)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34281639","locator":"J Equine Vet Sci 2021;103:103643, Introduction","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In Miniature horses, dwarfism can occur as chondrodysplastic dwarfism, an autosomal recessive disorder associated with five mutations (D1, D2, D3*, D4 and c.6465A > T variant) in the aggrecan (ACAN) gene."}},{"id":"equine-medicine--equine-farabella--falabella-breed-orthopedic-relevance--v2","statement":"Miniature horse ที่เป็น chondrodysplastic dwarf ในรายงาน genotype D4/D4 มีลักษณะ domed head ที่ใหญ่ผิดสัดส่วนกับลำตัว, mandibular prognathism และขาสั้นโค้ง โดยเฉพาะบริเวณ proximal ของ metatarsal bone ภาพรังสีพบขอบ subchondral bone ของ long bone ไม่เรียบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31906815","locator":"J Vet Diagn Invest 2020;32(1):99-102, Case description","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Clinically, the 2 dwarfs had a domed head that was large compared to the rest of the body, mandibular prognathism, and short and bowed limbs, mainly in the proximal region of the metatarsal bones. Radiographic examination revealed contour i"}}]}},"equine-medicine--equine-intro":{"equine-medicine--equine-intro--สมุดประจำตัวม้า-equine-passport":{"claims":[{"id":"equine-medicine--equine-intro--สมุดประจำตัวม้า-equine-passport--v1","statement":"การประมาณอายุจากฟันไม่สามารถให้อายุที่แม่นยำได้ เพราะความแปรผันระหว่างตัวสูงมาก จึงกำหนดอายุเจาะจงจากเกณฑ์ทางฟันไม่ได้ ตรงกับข้อกำหนดในสมุดที่ต้องกำกับว่าเป็น estimated by dental","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8533255","locator":"Conclusions; 137(5):117-21","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The results show that specific ages cannot be assigned to these dental criteria owing to the wide variation between horses, and that as a result the estimation of age from dentition can never be precise."}},{"id":"equine-medicine--equine-intro--สมุดประจำตัวม้า-equine-passport--v2","statement":"เมื่อเทียบกับม้า 434 ตัวที่ทราบอายุจริง ทั้งสัตวแพทย์ผู้มีประสบการณ์และแบบจำลองทางสถิติต่างประมาณอายุจากฟันได้ไม่ถึงระดับความแม่นยำที่ยอมรับได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8540206","locator":"Results; 137(6):139-40","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There was little difference between the accuracy of the computer model and the human observers, and neither method provided an acceptable level of accuracy for ageing horses from their dentition."}}]},"equine-medicine--equine-intro--สีขนม้า-coat-colours":{"claims":[{"id":"equine-medicine--equine-intro--สีขนม้า-coat-colours--v1","statement":"สี Dun เป็นสีขนแบบ wild type ที่เกิดจากการเจือจางของเม็ดสีร่วมกับ primitive markings คือแถบสีเข้ม เช่น เส้นกลางหลังและ leg barring กลไกคือการแสดงออกเฉพาะที่ของยีน TBX3 ในรูขุมขนทำให้เม็ดสีสะสมในเส้นขนแบบไม่สมมาตร","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26691985","locator":"Abstract; 48(2):152-8","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dun is a wild-type coat color in horses characterized by pigment dilution with a striking pattern of dark areas termed primitive markings."}},{"id":"equine-medicine--equine-intro--สีขนม้า-coat-colours--v2","statement":"สี Grey ในม้าคือการที่ขนขาวขึ้นตามอายุ ถ่ายทอดแบบ autosomal dominant จาก duplication ขนาด 4.6 kb ใน intron 6 ของยีน STX17 และสัมพันธ์กับอุบัติการณ์ melanoma และรอยด่างขาวคล้าย vitiligo ที่สูง จึงไม่ใช่แค่ลักษณะสีขนเฉย ๆ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18641652","locator":"Abstract; 40(8):1004-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In horses, graying with age is an autosomal dominant trait associated with a high incidence of melanoma and vitiligo-like depigmentation. Here we show that the Gray phenotype is caused by a 4.6-kb duplication in intron 6 of STX17 (syntaxin-"}}]},"equine-medicine--equine-intro--white-markings-ขวัญ-และวิธีลงบันทึกในสมุด":{"claims":[{"id":"equine-medicine--equine-intro--white-markings-ขวัญ-และวิธีลงบันทึกในสมุด--v1","statement":"ตำแหน่งและจำนวนขวัญเป็นลักษณะที่มีพื้นฐานทางพันธุกรรม โดย GWAS ในม้า Quarter Horse 342 ตัวพบ genomic windows ที่อธิบาย additive variance ได้ 20 ถึง 80% ของแต่ละลักษณะ และขวัญสัมพันธ์กับพฤติกรรม อารมณ์ และ laterality ของม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34679946","locator":"Abstract; 11(10):2925","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The position and number of hair whorls have been associated with the behavior, temperament, and laterality of horses ... The windows accounted for 20-80% of additive variance for each trait analyzed."}}]},"equine-medicine--equine-intro--การฝังไมโครชิพ-และวัคซีนม้าในไทย":{"claims":[{"id":"equine-medicine--equine-intro--การฝังไมโครชิพ-และวัคซีนม้าในไทย--v1","statement":"Japanese encephalitis virus ก่อโรคสมองอักเสบเฉียบพลันรุนแรงในทั้งคนและม้า และการสำรวจซีรัมในกรุงเทพมหานครพบ seroprevalence สูงถึง 51% ในสุนัขที่ใช้เป็น sentinel บ่งชี้ว่าความเสี่ยงการติดเชื้อในเมืองหลวงยังสูง สนับสนุนการบรรจุวัคซีน JE ไว้ในโปรแกรมวัคซีนม้าในประเทศไทย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23046992","locator":"Abstract; 187(1):85-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Japanese encephalitis virus (JEV) causes serious acute encephalitis in humans and horses ... The IgG ELISA was used to survey dogs in Bangkok, Thailand and 51% of these dogs were found seropositive for JEV."}}]},"equine-medicine--equine-intro--พฤติกรรมและการมองเห็นของม้า":{"claims":[{"id":"equine-medicine--equine-intro--พฤติกรรมและการมองเห็นของม้า--v1","statement":"ม้าต้องนอนลงเท่านั้นจึงจะเข้าสู่ REM sleep ได้ ถ้านอนลงไม่นานพอจะเกิดภาวะอดนอนจนล้มลงโดยควบคุมไม่ได้และเสี่ยงบาดเจ็บ ดังนั้นการยืนหลับที่สไลด์กล่าวถึงทดแทนการนอนลงไม่ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38163442","locator":"Background; 57(1):277-281","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses must lie down to go into vital rapid-eye movement (REM) sleep. If they are not lying down for sufficiently long periods they can become so sleep-deprived that they collapse uncontrollably, which results in a risk of injuries."}}]},"equine-medicine--equine-intro--การจับบังคับทางกายภาพ-physical-restraint":{"claims":[{"id":"equine-medicine--equine-intro--การจับบังคับทางกายภาพ-physical-restraint--v1","statement":"คณะผู้เชี่ยวชาญนานาชาติที่ประเมินสวัสดิภาพด้วย Five Domains Model จัดให้ ear twitch เป็นวิธีที่ส่งผลลบต่อสวัสดิภาพมากที่สุดในบริบทการจับบังคับเพื่อการจัดการ ที่คะแนน 8 จาก 10 สนับสนุนที่สไลด์จัดให้เป็นวิธีที่ใช้ไม่บ่อยและสงวนไว้กับม้าที่ดื้อมาก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29562654","locator":"Results, context C9; 8(3):41","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most severe (median and interquartile range, IQR) impacts within each context were identified during the workshop as: ... C9 ear twitch (8 IQR 1)"}},{"id":"equine-medicine--equine-intro--การจับบังคับทางกายภาพ-physical-restraint--v2","statement":"การใช้ lip twitch ในแม่ม้าระหว่างการผสมพันธุ์แบบจูงมือทำให้ระดับ cortisol ในน้ำลายสูงขึ้นอย่างมีนัยสำคัญ คือมีความเครียดระดับเล็กน้อย ส่วน hobble ใช้ไม่ได้เลยในแม่ม้า 2 จาก 10 ตัวที่ไม่ยอมรับวิธีนี้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40891633","locator":"Results; 58(4):1116-1126","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Using the lip twitch increased cortisol concentrations (with twitch from 0.77 to 1.20 ng/mL vs. without twitch from 0.73 ng/mL to 0.99 ng/mL; p = 0.04), and the hobbles could not be applied to 2 out of the 10 mares in our study, as they did"}},{"id":"equine-medicine--equine-intro--การจับบังคับทางกายภาพ-physical-restraint--v3","statement":"เมื่อเปรียบเทียบ nose twitch, ear hold, Stableizer และไม่จับบังคับเลย ในม้าที่ไม่ได้ให้ยาซึมระหว่างส่องกล้องทางเดินหายใจส่วนต้น ไม่พบความแตกต่างของประสิทธิภาพหรือการตอบสนองทาง neuroendocrine ม้าแต่ละตัวตอบสนองต่างกันมาก ผลจึงไม่สนับสนุนการชี้ว่าวิธีใดวิธีหนึ่งดีกว่าเสมอไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40922053","locator":"Results and conclusions; 58(4):1103-1115","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Horses demonstrated strong individual differences for procedure tolerance and preferred method of restraint, but there were no differences observed in outcome measures related to procedural efficacy or neuroendocrine response associated wit"}}]},"equine-medicine--equine-intro--การจับบังคับด้วยยา-chemical-restraint":{"claims":[{"id":"equine-medicine--equine-intro--การจับบังคับด้วยยา-chemical-restraint--v1","statement":"การให้ acepromazine ซึ่งเป็น phenothiazine tranquilizer สัมพันธ์กับ penile prolapse ที่คงอยู่นาน มีรายงานผู้ป่วยที่องคชาตยื่นนาน 12 วันหลังได้รับยา ยืนยันภาวะแทรกซ้อนที่สไลด์เตือนไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9290825","locator":"Abstract; 211(5):587-9","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Prolonged penile prolapse in horses has been reported in association with administration of phenothiazine tranquilizers, trauma, neuropathies, severe general debilitation or exhaustion, starvation, rabies, herpes myeloencephalitis, equine i"}},{"id":"equine-medicine--equine-intro--การจับบังคับด้วยยา-chemical-restraint--v2","statement":"ยากลุ่ม alpha-2 agonist รวมทั้ง xylazine และ detomidine ให้ฤทธิ์ระงับปวดที่แรง แต่ทำให้เกิดความดันสูง หัวใจเต้นช้า atrioventricular block การซึมมากเกินไป และ ataxia ซึ่งเป็นข้อจำกัดของการใช้ ตรงกับที่สไลด์ระบุว่ากลุ่มนี้ทำให้เกิด ataxia ต่างจาก acepromazine","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21056297","locator":"Abstract; 26(3):515-32","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Alpha-2 agonists, such as xylazine, clonidine, romifidine, detomidine, medetomidine, and dexmedetomidine, are potent analgesic drugs that also induce physiologic and behavioral changes, such as hypertension, bradycardia, atrioventricular bl"}},{"id":"equine-medicine--equine-intro--การจับบังคับด้วยยา-chemical-restraint--v3","statement":"detomidine ในรูป oromucosal gel ให้ใต้ลิ้นขนาด 40 ไมโครกรัมต่อกิโลกรัม ทำให้ม้าซึมได้อย่างปลอดภัย มี bioavailability ประมาณ 22% เทียบกับ 38% ทาง IM และการดูดซึมที่ช้ากว่าทำให้ผลข้างเคียงน้อยและรุนแรงน้อยกว่าทาง IM สนับสนุนการใช้เจลอมใต้ลิ้นสำหรับ standing sedation","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21219348","locator":"Results and conclusion; 34(1):76-81","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Mean bioavailability of detomidine was 22% after sublingual administration and 38.2% after intramuscular administration ... Sublingual administration of detomidine oromucosal gel at 40 mcg/kg produces safe sedation in horses."}}]},"equine-medicine--equine-intro--stomach-tubing-nasogastric":{"claims":[{"id":"equine-medicine--equine-intro--stomach-tubing-nasogastric--v1","statement":"Aspiration pneumonia เป็นภาวะแทรกซ้อนหลักของการอุดตันหลอดอาหาร และความเสี่ยงสัมพันธ์กับระยะเวลาที่อุดตันก่อนได้รับการแก้ไข โดยม้าที่เกิดปอดอักเสบมีระยะเวลาอุดตันมัธยฐาน 18 ชั่วโมง เทียบกับ 4 ชั่วโมงในม้าที่ไม่เกิด จึงต้องรีบแก้ choke","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-10738598","locator":"Results; 41(3):207-10","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The duration of esophageal obstruction prior to admission was significantly longer in horses that developed aspiration pneumonia (median 18, range 2-48 h) than in those horses that did not (median 4, range 0.5-48 h)."}},{"id":"equine-medicine--equine-intro--stomach-tubing-nasogastric--v2","statement":"ในม้า 109 ตัวที่มีการอุดตันหลอดอาหาร อัตราการหายใจที่เพิ่มขึ้นเกิน 22 ครั้งต่อนาที และการปนเปื้อนในหลอดลมระดับปานกลางถึงรุนแรง เพิ่มความเสี่ยงของ aspiration pneumonia อย่างมีนัยสำคัญ จึงเป็นสัญญาณที่ต้องเฝ้าระวังหลังทำหัตถการทางเดินอาหารส่วนต้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20707844","locator":"Results; 24(5):1147-52","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Increased respiratory rate (>22 breaths/min) and moderate or severe tracheal contamination, although not associated with complications as a whole, significantly increased the risk of developing aspiration pneumonia"}}]},"equine-medicine--equine-intro--problem-oriented-approach-และการซักประวัติ":{"claims":[{"id":"equine-medicine--equine-intro--problem-oriented-approach-และการซักประวัติ--v1","statement":"ความชุกและความรุนแรงของ equine gastric ulceration syndrome สัมพันธ์กับชนิดของการฝึกและรูปแบบการจัดการ โดยพบสูงถึง 93% ในม้าแข่งพันธุ์ Thoroughbred สนับสนุนการซักประวัติ working ว่าม้าถูกใช้งานแบบใดและหนักแค่ไหน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19927579","locator":"Background; 41(7):625-30","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The prevalence (up to 93% in Thoroughbred racehorses) and severity of equine gastric ulceration syndrome (EGUS) has been associated with type of training and differing management practices."}}]},"equine-medicine--equine-intro--normal-vital-signs-และลำดับการตรวจร่างกาย":{"claims":[{"id":"equine-medicine--equine-intro--normal-vital-signs-และลำดับการตรวจร่างกาย--v1","statement":"ในม้าที่ไม่ได้ให้ยาซึมและถูกทำหัตถการ วัดค่า minimum heart rate เฉลี่ยได้ 34.2 ครั้งต่อนาที และลดลงเหลือ 30.1 ครั้งต่อนาทีเมื่อม้าคุ้นเคยกับหัตถการมากขึ้น ซึ่งอยู่ในช่วง HR 28 ถึง 44 ที่สไลด์ระบุ และแสดงว่าความคุ้นเคยกับสถานการณ์มีผลต่อค่าที่วัดได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-40922053","locator":"Results; 58(4):1103-1115","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Repetition of experimental procedures was associated with a progressive decrease in mean (95% CI) minimum heart rate from 34.2 (31.7-36.7) to 30.1 (28.0-32.2) bpm (p < 0.001)"}}]},"equine-medicine--equine-intro--อุปกรณ์ม้า-tack-และส่วนประกอบของบังเหียน":{"claims":[{"id":"equine-medicine--equine-intro--อุปกรณ์ม้า-tack-และส่วนประกอบของบังเหียน--v1","statement":"รูปแบบของบิท (snaffle เทียบกับ curb) ขนาดบิท แรงดึงบังเหียน และมุมของบังเหียน ล้วนมีผลต่อการเคลื่อนที่ของบิทในช่องปากม้า โดย curb bit เคลื่อนที่ได้จำกัดกว่า snaffle และไม่พบการสัมผัสเหงือกด้าน mesial ของฟัน 06 ล่าง จึงยืนยันว่าบิทสองชนิดนี้ทำงานในปากม้าต่างกันจริง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-41007896","locator":"Abstract and Results; 15(18):2648","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Similar patterns were observed with curb bits, although bit movement was more restricted, and no contact with the mesial gingival tissues of the mandibular 06s was noted."}}]},"equine-medicine--equine-intro--เทคนิคการให้ยา-iv-im-po-และ-sc":{"claims":[{"id":"equine-medicine--equine-intro--เทคนิคการให้ยา-iv-im-po-และ-sc--v1","statement":"การฉีดยาพลาดเข้า carotid artery ระหว่างการเจาะ jugular vein ในม้าเกิดขึ้นจริงและมีรายงานเป็นชุดเคส โดยอาการนำแสดงออกระหว่างหรือหลังฉีดทันที เหตุการณ์ส่วนใหญ่เกิดที่กลาง jugular groove ขณะใช้เข็มยาว 1.5 นิ้ว เบอร์ 20 และในชุด 15 เคสมีม้าตาย 1 ตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"doi-10-1111-eve-13706","locator":"Abstract; volume 35, issue 4","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"premonitory clinical signs occurred while or soon after injection"}}]}},"equine-medicine--equine-derm":{"equine-medicine--equine-derm--ซักประวัติ-และโรคตามพันธุ์-สี-อายุ":{"claims":[{"id":"equine-medicine--equine-derm--ซักประวัติ-และโรคตามพันธุ์-สี-อายุ--v1","statement":"HERDA ใน Quarter Horse เป็นโรคผิวหนังเสื่อมที่ถ่ายทอดทางพันธุกรรม (เดิมเรียก hyperelastosis cutis)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21118319","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Hereditary equine regional dermal asthenia (HERDA) in Quarter Horses is an inherited degenerative skin disease. Initially reported as hyperelastosis cutis"}}]},"equine-medicine--equine-derm--ตรวจผิวหนัง-และเก็บตัวอย่าง":{"claims":[{"id":"equine-medicine--equine-derm--ตรวจผิวหนัง-และเก็บตัวอย่าง--v1","statement":"ผล skin scraping ที่เป็นลบไม่ตัดโรค mange ออก ต้อง biopsy เพื่อวินิจฉัยได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-mange-in-horses-2023","locator":"Sarcoptic mange","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Negative skin scrapings do not exclude the disease; biopsy may establish a diagnosis."}}]},"equine-medicine--equine-derm--คันจากปรสิตภายนอกและแมลง":{"claims":[{"id":"equine-medicine--equine-derm--คันจากปรสิตภายนอกและแมลง--v1","statement":"เหาของม้ามี 2 ชนิดคือ Haematopinus asini (เหาดูดเลือด) และ Damalinia equi (เหากัด)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-lice-in-horses-and-donkeys-2023","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Haematopinus asini (the horse bloodsucking louse) and Damalinia equi (the horse biting louse)."}}]},"equine-medicine--equine-derm--hypersensitivity-culicoides-และ-atopic-dermatitis":{"claims":[{"id":"equine-medicine--equine-derm--hypersensitivity-culicoides-และ-atopic-dermatitis--v1","statement":"Insect bite hypersensitivity ของม้าเป็น allergic dermatitis แบบ IgE-mediated ที่เกิดจากการถูกริ้น Culicoides spp. กัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-39403119","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Insect bite hypersensitivity (IBH) is an IgE-mediated allergic dermatitis of horses caused by bites of Culicoides spp."}}]},"equine-medicine--equine-derm--สะเก็ดและขุย-dermatophytosis-และ-dermatophilosis":{"claims":[{"id":"equine-medicine--equine-derm--สะเก็ดและขุย-dermatophytosis-และ-dermatophilosis--v1","statement":"Trichophyton equinum เป็นสาเหตุหลักของ dermatophytosis ในม้า","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-dermatophytosis-in-horses-2025","locator":"Overview","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Trichophyton equinum and T mentagrophytes are the primary causes of dermatophytosis in horses"}}]},"equine-medicine--equine-derm--erosion-habronemiasis-และ-coital-exanthema":{"claims":[{"id":"equine-medicine--equine-derm--erosion-habronemiasis-และ-coital-exanthema--v1","statement":"Equine coital exanthema (EHV-3) ไม่มีวัคซีนหรือการรักษาจำเพาะ และแนะนำให้พักการผสมพันธุ์เพื่อให้รอยโรคหายและป้องกันการแพร่โรค","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-equine-coital-exanthema-2024","locator":"Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"There are no vaccines or specific treatments. Sexual rest is recommended to allow lesions to heal and to prevent disease transmission."}}]},"equine-medicine--equine-derm--ขนผิดปกติ-ppid-equine-cushing-s-disease":{"claims":[{"id":"equine-medicine--equine-derm--ขนผิดปกติ-ppid-equine-cushing-s-disease--v1","statement":"Pergolide เริ่มขนาด 2 mcg/kg PO ทุก 24 ชั่วโมง แล้วปรับตามการตอบสนอง เป็นการรักษา PPID","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-hypertrichosis-associated-with-adenomas-of-the-pars-inte","locator":"Treatment","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pergolide (starting dosage, 2 mcg/kg, PO, every 24 hours, then titrated according to individual response)"}}]},"equine-medicine--equine-derm--เนื้องอก-sarcoid-และ-papillomatosis":{"claims":[{"id":"equine-medicine--equine-derm--เนื้องอก-sarcoid-และ-papillomatosis--v1","statement":"Bovine papillomavirus (BPV) โดยเฉพาะ type 1 และ 2 ถือเป็นสาเหตุหลักของ equine sarcoid","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-equine-sarcoids-2021","locator":"Etiology","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Bovine papillomavirus (BPV), primarily types 1 and 2, is now considered the main etiologic agent of equine sarcoids."}}]},"equine-medicine--equine-derm--เนื้องอก-scc-melanoma-และ-eosinophilic-granuloma":{"claims":[{"id":"equine-medicine--equine-derm--เนื้องอก-scc-melanoma-และ-eosinophilic-granuloma--v1","statement":"เนื้องอก melanocytic ส่วนใหญ่ในม้าพบในม้าสีเทา (gray) ที่ขนเปลี่ยนเป็นเทาหรือขาวตามอายุ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"web-tumors-of-melanocytic-origin-in-animals-2021","locator":"Tumors of Melanocytic Origin in Horses","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most melanocytic neoplasms are in gray horses, in which the coat turns gray (or white) with age."}}]}},"equine-medicine--equine-surgery-wound":{"equine-medicine--equine-surgery-wound--การไหลของงานในโรงพยาบาล-ห้องเตรียม-checklist-ห้อง-induction":{"claims":[{"id":"equine-medicine--equine-surgery-wound--การไหลของงานในโรงพยาบาล-ห้องเตรียม-checklist-ห้อง-induction--v1","statement":"การใช้ surgical safety checklist (WHO) ลดอัตราตายจาก 1.5% เป็น 0.8% (หลักฐานจากศัลยกรรมในคน; แนวคิด sign in / time out / sign out)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19144931","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The rate of death was 1.5% before the checklist was introduced and declined to 0.8% afterward"}}]},"equine-medicine--equine-surgery-wound--ระยะการหายของแผล-และม้าเทียบ-pony":{"claims":[{"id":"equine-medicine--equine-surgery-wound--ระยะการหายของแผล-และม้าเทียบ-pony--v1","statement":"การหายแบบ second intention เร็วกว่าในม้า pony เมื่อเทียบกับม้า และเร็วกว่าที่แผลลำตัวเมื่อเทียบกับแผลที่ขา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15691597","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Second-intention repair is faster in ponies than in horses and faster in body wounds than in limb wounds."}}]},"equine-medicine--equine-surgery-wound--เลือกวิธีปิดแผล-ไหม-รูปแบบการเย็บ-และ-drain":{"claims":[{"id":"equine-medicine--equine-surgery-wound--เลือกวิธีปิดแผล-ไหม-รูปแบบการเย็บ-และ-drain--v1","statement":"การเลือกชนิดการปิดแผลหรือการหายของแผลที่เหมาะสมต้องพิจารณาลักษณะของแต่ละแผลเป็นรายกรณี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30342805","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"providing the tools to decide which type of closure or healing is best in a given situation...Each wound must be considered as a unique problem"}}]},"equine-medicine--equine-surgery-wound--dressing-การจำกัดการขยับ-และ-exuberant-granulation-tissue":{"claims":[{"id":"equine-medicine--equine-surgery-wound--dressing-การจำกัดการขยับ-และ-exuberant-granulation-tissue--v1","statement":"ใน limb wound ของม้า inflammatory response ที่อ่อนและเรื้อรังยับยั้ง wound contraction และทำให้เกิด exuberant granulation tissue","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15691597","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In horses,leukocytes produce fewer mediators, initiating a weak inflammatory response, which becomes chronic. This inhibits wound contraction and gives rise to the formation of exuberant granulation tissue."}}]},"equine-medicine--equine-surgery-wound--การพันแผล-หลัก-3-ชั้น-และพันตามตำแหน่ง":{"claims":[{"id":"equine-medicine--equine-surgery-wound--การพันแผล-หลัก-3-ชั้น-และพันตามตำแหน่ง--v1","statement":"Bandage และ cast ช่วยพยุงกระบวนการหายของแผลโดยรวม แต่อาจกระตุ้น exuberant granulation tissue จึงต้องใช้อย่างระวัง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15691597","locator":"abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-11-15","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Bandages and casts stimulate the formation of exuberant granulation tissue; however, they are advantageous in many respects and play an important role in support of the overall healing process."}}]}}};
